/* =====================================================================
   Игра вдвоём: разговор с сервером.

   Этот файл — единственное место, которое знает про сеть. Правил игры
   здесь нет вовсе: их считает сервер, а мы только отправляем намерения
   («хочу сходить этой картой») и показываем то, что он ответил.

   Как всё устроено:
     1. Человек создаёт игру — сервер выдаёт код из четырёх знаков
        и пропуск. Код диктуют другу, пропуск храним у себя.
     2. Друг входит по коду, партия начинается.
     3. Дальше работает «длинный опрос»: мы спрашиваем сервер
        «что нового?», он придерживает ответ, пока за столом что-нибудь
        не произойдёт, и отвечает новым состоянием. Ответил — спрашиваем
        снова, и так всю партию.

   Почему пропуск важнее кода: код перестаёт работать, как только
   в комнату вошли двое. Вернуться в свою партию после обрыва связи
   можно только по пропуску, поэтому он лежит в памяти браузера.

   Где проходит граница с js/game.js. Стол с картами этот файл не рисует
   совсем: готовое состояние уходит в js/game.js через мост ИграПоСети —
   там его превращают в карты, подсказки и кнопки. Зато служебные экраны
   сетевого режима — «Игра с другом», плашка с кодом, вход по коду, — со
   всеми их надписями и сообщениями пишет прямо этот файл: в одиночной
   игре таких экранов нет, и js/game.js про них ничего не знает. Само
   переключение между экранами и строку связи над столом файл тоже просит
   у js/game.js через мост, а не трогает своими руками.
   ===================================================================== */

'use strict';

(function () {

  /* -------------------------------------------------------------------
     Адрес сервера
     ------------------------------------------------------------------- */

  /* Главный способ задать адрес — в самом адресе страницы:
       index.html?сервер=https://адрес-сервера
     Так его можно поменять в настройках бота (GAME_URL), не трогая код
     и не поднимая номер версии файла.

     Второй способ — вписать адрес руками прямо в игре (экран «Игра
     с другом», кнопка «Указать адрес сервера»). Он появился потому, что
     первый способ иногда отказывает целиком: адрес быстрого туннеля
     меняется при каждом запуске, а старая ссылка из закладки ведёт
     в никуда. Раньше человеку в этом случае было некуда деться — все
     объяснения советовали взять свежую ссылку у бота, и если бот молчал,
     игра вдвоём кончалась.

     Кто из двух адресов главнее. Сначала главным был адрес из ссылки —
     всегда. И это оставляло человека в тупике ровно там, где вписанный
     адрес и придумали: игра открыта из закладки или из старого сообщения
     бота, в ссылке торчит мёртвый хвостик «?сервер=», выкинуть его внутри
     Telegram нечем — и вписанный живой адрес не спасал.

     Теперь правило другое: ЖИВОЙ ПОБЕЖДАЕТ МЁРТВОГО.
       — адрес из ссылки отвечает → играем по нему. Он остаётся главным,
         и это важно: только свежая ссылка позволяет переехать на новый
         сервер, иначе однажды вписанный адрес держал бы человека вечно;
       — адрес из ссылки молчит, а вписанный отвечает → играем по вписанному;
       — молчат оба → остаёмся на адресе из ссылки и объясняем беду;
       — в ссылке адреса нет → играем по вписанному;
       — нет ни того, ни другого → запасной адрес: смотря где открыта
         страница (см. функцию «запаснойАдрес» ниже).

     Кто живой, выясняем коротким стуком в дверь. Стучимся только когда
     спорить есть о чём — адреса два и они разные. У большинства игроков
     вписанного адреса нет вовсе, спора нет, и запуск не тормозит ни на миг.

     Запасной адрес — не одна константа на всех, а правило по месту.

     Раньше запасной адрес подставлялся всегда и был «http://127.0.0.1:8765».
     Обе половины оказались неправдой. Порт: сервер игры давно живёт на 8790,
     а 8765 на машине хозяина занят вовсе чужой программой — стук туда даёт
     самый сбивающий с толку ответ, «отвечает какая-то другая программа».
     Всегда: на телефоне 127.0.0.1 — это сам телефон, где сервера нет и быть
     не может, и молчаливая подстановка превращала честное «я не знаю адреса»
     во враньё «сервер не отвечает». Именно это враньё прочитал хозяин
     сервера, у которого сервер в этот момент работал.

     Свой компьютер (файл с диска или localhost/127.0.0.1/домашняя сеть) —
     это разработка, и там сервер правда крутится на 127.0.0.1:8790
     (константа АДРЕС_ПО_УМОЛЧАНИЮ ниже).

     Переезд игры на собственный домен (https://igra.medart.com.ua) добавил
     третий случай: там nginx отдаёт и страницы, и сервер комнат с ОДНОГО
     адреса (страницы — как есть, «/что-нового», «/ход» и прочий API —
     дальше на 127.0.0.1:8790). Значит для такой страницы сервер живёт
     ровно там же, откуда она сама пришла, — берём location.origin.

     Известные витрины без сервера (сейчас — GitHub Pages, хост «*.github.io»)
     из этого правила нарочно исключены: своего сервера там нет и не будет,
     а origin выглядит как настоящий рабочий адрес. Подставь его — и лобби
     станет само стучаться на свой же «github.io/рейтинг», получать 404
     и врать потом «сервер держится на домашнем компьютере» вместо честного
     «адреса нет». Такой странице, как и раньше, возвращаем пустую строку. */
  const АДРЕС_ПО_УМОЛЧАНИЮ = 'http://127.0.0.1:8790';

  /* ИМЕНА КЛЮЧЕЙ ПАМЯТИ — ЛАТИНИЦЕЙ, и это не вкусовщина.

     Облако Telegram принимает в имени ключа только латинские буквы, цифры,
     «_» и «-». Кириллическое имя оно отвергает молча, и запись остаётся
     лежать в одном телефоне. Плюс разнобой сам по себе стоил нам ложной
     тревоги: тестировщик искал русское имя, не нашёл и решил, что выбор
     не сохраняется вовсе.

     Старые имена лежат рядом и НЕ СТИРАЮТСЯ: человек мог открыть игру
     на другом устройстве, где страница ещё прежняя. Значение переезжает
     один раз, при первом чтении (см. «переехатьНаНовыеКлючи»). */

  /* Где лежит вписанный руками адрес сервера. Ключ общий на весь сборник:
     сервер комнат один, и дурак с шашками ходят на один и тот же. */
  const КЛЮЧ_АДРЕСА = 'server_address';
  const СТАРЫЙ_КЛЮЧ_АДРЕСА = 'подкидной-дурак:адрес-сервера';

  const ОБЫЧНОЕ_ОЖИДАНИЕ = 10 * 1000;      // сколько ждём короткий ответ
  const ОЖИДАНИЕ_ОПРОСА = 30 * 1000;       // сервер держит опрос 25 с + 5 с запас на дорогу
  const ПАУЗА_ПОСЛЕ_СБОЯ = 1000;           // первая пауза перед повтором
  const МАКСИМАЛЬНАЯ_ПАУЗА = 10 * 1000;    // дальше паузы не растут
  const ДОЛГОЕ_РАЗДУМЬЕ = 10 * 1000;       // после этого пишем «друг думает»
  const ПОКАЗ_ПРИВЕТСТВИЯ = 4000;          // сколько висит «друг пришёл»
  const ЧАСТОТА_СТРОКИ_СВЯЗИ = 1000;       // как часто освежаем надпись о связи
  /* Сервер отвечает на длинный опрос не позже чем через 25 секунд, даже
     когда новостей нет. Значит, молчание дольше этого — уже не тишина
     за столом, а оборванная связь, и человеку пора об этом сказать.
     Десять секунд сверху — запас на медленную сеть, чтобы не пугать
     человека тревогой на ровном месте. */
  const МОЛЧАНИЕ_ЭТО_ОБРЫВ = 35 * 1000;

  /* Короткая икота туннеля (см. штаб/план-друг-пропал-со-связи.md) чаще
     всего проходит сама за секунды — тревожная надпись на ровном месте
     пугает зря. Первые МЯГКАЯ_ПРОПАЖА мс после того, как соперник стал
     не на связи, пишем спокойное, и только потом — прежнее тревожное. */
  const МЯГКАЯ_ПРОПАЖА = 20 * 1000;
  const ТЕКСТ_ДРУГ_ПЕРЕПОДКЛЮЧАЕТСЯ = 'Соперник переподключается…';
  const ТЕКСТ_ДРУГ_ПРОПАЛ = 'Соперник пропал со связи — ждём, партия сохранена';

  /* Метка игры в начале startapp. Игр в сборнике несколько, а Telegram
     открывает мини-приложение всегда по одному адресу — index.html, то есть
     в дурака. Чтобы ссылка «Сыграть» из чата про шашки не привела в карты,
     впереди стоит слово игры: «shashki» — просто открыть шашки,
     «shashki_КОД-адрес» — стол шашек. Старые ссылки без метки — дурак, как
     было: слово из этого словаря никогда не совпадёт с кодом комнаты (коды —
     четыре знака заглавными и цифрами), и разделитель «_» в кодах не
     встречается. Метки латиницей: startapp других знаков не пропускает.

     Отсюда же берётся слово игры для этой страницы и ключ сохранённой
     комнаты (см. ниже). Это единственный словарь меток в браузере, но
     не во всём проекте: у сервера своя таблица server/названия.js, а у
     главной — таблица страниц СТРАНИЦЫ_ИГР_ПО_ССЫЛКЕ в js/game.js. Новая
     игра по сети добавляется строкой во все три места; что они сходятся,
     сверяют tests/названия-игр-в-приглашениях.js и
     tests/маршрут-приглашения-8-игр.js. */
  const МЕТКИ_ИГР = { shashki: 'шашки', durak: 'дурак', nardy: 'нарды', deberts: 'деберц', seabattle: 'морской-бой', domino: 'домино', catan: 'катан', monopoly: 'монополия' };

  /**
   * Во что играют на ЭТОЙ странице. Страница говорит это сама, до
   * подключения нашего файла: <script>window.ИграСтраницы='шашки'</script>.
   * Не сказала или сказала незнакомое — дурак, как было всегда: так ни одна
   * нынешняя страница и ни одна старая ссылка не меняют поведения.
   *
   * От этого слова зависят три вещи, и все три — про «не перепутать игры»:
   * метка в ссылке-приглашении, ключ сохранённой комнаты в памяти браузера
   * и поле «игра» в запросе «создать».
   */
  const ИГРА_ЭТОЙ_СТРАНИЦЫ = (function () {
    let сказано = '';
    try {
      сказано = String(window.ИграСтраницы || '').trim();
    } catch (сбой) {
      сказано = '';
    }
    for (const метка in МЕТКИ_ИГР) {
      if (МЕТКИ_ИГР[метка] === сказано) return сказано;
    }
    return 'дурак';
  })();

  /** Метка этой игры для ссылки: 'шашки' → 'shashki'. Дурак — без метки. */
  function меткаИгрыДляСсылки(игра) {
    for (const метка in МЕТКИ_ИГР) {
      if (МЕТКИ_ИГР[метка] === игра) return метка;
    }
    return '';
  }

  /* Где лежит ключ от своей партии. Пропуск — это не пароль от чего-то
     ценного: он открывает одну комнату с картами и живёт минуты.

     Ключ РАЗНЫЙ у разных игр, и это не удобство, а починка настоящей
     ошибки: с общим ключом брошенный стол дурака воскресал бы в шашках —
     страница шашек нашла бы чужой пропуск и постучалась бы с ним в комнату,
     где играют в карты. У дурака ключ остался ровно прежним, поэтому
     никто из тех, кто сейчас играет, свою партию не потеряет. */
  /* Латинское слово этой игры берём из МЕТОК ИГР — той же таблицы, по которой
     разбираются ссылки-приглашения. Своей копии не заводим нарочно: две
     таблицы имён однажды разъедутся, и брошенная комната потеряется. */
  const ЛАТИНСКОЕ_ИМЯ_ИГРЫ = (function () {
    for (const метка in МЕТКИ_ИГР) {
      if (МЕТКИ_ИГР[метка] === ИГРА_ЭТОЙ_СТРАНИЦЫ) return метка;
    }
    return 'durak';   // игра без метки — та же дорога, что и у ссылок
  })();

  const КЛЮЧ_КОМНАТЫ = 'room_' + ЛАТИНСКОЕ_ИМЯ_ИГРЫ;
  const СТАРЫЙ_КЛЮЧ_КОМНАТЫ = ИГРА_ЭТОЙ_СТРАНИЦЫ === 'дурак'
    ? 'подкидной-дурак:комната'
    : ИГРА_ЭТОЙ_СТРАНИЦЫ + ':комната';

  /* Где лежит последний список знакомых, полученный от сервера. Держим его
     ради одного случая: сервер не ответил. Пустой экран человек читает как
     «друзей нет», и это неправда — правда в том, что мы сейчас не знаем,
     кто за столом. Поэтому показываем прежний список с честной пометкой.
     Лежат тут только имена — ни номеров, ни кодов комнат. */
  const КЛЮЧ_ЗНАКОМЫХ = 'friends';
  const СТАРЫЙ_КЛЮЧ_ЗНАКОМЫХ = 'подкидной-дурак:знакомые';

  /* Сколько имён держим в памяти браузера. Ровно столько же помнит и сервер
     (см. ЗНАКОМЫХ_НА_ЧЕЛОВЕКА в server/знакомые.js): держать больше незачем,
     длиннее списка всё равно не придёт. */
  const ЗНАКОМЫХ_В_ПАМЯТИ = 50;

  /* Как выглядит рабочий адрес: начало, имя сервера, необязательный порт
     и путь. Пробелов и лишних слов быть не должно. Разбираем сами, а не
     через URL: так проверка одинаково работает и в браузере, и в имитации
     страницы, где встроенного разбора адресов может не быть. */
  const ПОХОЖЕ_НА_АДРЕС = /^https?:\/\/[^\s/:?#]+(:\d+)?(\/[^\s?#]*)?$/i;

  /* Свой компьютер и домашняя сеть: туда ходят по обычному http —
     защищённого https там обычно просто нет. Нужно, чтобы дописать
     недостающее начало адреса самим. */
  const АДРЕС_СВОЕГО_КОМПЬЮТЕРА =
    /^(localhost|127\.\d+\.\d+\.\d+|0\.0\.0\.0|\[[^\]]+\]|10\.\d+\.\d+\.\d+|192\.168\.\d+\.\d+|172\.(1[6-9]|2\d|3[01])\.\d+\.\d+)(:\d+)?$/i;

  /* Известные витрины без сервера — сейчас только GitHub Pages. Своего
     сервера там нет и не будет, поэтому запасной адрес (см. функцию
     «запаснойАдрес» ниже) отвечает такой странице честным «адреса нет»,
     а не её origin. Порт нарочно необязателен — как и у остальных правил
     этого файла для хоста страницы. */
  const ВИТРИНА_БЕЗ_СЕРВЕРА = /(^|\.)github\.io(:\d+)?$/i;

  /**
   * Привести вписанный адрес к рабочему виду.
   * Прощаем лишние пробелы, хвостовой знак «/» и забытое начало «https://»,
   * а если из написанного адреса не выходит — честно говорим, чего не хватает.
   * Возвращаем { адрес, беда }: либо готовый адрес, либо объяснение.
   */
  function привестиАдрес(что) {
    let текст = String(что === null || что === undefined ? '' : что).trim();
    if (!текст) return { адрес: '', беда: 'Адрес пустой — впишите его целиком.' };

    текст = текст.replace(/^\/+/, '').replace(/\/+$/, '');   // «//адрес» и «адрес/» — обычные описки

    if (!/^https?:\/\//i.test(текст)) {
      // Начало вида «ws://» или «ftp://» дописать нельзя — тут нужен человек.
      if (/^[a-zа-яё]+:\/\//i.test(текст)) {
        return { адрес: '', беда: 'Адрес должен начинаться с https:// или http://, ' +
                                  'а начинается по-другому: «' + текст + '».' };
      }
      // Начала нет вовсе — дописываем сами. Для своего компьютера это
      // http://, для всего остального https://: туннели и опубликованные
      // сайты всегда защищённые.
      const имяСервера = текст.split('/')[0];
      текст = (АДРЕС_СВОЕГО_КОМПЬЮТЕРА.test(имяСервера) ? 'http://' : 'https://') + текст;
    }

    if (!ПОХОЖЕ_НА_АДРЕС.test(текст)) {
      return { адрес: '', беда: 'Это не похоже на адрес сервера: «' + текст + '». ' +
                                'Нужно что-то вроде https://имя-сервера.trycloudflare.com ' +
                                'или http://127.0.0.1:8790 — одной строкой, без пробелов.' };
    }
    return { адрес: текст, беда: null };
  }

  /**
   * Что стоит в хвостике «?сервер=» самой ссылки на игру.
   *
   * Пришли по приглашению — адрес берём оттуда, и он сильнее хвостика.
   * Так и должно быть: приглашение указывает на тот самый сервер, где
   * прямо сейчас стоит стол друга, а хвостик мог достаться странице
   * от старой закладки и вести в никуда. Дальше этот адрес живёт как
   * обычный «адрес из ссылки» — со всем прежним спором живого с мёртвым.
   */
  function адресИзСсылки() {
    const позвали = приглашениеИзСсылки();
    if (позвали && позвали.адрес) return позвали.адрес;
    try {
      const разбор = new URLSearchParams(window.location.search);
      // Русское название удобно человеку, латинское — тому, кто правит
      // настройки бота в консоли. Принимаем оба.
      return разбор.get('сервер') || разбор.get('server') || '';
    } catch (сбой) {
      return '';
    }
  }

  /* Вписанный адрес держим ещё и здесь. Память браузера бывает запрещена
     (режим инкогнито, встроенный браузер Telegram), и тогда сохранить
     адрес не выйдет — но хотя бы до перезагрузки страницы человек должен
     сыграть, а не читать отказ. */
  let вписанныйАдрес = '';

  /**
   * Перевезти выбор человека со старых имён ключей на новые.
   *
   * Переименование ключа без переноса стирает настройку молча: игра ищет
   * новое имя, не находит и решает, что человек ничего не выбирал. Для
   * адреса сервера это особенно дорого — без него не создать игру с другом,
   * и мы эту беду уже чинили.
   *
   * Общую дверь даёт js/telegram.js. Её может не быть (файл ещё не
   * загрузился или это чужая страница) — тогда переносим теми же тремя
   * строками сами. Старые имена не стираем: человек мог открыть игру
   * на другом устройстве, где страница ещё прежняя.
   */
  function перенестиКлюч(старое, новое) {
    if (!старое || !новое || старое === новое) return;
    try {
      if (window.Телеграм && typeof window.Телеграм.перенестиНастройку === 'function') {
        window.Телеграм.перенестиНастройку(старое, новое);
        return;
      }
      if (window.localStorage.getItem(новое) !== null) return;
      const прежнее = window.localStorage.getItem(старое);
      if (прежнее !== null) window.localStorage.setItem(новое, прежнее);
    } catch (сбой) {
      /* память запрещена — переносить нечего и некуда */
    }
  }

  /* Переезд делаем один раз, при запуске файла: дальше все читают уже
     новые имена и про старые не знают вовсе. */
  перенестиКлюч(СТАРЫЙ_КЛЮЧ_АДРЕСА, КЛЮЧ_АДРЕСА);
  перенестиКлюч(СТАРЫЙ_КЛЮЧ_КОМНАТЫ, КЛЮЧ_КОМНАТЫ);
  перенестиКлюч(СТАРЫЙ_КЛЮЧ_ЗНАКОМЫХ, КЛЮЧ_ЗНАКОМЫХ);
  /* Ключ имени вкладки объявлен ниже по файлу, и его переезд стоит рядом
     с самим объявлением: здесь имя ещё не создано, и вызов упал бы. */

  /** Адрес, вписанный руками и сохранённый в памяти браузера. */
  function сохранённыйАдрес() {
    try {
      return (window.localStorage.getItem(КЛЮЧ_АДРЕСА) || '').trim();
    } catch (сбой) {
      return '';
    }
  }

  /** Запомнить вписанный адрес. Отвечает, легло ли в память браузера. */
  function запомнитьАдрес(адрес) {
    вписанныйАдрес = адрес;
    try {
      window.localStorage.setItem(КЛЮЧ_АДРЕСА, адрес);
      return true;
    } catch (сбой) {
      return false;
    }
  }

  /**
   * Запомнить адрес, приехавший в ссылке, — но только если своего у игры
   * ещё нет.
   *
   * Зачем. Telegram открывает мини-приложение всегда по одному адресу,
   * и адрес сервера приезжает только в самой ссылке. Открыл человек игру
   * во второй раз, уже из списка приложений, — ссылки нет, адреса нет,
   * и игра честно, но обидно отвечает, что сервера не знает. Ровно это
   * и случилось у хозяина сервера: он играл вчера, а сегодня игра его
   * не узнала.
   *
   * Почему только в пустую память. Вписанный руками адрес человек вводил
   * сам, и затирать его чужой ссылкой нельзя: сегодня он позвал друга
   * по чьей-то ссылке, а завтра его собственный сервер стал бы недоступен
   * без всякого объяснения. Пока память пуста, спорить не с чем.
   */
  function запомнитьАдресИзСсылки() {
    if (сохранённыйАдрес() || вписанныйАдрес) return false;
    const изСсылки = привестиАдрес(адресИзСсылки()).адрес;
    if (!изСсылки) return false;
    запомнитьАдрес(изСсылки);
    return true;
  }

  /**
   * Положить в память адрес, пришедший ссылкой, поверх мёртвого.
   * Зовётся только из спора адресов и только когда прежний не отвечает.
   * Отдельная дверь нужна, чтобы это решение жило в одном месте,
   * а не растворилось в разборе ответов.
   */
  function освежитьПамятьАдреса(адрес) {
    const годный = привестиАдрес(адрес).адрес;
    if (!годный || годный === сохранённыйАдрес()) return false;
    запомнитьАдрес(годный);
    return true;
  }

  /** Забыть вписанный адрес и вернуться к тому, что в ссылке. */
  function забытьАдрес() {
    вписанныйАдрес = '';
    try {
      window.localStorage.removeItem(КЛЮЧ_АДРЕСА);
    } catch (сбой) {
      /* нечего было забывать */
    }
  }

  /** Оба возможных адреса, уже приведённые к рабочему виду. */
  function кандидаты() {
    return {
      ссылка: привестиАдрес(адресИзСсылки()).адрес,
      вписан: привестиАдрес(сохранённыйАдрес() || вписанныйАдрес).адрес
    };
  }

  /* Итог спора двух адресов: кто из них ответил и кого в итоге выбрали.
     Держим до перезагрузки страницы — стучаться в дверь на каждый чих
     незачем. Сбрасывается сам, как только один из адресов изменился
     (человек вписал другой или стёр вписанный). */
  let итогСпора = null;    // { ссылка, вписан, адрес, ссылкаЖива, вписанныйЖив }
  let забег = null;        // идущая прямо сейчас проверка: { ссылка, вписан, обещание }

  /** Есть ли о чём спорить: адреса два и они разные. */
  function естьСпор() {
    const кто = кандидаты();
    return Boolean(кто.ссылка && кто.вписан && кто.ссылка !== кто.вписан);
  }

  /** Годится ли добытый итог для нынешней пары адресов. */
  function итогГодится() {
    const кто = кандидаты();
    return Boolean(итогСпора && итогСпора.ссылка === кто.ссылка &&
                   итогСпора.вписан === кто.вписан);
  }

  /** Забыть, кто победил: адреса изменились, надо выяснять заново. */
  function забытьИтогСпора() {
    итогСпора = null;
    забег = null;
  }

  /**
   * Адрес сервера. Спор уже решён — берём победителя. Не решён (или спорить
   * не о чем) — отвечаем сразу, не задерживая игру: адрес из ссылки, потом
   * вписанный, потом запасной.
   */
  function адресСервера() {
    if (итогГодится()) return итогСпора.адрес;
    const кто = кандидаты();
    if (кто.ссылка) return кто.ссылка;
    if (кто.вписан) return кто.вписан;
    return запаснойАдрес();
  }

  /**
   * Запасной адрес — когда в ссылке нет «?сервер=» и руками ничего не
   * вписано. Свой компьютер (файл с диска или localhost/127.0.0.1/домашняя
   * сеть) — там сервер и правда на 127.0.0.1:8790, как раньше. Известная
   * витрина без сервера (GitHub Pages, хост «*.github.io») — честное
   * «адреса нет»: своего сервера там не бывает, а origin выглядел бы как
   * рабочий адрес и слал бы запросы в 404. С любого другого настоящего
   * адреса (например, https://igra.medart.com.ua) сервер живёт там же, где
   * сама страница, — location.origin: так устроен переезд на свой домен,
   * где nginx одним адресом отдаёт и страницы, и API. Ни то ни другое не
   * вышло (нет window.location) — тоже честное «адреса нет».
   */
  function запаснойАдрес() {
    try {
      if (window.location.protocol === 'file:') return АДРЕС_ПО_УМОЛЧАНИЮ;
      const хост = window.location.host || '';
      if (АДРЕС_СВОЕГО_КОМПЬЮТЕРА.test(хост)) return АДРЕС_ПО_УМОЛЧАНИЮ;
      if (ВИТРИНА_БЕЗ_СЕРВЕРА.test(хост)) return '';
      return String(window.location.origin || '');
    } catch (сбой) {
      return '';
    }
  }

  /** Знает ли игра вообще, где сервер. */
  function адресаНет() {
    return !адресСервера();
  }

  /** Откуда взялся нынешний адрес: 'ссылка' | 'вписан' | 'запасной' | 'нет'. */
  function откудаАдрес() {
    const кто = кандидаты();
    const адрес = адресСервера();
    if (!адрес) return 'нет';
    if (кто.ссылка && кто.ссылка === адрес) return 'ссылка';
    if (кто.вписан && кто.вписан === адрес) return 'вписан';
    return 'запасной';
  }

  /**
   * Выяснить, какой из двух адресов живой, и выбрать его.
   * Стучимся в оба разом, а не по очереди: так ожидание равно одному
   * стуку, а не двум. Ответ всегда обещание с выбранным адресом.
   */
  function решитьСпорАдресов() {
    if (итогГодится()) return Promise.resolve(итогСпора.адрес);

    const кто = кандидаты();
    // Спорить не о чем: адрес один (или их нет вовсе). Никуда не стучимся.
    if (!кто.ссылка || !кто.вписан || кто.ссылка === кто.вписан) {
      return Promise.resolve(адресСервера());
    }
    // Такой же забег уже идёт — ждём его, второй раз сервер не тревожим.
    if (забег && забег.ссылка === кто.ссылка && забег.вписан === кто.вписан) {
      return забег.обещание;
    }

    const обещание = Promise.all([отвечаетЛиАдрес(кто.ссылка), отвечаетЛиАдрес(кто.вписан)])
        .then(function (ответы) {
      const ссылкаЖива = ответы[0];
      const вписанныйЖив = ответы[1];
      /* Уступает адрес из ссылки только в одном случае: сам молчит,
         а вписанный отвечает. Во всех остальных он главный. */
      const адрес = (!ссылкаЖива && вписанныйЖив) ? кто.вписан : кто.ссылка;
      // Пока стучались, человек мог вписать другой адрес — тогда наш
      // итог уже про вчерашний день, и записывать его нельзя.
      const сейчас = кандидаты();
      if (сейчас.ссылка === кто.ссылка && сейчас.вписан === кто.вписан) {
        итогСпора = {
          ссылка: кто.ссылка, вписан: кто.вписан, адрес: адрес,
          ссылкаЖива: ссылкаЖива, вписанныйЖив: вписанныйЖив
        };
        забег = null;
        /* Память освежаем ровно в одном случае: адрес из неё умер,
           а тот, что пришёл ссылкой, — жив. Старый тогда не жалко:
           он всё равно никуда не ведёт.

           Зачем это нужно. Имя туннеля меняется при каждом запуске,
           а на СТРАНИЦЕ ШАШЕК ссылки нет вовсе: туда переходят
           с витрины, закладкой или из истории браузера. Память там —
           единственное слово, и вчерашний мёртвый адрес делал игру
           с другом невозможной, хотя у дурака всё работало: ему свежий
           адрес приезжал ссылкой и побеждал память.

           Оба живы — память НЕ трогаем. Человек мог зайти по
           приглашению друга на чужой сервер, играя там разово;
           свой сервер остаётся его. Отбирать живое нельзя,
           мёртвое — не жалко. */
        if (ссылкаЖива && !вписанныйЖив) освежитьПамятьАдреса(кто.ссылка);
      }
      return адресСервера();
    });

    забег = { ссылка: кто.ссылка, вписан: кто.вписан, обещание: обещание };
    return обещание;
  }

  /**
   * Сделать дело тогда, когда адрес окончательно выбран. Спорить не о чем —
   * делаем прямо сейчас, в той же строке: обычный запуск по хорошей ссылке
   * не должен ждать ни секунды. Спор есть — сначала выясняем, кто живой.
   *
   * Если дело начато нажатием кнопки, её имя стоит передать: кнопка скажет,
   * чего ждём, и на время ожидания перестанет принимать нажатия — двойной
   * тап на телефоне иначе отправил бы два запроса подряд.
   */
  function приВыбранномАдресе(идКнопки, дело) {
    if (итогГодится() || !естьСпор()) {
      дело();
      return;
    }
    if (идКнопки) занятьКнопку(идКнопки, 'Проверяем адрес…');
    решитьСпорАдресов().then(function () {
      if (идКнопки) освободитьКнопку(идКнопки);
      дело();
    });
  }

  /**
   * Пропустит ли браузер запрос по такому адресу. Защищённая страница
   * (а в Telegram она всегда защищённая) не имеет права обращаться
   * к незащищённому адресу — браузер запрещает это молча.
   */
  function браузерЗапретит(адрес) {
    return window.location.protocol === 'https:' && /^http:\/\//i.test(адрес);
  }

  /**
   * Почему по этому адресу играть не выйдет — одним словом, без объяснений.
   * Проверяем до первой попытки: иначе браузер скажет невнятное «не удалось
   * подключиться», и человек будет искать причину весь вечер.
   * Отвечаем 'плохой-адрес', 'запрет-браузера' или null, если всё в порядке.
   * Слова для человека собираются отдельно — см. «Играть с другом сейчас
   * нельзя» ниже.
   */
  function бедаАдреса(адрес) {
    /* Адреса нет вовсе — это не «плохой адрес», а совсем другой случай:
       игре никто не сказал, где сервер. Слова у него свои (см. БЕДА_ГЛАВНОЕ),
       потому что прежние обвиняли чужой выключенный компьютер, а виноват
       никто: просто ссылка не принесла адреса. */
    if (!String(адрес || '').trim()) return 'нет-адреса';
    if (!/^https?:\/\//i.test(адрес)) return 'плохой-адрес';
    if (браузерЗапретит(адрес)) return 'запрет-браузера';
    return null;
  }

  /* -------------------------------------------------------------------
     Приглашение по ссылке: как оно собирается и как читается

     Раньше позвать друга можно было только голосом: создал стол, получил
     код из четырёх знаков и продиктовал. Ссылка делает то же самое в один
     тап — друг жмёт её и садится за стол сам.

     Путей у ссылки два, и они разные для человека:

       1. Обычная ссылка на страницу игры:
            https://имя-сайта/Games/?server=<адрес сервера>&code=<КОД>
          Работает уже сегодня и открывается в браузере телефона. Отправить
          её можно чем угодно — хоть в Telegram, хоть в SMS.

       2. Ссылка мини-приложения:
            https://t.me/ИМЯБОТА/ИМЯПРИЛОЖЕНИЯ?startapp=<КОД>-<адрес буквами>
          Открывает игру внутри Telegram (рекорды из облака Telegram
          остаются при игроке). Заработает, когда владелец заведёт
          мини-приложение у BotFather и мы узнаем его короткое имя.

     Второй путь включается сам, как только это имя появится, — см.
     именаДляСсылки.

     Главная засада, ради которой всё это устроено именно так. Адрес
     домашнего сервера игра берёт из хвостика «?сервер=» в собственной
     ссылке. Ссылка мини-приложения ведёт не туда: Telegram открывает
     адрес, записанный у BotFather, а он про наш сервер ничего не знает
     и меняется вручную. Поэтому адрес сервера мы кладём прямо внутрь
     startapp — тогда приглашение самодостаточно и от настроек бота
     не зависит вовсе.

     В startapp разрешены только латиница, цифры, «_» и «-» (до 512
     знаков). Адрес сервера в такой набор не влезает — в нём есть «:»
     и «/», — поэтому он едет в виде base64url: там ровно эти знаки
     и есть. Разделитель между кодом и адресом — первый «-»: в алфавите
     кодов комнат (ABCDEFGHJKMNPQRSTUVWXYZ23456789) его нет, спутать
     нельзя.
     ------------------------------------------------------------------- */

  /* Имя бота и короткое имя мини-приложения — из настроек у BotFather.
     Вместе они дают ссылку https://t.me/BoardingGames_bot/BoardGames,
     и по ней друг попадает прямо за стол, внутрь Telegram.

     Заменят бота или приложение — правится здесь. Можно и не править вовсе:
     хвостик «?приглашение=имя-приложения» в адресе игры сильнее этих строк.
     Пустое имя приложения тоже допустимо: тогда приглашение будет обычной
     ссылкой на страницу игры — она работает и без всякого Telegram. */
  const ИМЯ_БОТА = 'BoardingGames_bot';
  const ИМЯ_ПРИЛОЖЕНИЯ = 'BoardGames';

  /** Достать значение из части адреса страницы (из «?…» или из «#…»). */
  function изЧастиАдреса(часть, имена) {
    try {
      const разбор = new URLSearchParams(часть || '');
      for (const имя of имена) {
        const значение = разбор.get(имя);
        if (значение) return значение;
      }
    } catch (сбой) {
      /* разбора адресов нет — считаем, что параметра нет */
    }
    return '';
  }

  /**
   * Значение из адреса страницы — сначала из обычного хвостика «?…»,
   * потом из решётки «#…». Решётка нужна не для красоты: открывая
   * мини-приложение, Telegram дописывает свои поля (в том числе
   * tgWebAppStartParam) именно туда.
   */
  function изАдресаСтраницы(имена) {
    const место = window.location || {};
    const изЗапроса = изЧастиАдреса(String(место.search || '').replace(/^\?/, ''), имена);
    if (изЗапроса) return изЗапроса;
    return изЧастиАдреса(String(место.hash || '').replace(/^#/, ''), имена);
  }

  /**
   * Адрес сервера буквами, которые разрешены в ссылке мини-приложения.
   *
   * Между строкой и base64 стоит лишний шаг, и он нужен: btoa умеет только
   * однобайтовые знаки и на кириллице просто падает. Адрес сервера обычно
   * латинский, но бывает и с русскими буквами — тогда мы сначала переводим
   * его в проценты (%D1%82…), а проценты обратно в байты, и уже байты
   * складываем в base64. На той стороне всё разворачивается в обратном
   * порядке.
   */
  function буквамиИзАдреса(адрес) {
    try {
      const байтами = encodeURIComponent(String(адрес || ''))
        .replace(/%([0-9A-F]{2})/gi, function (всё, число) {
          return String.fromCharCode(parseInt(число, 16));
        });
      return window.btoa(байтами)
        .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    } catch (сбой) {
      // Не вышло — приглашение обойдётся без адреса, друг подставит его сам.
      return '';
    }
  }

  /**
   * Обратно: буквы из ссылки — в адрес сервера. Ссылку мог прислать кто
   * угодно, поэтому результат проходит ту же проверку, что и вписанный
   * руками адрес: не похоже на http/https-адрес — не берём вовсе.
   */
  function адресИзБукв(буквы) {
    const чистые = String(буквы || '').replace(/[^A-Za-z0-9\-_]/g, '');
    if (!чистые) return '';
    let основа = чистые.replace(/-/g, '+').replace(/_/g, '/');
    while (основа.length % 4 !== 0) основа += '=';
    let расшифровка = '';
    try {
      const байты = window.atob(основа);
      // Обратный порядок: байты → проценты → обычная строка (см. буквамиИзАдреса).
      let проценты = '';
      for (let место = 0; место < байты.length; место++) {
        проценты += '%' + ('0' + байты.charCodeAt(место).toString(16)).slice(-2);
      }
      расшифровка = decodeURIComponent(проценты);
    } catch (сбой) {
      return '';
    }
    return привестиАдрес(расшифровка).адрес;
  }

  /**
   * Что Telegram передал при запуске мини-приложения. Спрашиваем осторожно:
   * скрипт Telegram подключён с пометкой defer, то есть в момент запуска
   * этого файла его может ещё не быть вовсе. Ничего страшного — то же самое
   * значение лежит в решётке адреса страницы и доступно сразу.
   */
  function стартовыйПараметрОтTelegram() {
    try {
      const приложение = window.Telegram && window.Telegram.WebApp;
      const данные = приложение && приложение.initDataUnsafe;
      return данные && данные.start_param ? String(данные.start_param) : '';
    } catch (сбой) {
      return '';
    }
  }

  /* Словарь меток игр и слово этой страницы объявлены в начале файла:
     от них зависит ещё и ключ сохранённой комнаты, а он нужен раньше. */

  /** Отделить метку игры: { игра, остаток }. Метки нет — игра страницы. */
  function отделитьМеткуИгры(строка) {
    const текст = String(строка || '').trim();
    const разбор = текст.match(/^([a-z]+)(?:_(.*))?$/);
    if (разбор && МЕТКИ_ИГР[разбор[1]]) {
      return { игра: МЕТКИ_ИГР[разбор[1]], остаток: разбор[2] || '' };
    }
    /* Слово с подчёркиванием, но не из словаря, — метка игры, которой эта
       страница не знает (ссылка из будущего). Кодом комнаты это не считаем:
       иначе дурак стучался бы в несуществующий стол «CHESSA». */
    if (разбор && разбор[2] !== undefined) return { игра: '', остаток: '' };
    return { игра: текст ? ИГРА_ЭТОЙ_СТРАНИЦЫ : '', остаток: текст };
  }

  /**
   * Разобрать «[метка_]КОД-адрес-буквами» на игру, код комнаты и адрес сервера.
   *
   * Код бывает ПУСТЫМ — «durak_-адрес», «shashki_-адрес» или просто
   * «-адрес». Это ссылка, которая не зовёт за конкретный стол, а только
   * говорит игре, где искать сервер: такую кладёт бот в кнопку «Играть»
   * для группового чата и в приглашение друга. Без неё игра, открытая
   * прямо в Telegram, не знает адреса вовсе — и честно, но обидно
   * отвечает хозяину сервера, что сервера нет.
   *
   * Дефис в такой ссылке обязателен, и это не украшение. Голый адрес
   * без дефиса («aHR0cHM6Ly8…») прошёл бы проверку кода: после очистки
   * от лишних знаков остаётся «AHR0CH» — шесть годных знаков, и игра
   * пошла бы стучаться в несуществующий стол. Пустая часть до дефиса
   * говорит прямо: кода тут нет, дальше только адрес.
   */
  function разобратьПриглашение(строка) {
    const метка = отделитьМеткуИгры(строка);
    const номер = отделитьНомерПриглашения(метка.остаток);
    const текст = номер.остаток;
    if (!текст) return null;
    const граница = текст.indexOf('-');
    let кодЧасти = граница === -1 ? текст : текст.slice(0, граница);
    const адресЧасти = граница === -1 ? '' : текст.slice(граница + 1);
    let приглашение = номер.номер;
    /* «КОД_ИД» — новый вид (тот же разбор, что разобратьСсылкуЗаСтол
       на сервере): в кодах столов «_» не бывает, и ровно одно «_», перед
       ним настоящий код стола, после — годный номер: это номер приглашения.
       Иначе код целиком, как у сервера. Без этого очиститьКод склеил бы
       код с номером — «ABCD_ab12cd34» → «ABCDAB», чужой стол. */
    const части = кодЧасти.split('_');
    if (части.length === 2 && КОД_СТОЛА.test(части[0]) && НОМЕР_ПРИГЛАШЕНИЯ.test(части[1]) && !приглашение) {
      кодЧасти = части[0];
      приглашение = части[1];
    }
    const кодКомнаты = очиститьКод(кодЧасти);

    // Ссылка «только адрес»: до дефиса пусто, за дефисом — сервер.
    if (граница !== -1 && кодЧасти === '') {
      const адрес = адресИзБукв(адресЧасти);
      return адрес ? { игра: метка.игра, код: '', адрес: адрес, приглашение: '' } : null;
    }

    if (кодКомнаты.length < 4) return null;
    /* Номер приглашения уезжает в /войти (войтиПоПриглашению): по нему
       сервер отмечает вход в учёте (server/приглашения.js). */
    return { игра: метка.игра, код: кодКомнаты, адрес: адресИзБукв(адресЧасти), приглашение: приглашение };
  }

  /* Номер приглашения — 4–16 латинских букв и цифр, как у сервера
     (НОМЕР_ПРИГЛАШЕНИЯ в server/сервер.js). */
  const НОМЕР_ПРИГЛАШЕНИЯ = /^[A-Za-z0-9]{4,16}$/;
  // Код стола перед «_» — то же правило, что КОД_СТОЛА в server/сервер.js.
  const КОД_СТОЛА = /^[A-Z0-9]{4,12}$/;

  /**
   * Прежний вид номера — хвост «.id» (8 строчных букв и цифр) в самом
   * конце. Telegram точку в startapp не пропускает, но такие ссылки могли
   * успеть появиться, а сервер их понимает. Не отрезать хвост — он уехал бы
   * в буквы адреса и испортил адрес сервера.
   */
  function отделитьНомерПриглашения(текст) {
    const строка = String(текст || '');
    const разбор = строка.match(/^(.*)\.([a-z0-9]{8})$/);
    if (разбор) return { остаток: разбор[1], номер: разбор[2] };
    return { остаток: строка, номер: '' };
  }

  /**
   * Какую игру просит ссылка, по которой открыли страницу: 'шашки',
   * 'дурак' или '' — если ссылка ни о какой игре не говорит. Нужно
   * index.html, чтобы по метке перебросить человека на страницу шашек
   * с тем же параметром запуска — иначе «Сыграть» из чата про шашки
   * откроет карты. Про комнату здесь ничего не решается: только игра.
   */
  function какуюИгруПроситСсылка() {
    const отTelegram = стартовыйПараметр();
    if (отTelegram) {
      /* По этой ссылке главная уже перебросила человека. Telegram держит
         start_param всю сессию, и без этой проверки «Все игры» из нард
         снова кидали бы в нарды — с главной было бы не уйти. */
      if (ИГРА_ЭТОЙ_СТРАНИЦЫ === 'дурак' && изПамятиВкладки(КЛЮЧ_ПЕРЕБРОСКИ) === отTelegram) return '';
      return отделитьМеткуИгры(отTelegram).игра;
    }
    // Обычная ссылка на страницу с кодом стола — это дурак, как и было.
    return очиститьКод(изАдресаСтраницы(['код', 'code'])).length >= 4 ? ИГРА_ЭТОЙ_СТРАНИЦЫ : '';
  }

  /** Параметр запуска Telegram: из решётки адреса или от самого Telegram. */
  function стартовыйПараметр() {
    return изАдресаСтраницы(['tgWebAppStartParam']) || стартовыйПараметрОтTelegram();
  }

  /* Какие ссылки в этой сессии уже отработали. Память вкладки, а не
     localStorage: новая сессия Telegram — новая ссылка, помнить старую
     незачем. Ключи латиницей, как у всей памяти игрока. */
  const КЛЮЧ_ПЕРЕБРОСКИ = 'startapp_redirected';
  const КЛЮЧ_ВХОДА_ПО_ССЫЛКЕ = 'startapp_joined_' + ЛАТИНСКОЕ_ИМЯ_ИГРЫ;

  /* Запасная память вкладки — window.name. Если sessionStorage запрещён
     (бывает во встроенных браузерах), без запаса петля «главная → нарды →
     Все игры → снова нарды» вернулась бы. Имя окна переживает переходы
     между страницами той же вкладки и больше никем в игре не занято.
     Кладём туда JSON с приставкой, чтобы не спутать с чужим именем. */
  const ПРИСТАВКА_ИМЕНИ_ОКНА = 'games-startapp:';

  function изИмениОкна() {
    try {
      const имя = String(window.name || '');
      if (имя.indexOf(ПРИСТАВКА_ИМЕНИ_ОКНА) !== 0) return {};
      const разбор = JSON.parse(имя.slice(ПРИСТАВКА_ИМЕНИ_ОКНА.length));
      return разбор && typeof разбор === 'object' ? разбор : {};
    } catch (сбой) {
      return {};
    }
  }

  function вИмяОкна(ключ, значение) {
    try {
      const всё = изИмениОкна();
      всё[ключ] = String(значение || '');
      window.name = ПРИСТАВКА_ИМЕНИ_ОКНА + JSON.stringify(всё);
    } catch (сбой) {
      /* и имени окна нет — переброска сработает ещё раз, как было раньше */
    }
  }

  /** Прочитать из памяти вкладки; хранилище запрещено — из имени окна. */
  function изПамятиВкладки(ключ) {
    try {
      return String(window.sessionStorage.getItem(ключ) || '');
    } catch (сбой) {
      return String(изИмениОкна()[ключ] || '');
    }
  }

  /** Записать в память вкладки; хранилище запрещено — в имя окна. */
  function вПамятьВкладки(ключ, значение) {
    try {
      window.sessionStorage.setItem(ключ, String(значение || ''));
    } catch (сбой) {
      вИмяОкна(ключ, значение);
    }
  }

  /** Сажала ли уже эта ссылка за стол в этой сессии (или сервер отказал). */
  function входПоСсылкеУжеБыл(параметр) {
    return изПамятиВкладки(КЛЮЧ_ВХОДА_ПО_ССЫЛКЕ) === параметр;
  }

  /** Сервер ответил на вход по ссылке — больше по ней не стучимся. */
  function отметитьВходПоСсылке(параметр) {
    вПамятьВкладки(КЛЮЧ_ВХОДА_ПО_ССЫЛКЕ, параметр);
  }

  /**
   * Главная перебрасывает по ссылке — запомнить, по какой именно. Зовёт
   * js/game.js прямо перед переходом (см. переброситьПоМеткеСсылки).
   */
  function запомнитьПереброску() {
    const параметр = стартовыйПараметр();
    if (параметр) вПамятьВкладки(КЛЮЧ_ПЕРЕБРОСКИ, параметр);
  }

  /* Разобранное приглашение. Удачный разбор запоминаем, а неудачу — нет:
     скрипт Telegram мог ещё не догрузиться, и через секунду ответ будет
     другим. Стоит это дёшево — пара разборов строки. */
  let приглашение = null;

  /** Позвал ли нас кто-нибудь ссылкой: { код, адрес } или null. */
  function приглашениеИзСсылки() {
    if (приглашение) return приглашение;

    // Путь 2: ссылка мини-приложения. Внутри неё и код, и адрес сервера.
    const отTelegram = изАдресаСтраницы(['tgWebAppStartParam']) || стартовыйПараметрОтTelegram();
    const разобранное = разобратьПриглашение(отTelegram);
    if (разобранное) {
      приглашение = разобранное;
      return приглашение;
    }

    // Путь 1: обычная ссылка на страницу игры. Адрес сервера едет в ней
    // отдельным хвостиком «?сервер=», его читает адресИзСсылки.
    const кодКомнаты = очиститьКод(изАдресаСтраницы(['код', 'code']));
    if (кодКомнаты.length >= 4) {
      приглашение = { игра: ИГРА_ЭТОЙ_СТРАНИЦЫ, код: кодКомнаты, адрес: '' };
      return приглашение;
    }
    return null;
  }

  /**
   * Имя бота и короткое имя мини-приложения. Хвостик в адресе игры
   * («?приглашение=имя-приложения» или «?приглашение=бот/приложение»)
   * сильнее констант: так имя можно задать в настройках бота, не трогая
   * код и не поднимая номер версии файла.
   */
  function именаДляСсылки() {
    const хвостик = String(изАдресаСтраницы(['приглашение', 'invite']) || '').trim();
    const части = хвостик.split('/').filter(Boolean);
    const бот = (части.length > 1 ? части[0] : ИМЯ_БОТА).replace(/^@/, '');
    const приложение = части.length > 1 ? части[1] : (части[0] || ИМЯ_ПРИЛОЖЕНИЯ);
    return { бот: бот, приложение: приложение };
  }

  /**
   * Где открыта игра: 'телефон', 'компьютер' или '' — если не в Telegram.
   *
   * Разница между телефоном и компьютером тут не косметическая. На
   * компьютере открытие списка чатов уводит мини-приложение с экрана,
   * и человек не может найти игру: владелец так и сказал — «окно улетает
   * и я его не могу найти». Поэтому на компьютере списком чатов мы
   * не пользуемся вовсе.
   *
   * Неизвестную площадку считаем компьютером нарочно: скопированная
   * ссылка не теряется никогда, а потерянное окно игры — беда.
   */
  function гдеМыВTelegram() {
    if (!мыВTelegram()) return '';
    let площадка = '';
    try {
      площадка = String(window.Telegram.WebApp.platform || '').toLowerCase();
    } catch (сбой) {
      return 'компьютер';
    }
    return (площадка === 'android' || площадка === 'ios') ? 'телефон' : 'компьютер';
  }

  /** Игра открыта внутри Telegram, а не просто в браузере. */
  function мыВTelegram() {
    try {
      const приложение = window.Telegram && window.Telegram.WebApp;
      if (!приложение) return false;
      if (приложение.initData) return true;
      // Вне Telegram тот же скрипт называет площадку «unknown».
      const площадка = String(приложение.platform || '');
      return Boolean(площадка) && площадка !== 'unknown';
    } catch (сбой) {
      return false;
    }
  }

  /**
   * Обычная ссылка на эту же страницу — с адресом сервера и кодом комнаты.
   * Имена хвостиков латинские (server, code), хотя игра понимает и русские:
   * русское слово в ссылке превращается в вереницу процентов, и такое
   * приглашение выглядит как что-то опасное.
   */
  function ссылкаНаСтраницу(адрес, кодКомнаты) {
    const место = window.location || {};
    // Игра открыта файлом с диска — такую ссылку другу отправлять некуда.
    if (String(место.protocol || '') === 'file:') return '';
    const начало = место.origin || (String(место.protocol || '') + '//' + String(место.host || ''));
    if (!начало || начало === 'null//') return '';
    return начало + String(место.pathname || '') +
           '?server=' + encodeURIComponent(адрес) +
           '&code=' + encodeURIComponent(кодКомнаты);
  }

  /** Ссылка мини-приложения или пусто, если имена бота и приложения неизвестны. */
  function ссылкаНаМиниПриложение(адрес, кодКомнаты) {
    const имена = именаДляСсылки();
    if (!имена.бот || !имена.приложение) return '';
    const буквы = буквамиИзАдреса(адрес);
    /* Метка игры впереди кода — иначе приглашение за стол шашек откроет
       дурака: Telegram ведёт мини-приложение всегда на одну страницу.
       У дурака метки нет и не будет: ссылки, разосланные до появления
       второй игры, обязаны открываться как прежде. */
    const метка = меткаИгрыДляСсылки(ИГРА_ЭТОЙ_СТРАНИЦЫ);
    const начало = метка && ИГРА_ЭТОЙ_СТРАНИЦЫ !== 'дурак' ? метка + '_' : '';
    return 'https://t.me/' + имена.бот + '/' + имена.приложение +
           '?startapp=' + начало + кодКомнаты + (буквы ? '-' + буквы : '');
  }

  /**
   * Ссылка-приглашение за этот стол. Какая именно — зависит от того, откуда
   * зовут, и это не мелочь: ссылка должна открываться там же, где её взяли.
   *
   *   — зовут из Telegram → ссылка мини-приложения: друг откроет игру прямо
   *     в мессенджере, с именем и облачными рекордами;
   *   — зовут из браузера → ссылка на эту же страницу. Телеграмная ссылка
   *     в браузере просто не откроется, а вторую вкладку игрой открывают
   *     постоянно — и мы сами, когда проверяем игру вдвоём.
   *
   * Адрес страницы берём у самой страницы, а не из константы: игру открывают
   * и с домашнего компьютера, и с сайта, и через туннель.
   *
   * Если нужной ссылки не выходит (игру открыли файлом с диска — ссылки
   * на страницу тогда нет вовсе; или короткое имя приложения неизвестно),
   * берём вторую: приглашение хоть какое-то лучше, чем никакого.
   */
  function ссылкаПриглашения(кодКомнаты) {
    if (!кодКомнаты) return '';
    const адрес = адресСервера();
    const телеграмная = ссылкаНаМиниПриложение(адрес, кодКомнаты);
    const браузерная = ссылкаНаСтраницу(адрес, кодКомнаты);
    if (мыВTelegram()) return телеграмная || браузерная;
    return браузерная || телеграмная;
  }

  /** Куда приведёт ссылка: в Telegram или в обычный браузер. */
  function этоСсылкаВTelegram(ссылка) {
    return String(ссылка || '').indexOf('https://t.me/') === 0;
  }

  /* -------------------------------------------------------------------
     Память о своей комнате
     ------------------------------------------------------------------- */

  /* Своё имя этой открытой страницы. Память браузера одна на все вкладки,
     поэтому в записи о комнате отмечено, какая вкладка сейчас за столом:
     иначе вторая вкладка садится на то же место, а её выход выкидывает
     из партии и первую — друг видит «Соперник вышел», хотя человек играет. */
  const КЛЮЧ_ИМЕНИ_ВКЛАДКИ = 'tab_name';
  const СТАРЫЙ_КЛЮЧ_ВКЛАДКИ = 'подкидной-дурак:вкладка';
  // Переезд зовём здесь, а не наверху: имя ключа объявлено только сейчас.
  перенестиКлюч(СТАРЫЙ_КЛЮЧ_ВКЛАДКИ, КЛЮЧ_ИМЕНИ_ВКЛАДКИ);

  function придуматьИмя() {
    return Math.random().toString(36).slice(2) + Date.now().toString(36);
  }

  /**
   * Имя берём из памяти самой вкладки (sessionStorage). Она у каждой вкладки
   * своя и переживает перезагрузку страницы — а это ровно то, что нужно:
   * после обновления вкладка узнаёт собственную запись о комнате и зовёт
   * вернуться в игру. Со случайным именем при каждой загрузке она принимала
   * себя же за соседнюю вкладку и первые пятнадцать секунд отказывалась
   * возвращаться в свою партию.
   * Вкладка, открытая обычным способом, чужой памяти не наследует, имя
   * получает другое, поэтому защита «эта игра уже открыта в другой вкладке»
   * работает как была.
   * Но есть две лазейки, и лучше знать о них заранее: по команде браузера
   * «Дублировать вкладку» и при восстановлении случайно закрытой вкладки
   * эта память копируется вместе с содержимым. Тогда у двух вкладок имя
   * одинаковое, они считают друг друга собой, и защита молчит: обе сядут
   * за один стол, а выход из любой из них выбросит из партии обеих.
   * Внутри Telegram и в режиме инкогнито доступ к этой памяти иногда
   * запрещён и обрывается ошибкой — тогда берём случайное имя, как раньше.
   */
  function узнатьИмяВкладки() {
    try {
      const сохранённое = window.sessionStorage.getItem(КЛЮЧ_ИМЕНИ_ВКЛАДКИ);
      if (сохранённое) return сохранённое;
      const свежее = придуматьИмя();
      window.sessionStorage.setItem(КЛЮЧ_ИМЕНИ_ВКЛАДКИ, свежее);
      return свежее;
    } catch (сбой) {
      return придуматьИмя();
    }
  }

  const имяВкладки = узнатьИмяВкладки();

  /* Пока играющая вкладка жива, она обновляет отметку времени. Запись
     старше этого срока считается брошенной — например, вкладку закрыли. */
  const СРОК_ЗАНЯТОСТИ = 15 * 1000;
  const ОТМЕТКА_КАЖДЫЕ = 4 * 1000;

  function запомнитьКомнату(код, пропуск) {
    try {
      window.localStorage.setItem(КЛЮЧ_КОМНАТЫ, JSON.stringify({
        код: код, пропуск: пропуск, владелец: имяВкладки, отметка: Date.now()
      }));
    } catch (сбой) {
      /* запрещённая память — не повод ломать игру, просто не вернёмся после перезагрузки */
    }
    обновитьКнопкуВозврата();
  }

  function забытьКомнату() {
    // Чужую запись не стираем: за это время другая вкладка могла начать
    // свою игру, и её ключ возврата нам не принадлежит.
    if (комнатуДержитДругаяВкладка()) return;
    try {
      window.localStorage.removeItem(КЛЮЧ_КОМНАТЫ);
    } catch (сбой) {
      /* ничего страшного */
    }
    обновитьКнопкуВозврата();
  }

  /** Сохранённые код и пропуск или null, если их нет. */
  function вспомнитьКомнату() {
    let текст = null;
    try {
      текст = window.localStorage.getItem(КЛЮЧ_КОМНАТЫ);
    } catch (сбой) {
      return null;
    }
    if (!текст) return null;
    try {
      const разобранное = JSON.parse(текст);
      if (разобранное && разобранное.код && разобранное.пропуск) return разобранное;
    } catch (сбой) {
      /* испорченная запись — считаем, что её нет */
    }
    return null;
  }

  /**
   * Играет ли этой комнатой другая вкладка прямо сейчас. Отметка времени
   * свежая — значит там живой человек за столом, и лезть туда нельзя.
   */
  function комнатуДержитДругаяВкладка() {
    const запись = вспомнитьКомнату();
    if (!запись || !запись.владелец || запись.владелец === имяВкладки) return false;
    return Date.now() - (Number(запись.отметка) || 0) < СРОК_ЗАНЯТОСТИ;
  }

  /** Отметиться: «эта вкладка всё ещё за столом». */
  function отметитьВладение() {
    if (!код || !пропуск) return;
    const запись = вспомнитьКомнату();
    // Чужую запись не трогаем: вдруг за столом уже другая вкладка.
    if (запись && запись.код !== код) return;
    запомнитьКомнату(код, пропуск);
  }

  /* -------------------------------------------------------------------
     Состояние этой вкладки
     ------------------------------------------------------------------- */

  let код = null;              // код комнаты
  let пропуск = null;          // ключ возврата в свою партию
  let версия = 0;              // версия состояния, с которой мы спрашиваем новости
  let вПартии = false;         // идёт ли сейчас наша сетевая партия
  let опросИдёт = false;       // крутится ли длинный опрос
  let связьЕсть = true;        // отвечает ли сервер
  let попытокПодряд = 0;       // сколько раз подряд не достучались
  let последнееСостояние = null;
  let когдаБылоСобытие = 0;    // время последней новости — по нему видно раздумье
  let когдаОтвечалСервер = 0;  // время последнего удачного ответа
  let соперникПропалС = 0;     // когда соперник впервые стал не на связи, 0 — не пропадал
  let часовойСвязи = null;     // таймер, освежающий строку связи
  let часовойВладения = null;  // таймер, отмечающий «эта вкладка играет»
  let приветствиеДо = 0;       // до какого времени висит «друг пришёл»
  let ручкаОпроса = null;      // чем прервать висящий длинный опрос
  /* Умеет ли сервер эмоции. Узнаём из его же ответа, а не по словам отказа:
     у старого сервера этого поля нет вовсе. Пока ни одного состояния
     не пришло, считаем, что не умеет, — обещать кнопку раньше времени
     хуже, чем показать её на секунду позже. */
  let эмоцииРаботают = false;

  /* Откуда попали в комнату — от этого зависит, куда вернёт «Выйти из
     комнаты»: новый путь дурака (лобби → три шага режима «друзья»)
     привёл сюда не через «Игра с другом», и выходить из комнаты нужно
     в лобби, а не на экран, которого человек не открывал. Прежний вход —
     кнопка «Создать игру» или «Войти по коду» на самом экране «Игра
     с другом» — по-прежнему ведёт туда же, откуда пришёл. По умолчанию —
     «друг»: так вело себя это место раньше, и старый вход это поведение
     не трогает. */
  let путьВКомнату = 'друг';

  /* Номер попытки. Каждое новое начало (создали, вошли, вернулись, вышли)
     поднимает его на единицу. Ответ на старый запрос может прийти позже
     нового — например, на медленной связи, — и такой ответ нельзя
     применять: он выбросит человека из свежей комнаты обратно в старую,
     а друг останется за столом навсегда. Поэтому каждый ответ сверяет
     свой номер с текущим и, если отстал, молча выбрасывается. */
  let поколение = 0;

  function новоеПоколение() {
    поколение++;
    return поколение;
  }

  /** Не устарел ли ответ, пока летел. */
  function ответУстарел(моёПоколение) {
    return моёПоколение !== поколение;
  }

  /* -------------------------------------------------------------------
     Запросы к серверу
     ------------------------------------------------------------------- */

  /* Заголовок-пропуск через бесплатный туннель.

     Между игроком и домашним сервером стоит туннель — чужая программа,
     которая даёт домашнему компьютеру адрес в интернете. Некоторые
     бесплатные туннели (например, loca.lt) на запрос из браузера
     отвечают не сервером, а собственной страницей-предупреждением
     «дальше чужой туннель, точно хотите?». Человек её никогда не увидит:
     игра стучится в сервер сама, и вместо карт получает отказ 511 —
     то есть партия просто не начинается.

     Этот заголовок и есть просьба «страницу не показывай, пропусти
     к серверу». Всем остальным он безобиден: наш сервер и Cloudflare
     его просто не замечают. Поэтому шлём его всегда, не разбирая,
     по какому адресу идём.

     Важно: этот заголовок необычный, поэтому браузер сперва спрашивает
     у сервера разрешения отдельным запросом (OPTIONS). Разрешение выдаёт
     server/сервер.js — там заголовок назван в списке разрешённых. */
  const ПРОПУСК_ЧЕРЕЗ_ТУННЕЛЬ = { 'bypass-tunnel-reminder': 'true' };

  /**
   * Ответ пришёл, но не от нашего сервера. Такое бывает, когда туннель
   * умер посреди партии: до сервера запрос уже не доходит, и вместо ответа
   * возвращается страница посредника — «Bad Gateway», «Tunnel Unavailable»
   * или предупреждение самого туннеля.
   *
   * Узнаём это по одному верному признаку: наш сервер отвечает только
   * JSON, всегда и на любую беду. Не разобралось — значит отвечал не он.
   *
   * Почему это важно. Раньше такой ответ считался настоящим ответом
   * сервера. Человек нажимал на карту, ответ приходил без пояснений,
   * и игра делала худшее из возможного: объявляла, что связь в порядке,
   * писала «Соперник на связи» — и молча не делала ход. Экран не менялся
   * вовсе, и понять, что происходит, было нельзя.
   */
  function отвечалНеСервер(номер) {
    return { ок: false, связьСорвалась: true, номер: номер, данные: {} };
  }

  /**
   * Один запрос. Никогда не «падает»: любая беда возвращается обычным
   * ответом с пометкой «связь сорвалась», чтобы её обработали в одном месте.
   */
  function запрос(путь, тело, сколькоЖдать, ручка) {
    const адрес = адресСервера();
    const управление = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const сторож = setTimeout(function () {
      if (управление) управление.abort();
    }, сколькоЖдать || ОБЫЧНОЕ_ОЖИДАНИЕ);

    /* Через ручку запрос можно прервать снаружи. Это нужно при выходе
       в меню: висящий «что нового» вернулся бы в уже удалённую комнату
       и браузер написал бы в консоль красную ошибку 404. */
    if (ручка) {
      ручка.прервать = function () {
        clearTimeout(сторож);
        if (управление) управление.abort();
      };
    }

    const настройки = {
      method: 'POST',
      headers: Object.assign({ 'Content-Type': 'application/json' }, ПРОПУСК_ЧЕРЕЗ_ТУННЕЛЬ),
      body: JSON.stringify(тело || {})
    };
    if (управление) настройки.signal = управление.signal;

    return fetch(адрес + путь, настройки)
      .then(function (ответ) {
        return ответ.json().then(
          function (данные) {
            if (!данные || typeof данные !== 'object') return отвечалНеСервер(ответ.status);
            return { ок: ответ.ok, номер: ответ.status, данные: данные };
          },
          function () { return отвечалНеСервер(ответ.status); }
        );
      })
      .catch(function () {
        return { ок: false, связьСорвалась: true, данные: {} };
      })
      .then(function (итог) {
        clearTimeout(сторож);
        return итог;
      });
  }

  /** Запрос от имени игрока: код и пропуск подставляются сами. */
  function запросОтМеня(путь, тело, сколькоЖдать, ручка) {
    const полное = Object.assign({ код: код, пропуск: пропуск }, тело || {});
    return запрос(путь, полное, сколькоЖдать, ручка);
  }

  /* -------------------------------------------------------------------
     Экраны и надписи
     ------------------------------------------------------------------- */

  function узел(id) {
    return document.getElementById(id);
  }

  function написать(id, текст) {
    const место = узел(id);
    if (место) место.textContent = текст;
  }

  /** Показать или спрятать элемент. */
  function показать(id, видно) {
    const место = узел(id);
    if (место) место.classList.toggle('скрыт', !видно);
  }

  /** Сообщение на экране: пустой текст прячет строку целиком. */
  function сказать(id, текст) {
    написать(id, текст || '');
    показать(id, Boolean(текст));
  }

  /* ---------- Отклик прямо на кнопке ----------
     Без отклика человек не понимает, сработало ли нажатие. Особенно
     обидно, когда игра заранее знает ответ: она переписывала тот же текст
     в то же место, на экране не менялось ни пикселя, и кнопка выглядела
     сломанной. Поэтому теперь на каждое нажатие отвечает сама кнопка —
     это видно всегда, чем бы дело ни кончилось. */

  const ПОКАЗ_ОТВЕТА_КНОПКИ = 2000;   // сколько кнопка держит ответ вместо названия
  const памятьКнопок = {};            // id кнопки → её обычная надпись и таймер

  function памятьКнопки(кнопка) {
    const запись = памятьКнопок[кнопка.id] ||
                   (памятьКнопок[кнопка.id] = { надпись: '', таймер: null });
    // Обычную надпись берём из разметки при первом же обращении.
    if (!запись.надпись) запись.надпись = кнопка.textContent;
    return запись;
  }

  /** Ответить прямо на кнопке и через пару секунд вернуть ей название. */
  function ответитьНаКнопке(id, текст) {
    const кнопка = узел(id);
    if (!кнопка) return;
    const запись = памятьКнопки(кнопка);
    кнопка.textContent = текст;
    if (запись.таймер !== null) clearTimeout(запись.таймер);
    запись.таймер = setTimeout(function () {
      запись.таймер = null;
      кнопка.textContent = запись.надпись;
    }, ПОКАЗ_ОТВЕТА_КНОПКИ);
  }

  /**
   * Кнопка занята работой: надпись рассказывает, что происходит, а нажатия
   * больше не проходят. Это же и защита от двойного тапа — на телефоне
   * он случается сам собой.
   */
  function занятьКнопку(id, надпись) {
    const кнопка = узел(id);
    if (!кнопка) return;
    const запись = памятьКнопки(кнопка);
    if (запись.таймер !== null) {
      clearTimeout(запись.таймер);
      запись.таймер = null;
    }
    кнопка.textContent = надпись;
    кнопка.disabled = true;
  }

  /** Работа кончилась: вернуть кнопке название (или на пару секунд — ответ). */
  function освободитьКнопку(id, ответ) {
    const кнопка = узел(id);
    if (!кнопка) return;
    const запись = памятьКнопки(кнопка);
    кнопка.disabled = false;
    if (ответ) ответитьНаКнопке(id, ответ);
    else кнопка.textContent = запись.надпись;
  }

  /** Мост в js/game.js. Без него сетевой режим бесполезен. */
  function игра() {
    return window.ИграПоСети || null;
  }

  function показатьЭкран(id) {
    const мост = игра();
    if (мост && typeof мост.экран === 'function') мост.экран(id);
  }

  function показатьСвязь(текст, вид) {
    const мост = игра();
    if (мост && typeof мост.показатьСвязь === 'function') мост.показатьСвязь(текст, вид);
  }

  /**
   * Скрыть новый экран комнаты (js/дурак-комната.js), если он сейчас показан:
   * партия началась, комната закрылась или мы сами из неё вышли. Файла нет
   * или комната показывалась старым видом — делать нечего, старый вид уходит
   * обычным переключением экрана, как и раньше.
   */
  function спрятатьНовуюКомнату() {
    if (window.ДуракКомната && typeof window.ДуракКомната.спрятать === 'function') {
      window.ДуракКомната.спрятать();
    }
  }

  /* -------------------------------------------------------------------
     Строка связи: что происходит прямо сейчас
     ------------------------------------------------------------------- */

  /**
   * Какой текст показать про пропавшего соперника — по тому, сколько
   * миллисекунд назад он стал не на связи. Чистая функция (ничего не
   * читает и не трогает снаружи), поэтому её можно проверить в node без
   * браузера: тестировщик подставляет разные мсСПропажи и сверяет текст.
   */
  function текстПропажи(мсСПропажи) {
    return мсСПропажи < МЯГКАЯ_ПРОПАЖА
      ? ТЕКСТ_ДРУГ_ПЕРЕПОДКЛЮЧАЕТСЯ
      : ТЕКСТ_ДРУГ_ПРОПАЛ;
  }

  /**
   * Одна строка над столом отвечает на два вопроса сразу: жив ли друг
   * и жива ли наша связь. Пишем словами, без значков — значок «!» человек
   * истолкует как угодно.
   */
  function освежитьСтрокуСвязи() {
    if (!вПартии) return;

    // Молчание дольше длинного опроса — тоже обрыв, даже если ни один
    // запрос ещё не успел сорваться: висящий запрос мог просто повиснуть.
    const давноМолчит = когдаОтвечалСервер > 0 &&
                        Date.now() - когдаОтвечалСервер > МОЛЧАНИЕ_ЭТО_ОБРЫВ;

    if (!связьЕсть || давноМолчит) {
      показатьСвязь('Связь с игрой потеряна. Пробуем восстановить…' +
                    (попытокПодряд > 0 ? ' (попытка ' + попытокПодряд + ')' : ''), 'тревога');
      return;
    }
    const вид = последнееСостояние;
    if (!вид) {
      показатьСвязь('Соединяемся с игрой…', 'ожидание');
      return;
    }
    // Друг снова на связи — момент пропажи забываем, чтобы следующая
    // пропажа опять начиналась с мягкой надписи, а не с тревожной.
    if (вид.соперникНаСвязи) соперникПропалС = 0;
    if (вид.соперникУшёл) {
      показатьСвязь('Соперник вышел из игры', 'тревога');
      return;
    }
    if (!вид.соперникНаСвязи) {
      if (!соперникПропалС) соперникПропалС = Date.now();
      показатьСвязь(текстПропажи(Date.now() - соперникПропалС), 'тревога');
      return;
    }
    // Первые секунды партии показываем сам факт: друг за столом.
    if (Date.now() < приветствиеДо) {
      показатьСвязь('Соперник пришёл — играем!');
      return;
    }
    // Ходит друг и молчит уже долго: пусть будет видно, что игра не зависла.
    if (!вид.яХожу && !вид.завершена && Date.now() - когдаБылоСобытие > ДОЛГОЕ_РАЗДУМЬЕ) {
      показатьСвязь((вид.имяСоперника || 'Соперник') + ' думает…', 'ожидание');
      return;
    }
    показатьСвязь('Соперник на связи');
  }

  function запуститьЧасовогоСвязи() {
    if (часовойСвязи !== null) return;
    часовойСвязи = setInterval(освежитьСтрокуСвязи, ЧАСТОТА_СТРОКИ_СВЯЗИ);
  }

  function остановитьЧасовогоСвязи() {
    if (часовойСвязи === null) return;
    clearInterval(часовойСвязи);
    часовойСвязи = null;
  }

  /* -------------------------------------------------------------------
     Приём состояния от сервера
     ------------------------------------------------------------------- */

  /**
   * Принять новое состояние. Отсюда оно уходит в игру одной дверью —
   * так на экране всегда ровно то, что думает сервер.
   */
  function принятьСостояние(вид) {
    if (!вид) return;
    if (typeof вид.версия === 'number') версия = вид.версия;
    /* Что умеет сервер по части знаков. Не «да/нет», а объект: броски
       с целью появились позже смайликов, и сервер может уметь одно без
       другого. Не умеет ничего — false, чтобы прежняя проверка
       «if (Сеть.эмоцииРаботают())» вела себя как раньше. */
    эмоцииРаботают = вид.знакиВниманияЕсть === true
      ? { знаки: true, броски: вид.броскиЕсть === true }
      : false;

    const прежнийНомер = последнееСостояние ? последнееСостояние.номерСобытия : -1;
    if (вид.номерСобытия !== прежнийНомер) когдаБылоСобытие = Date.now();
    последнееСостояние = вид;
    /* Кнопку пересбора решаем здесь, на каждом состоянии: и когда партия
       кончилась (показать), и когда началась новая или мы ушли в прихожую
       (спрятать). Одно место — и кнопка не может остаться висеть от прошлой
       партии на чужом экране. */
    обновитьКнопкуПересбора(вид);

    if (вид.этап === 'ожидание') {
      /* Сюда попадаем не только в начале. Бывает, что у друга оборвалась
         связь ровно на входе, и сервер откатил вход обратно: мы уже успели
         сесть за стол, а комната снова пуста. Тогда надо вернуть вкладку
         в то же состояние, в каком она была до прихода друга. Иначе его
         вторая попытка войти пройдёт мимо: «мы же уже в партии» — стол
         никто не покажет, и человек до конца просидит на «Ждём друга». */
      if (вПартии) {
        вПартии = false;
        приветствиеДо = 0;
        соперникПропалС = 0;
        остановитьЧасовогоСвязи();
        показатьСвязь('');
      }
      показатьОжиданиеДруга(вид);
      return;
    }

    // Партия идёт (или уже доиграна, но комната жива — можно позвать на реванш).
    const мост = игра();
    if (!мост) return;
    if (!вПартии) {
      вПартии = true;
      спрятатьНовуюКомнату();   // партия началась — комнате 05 тут больше нечего делать
      мост.начать();
      запуститьЧасовогоСвязи();
      // Человек ждал не отчёта о скорости друга, а подтверждения, что тот
      // вообще пришёл. Сначала говорим это, а уже потом всё остальное.
      приветствиеДо = Date.now() + ПОКАЗ_ПРИВЕТСТВИЯ;
    }
    мост.показатьВид(вид);
    освежитьСтрокуСвязи();
  }

  /**
   * Двери экрана 05 (js/дурак-комната.js) — собраны один раз: сам объект
   * не меняется, код и пропуск текущей комнаты живут внутри замыканий
   * действиеДвери/позватьДруга/отменитьКомнату и берутся оттуда заново
   * на каждый вызов.
   */
  const двериНовойКомнаты = {
    действие: function (имя, поля) { return действиеДвери(имя, поля); },
    позвать: function () { позватьДруга(); },
    выйти: function () { отменитьКомнату(); },
    /* Раздел «Позвать знакомого» в листе свободного места (js/дурак-комната.js) —
       те же две двери, что кормят список и кнопку «Позвать» на экране
       «Играть с другом», без своей логики: код текущего стола
       позватьЗнакомого возьмёт сама (стол уже открыт — новый не создаст). */
    списокЗнакомых: function () { return списокЗнакомых(); },
    позватьЗнакомого: function (ключ, имя) { return позватьЗнакомого(ключ, имя); }
  };

  /** Пока карты не розданы, показываем код и то, кто уже собрался за столом. */
  function показатьОжиданиеДруга(вид) {
    показатьКодКомнаты(вид.код || код || '', вид);
    /* Список мест («застолом») приходит только из комнаты на компанию —
       вместе с ним сервер шлёт и «яХозяин», «можноНачать», «парами»,
       «переводной» (server/комнаты.js, показатьИгроку): именно на них
       стоит новый экран 05. Обычной игре вдвоём список мест не идёт вовсе
       (ждать там нечего, кроме одного друга) — этих полей у неё нет,
       и новый экран её по-настоящему не нарисует: ей остаётся прежний вид. */
    const компания = Array.isArray(вид.застолом);
    const новыйЭкранУмеет = компания && window.ДуракКомната &&
      typeof window.ДуракКомната.показать === 'function';
    if (новыйЭкранУмеет) {
      window.ДуракКомната.показать(вид, двериНовойКомнаты);
    } else {
      // Комната вдвоём или файл нового экрана не подключён — прежний вид;
      // если новый экран остался от прошлой комнаты, убираем его следом.
      спрятатьНовуюКомнату();
      показать('прихожая', компания);
      if (компания) {
        нарисоватьПрихожую(вид);
      } else {
        написать('ожидание-соперника', 'Ждём, когда друг войдёт по коду…');
        сказать('сообщение-прихожей', '');
      }
    }
    настроитьКнопкуОтмены(вид);
    показатьЭкран('экран-комнаты');
  }

  /* -------------------------------------------------------------------
     Прихожая: кто уже за столом и что можно нажать хозяину

     Прихожая — это несколько секунд перед раздачей карт, когда за столом
     собирается компания. Главный вопрос человека в эти секунды один:
     «все ли уже здесь». Поэтому список мест рисуется целиком — и занятые,
     и пустые, — а новости о приходе и уходе приносит длинный опрос, тот же
     самый, что потом носит ходы.
     ------------------------------------------------------------------- */

  /* Пока ответ на кнопку хозяина в пути, кнопки не трогаем: иначе пришедшая
     в эту секунду новость от опроса вернула бы им обычный вид, и человек
     решил бы, что нажатие не сработало. */
  let идётДействиеПрихожей = false;

  /* ---------- Пересадка: хозяин меняет двоих местами ----------

     Зачем это вообще. В игре парами напарник определяется местом — через
     одного, — и раньше человек не мог выбрать, с кем играет: кто первым
     вошёл, тот и напарник. Теперь хозяин ткнул в одно место, ткнул
     во второе — они поменялись.

     Выбранное место помним номером, а не узлом разметки: список мест
     перерисовывается заново на каждую новость от сервера, и ссылка
     на старый узел через секунду показывала бы на выброшенную строку. */
  let выбранноеМесто = 0;

  /* Что делает одиночное нажатие по месту за ПАРНЫМ столом.

     Владелец сказал прямо: «хочу поменять своего напарника», — а прежняя
     пересадка отвечала на другой вопрос, «поменяйте местами вот этих двоих».
     Отсюда два касания там, где мыслится одно, и лишняя умственная работа:
     сообразить, кого с кем менять. Поэтому за парным столом обычный тап
     теперь означает «беру этого в напарники», и кого с кем переставить,
     считает сервер.

     Прежний обмен никуда не делся: он нужен хозяину, чтобы рассаживать
     ЧУЖИХ людей, а не себя. Он включается отдельной кнопкой под списком
     («Поменять местами двоих») и гаснет сам, как только обмен сделан.

     Почему кнопка, а не долгое нажатие. Долгое нажатие невидимо — о нём
     никто не догадается, надписью его не объяснить; на телефоне оно ещё
     и спорит с прокруткой и выделением текста. Кнопка видна и объясняет
     себя сама, а самое частое действие остаётся самым коротким — один тап. */
  let режимОбменаМестами = false;

  /** Забыть выбор — например, когда пересадка удалась или мы ушли из комнаты. */
  function забытьВыборМеста() {
    выбранноеМесто = 0;
    режимОбменаМестами = false;
  }

  /** Стол парный и ещё собирается — значит, тап означает «в напарники». */
  function тапБерётВНапарники(вид) {
    return Boolean(вид) && вид.парами === true && вид.этап === 'ожидание' &&
           !режимОбменаМестами;
  }

  /**
   * Нажали на место. За парным столом одно нажатие берёт игрока
   * в напарники. В обмене местами (и за столом без пар) первое нажатие
   * выбирает, второе — меняет местами, повторное по тому же снимает выбор.
   */
  function нажалиНаМесто(номер) {
    if (идётДействиеПрихожей) return;      // ответ на прошлое нажатие ещё в пути
    if (!номер) return;

    if (тапБерётВНапарники(последнееСостояние)) {
      взятьВНапарники(номер);
      return;
    }

    if (выбранноеМесто === номер) {
      забытьВыборМеста();
      сказать('сообщение-прихожей', '');
      перерисоватьПрихожую();
      return;
    }
    if (!выбранноеМесто) {
      выбранноеМесто = номер;
      сказать('сообщение-прихожей',
        'Место ' + номер + ' выбрано. Нажмите второе место — они поменяются.');
      перерисоватьПрихожую();
      return;
    }

    const откуда = выбранноеМесто;
    забытьВыборМеста();
    пересадитьИгроков(откуда, номер);
  }

  /** Попросить сервер поменять двоих местами. Правило проверяет он, не мы. */
  function пересадитьИгроков(откуда, куда) {
    режимОбменаМестами = false;   // обмен сделан — возвращаемся к обычному тапу
    действиеПрихожей('пересадить', null, null, 'сообщение-прихожей',
                     { откуда: откуда, куда: куда });
  }

  /**
   * Попросить этого игрока себе в напарники. Кого с кем поменять местами,
   * решает сервер: правило рассадки («через одного») живёт там, и второй
   * его копии в браузере быть не должно.
   */
  function взятьВНапарники(номер) {
    действиеПрихожей('в-напарники', null, null, 'сообщение-прихожей',
                     { кого: номер });
  }

  /** Включить или выключить обмен местами (кнопка под списком мест). */
  function переключитьОбменМестами() {
    режимОбменаМестами = !режимОбменаМестами;
    выбранноеМесто = 0;
    сказать('сообщение-прихожей', режимОбменаМестами
      ? 'Обмен местами: нажмите на два места по очереди — они поменяются.'
      : '');
    перерисоватьПрихожую();
  }

  /* Перерисовать список мест по последнему известному состоянию — нужно
     после нажатия, чтобы выбор стал виден сразу, не дожидаясь новостей
     от сервера. */
  function перерисоватьПрихожую() {
    if (последнееСостояние && Array.isArray(последнееСостояние.застолом)) {
      нарисоватьМеста(последнееСостояние);
    }
  }

  function нарисоватьПрихожую(вид) {
    написать('прихожая-правила', словаПроСтолКомнаты(вид));
    нарисоватьМеста(вид);
    // Стол собирает только хозяин, остальные ждут. Кнопок у них нет вовсе:
    // кнопка, которая всегда отвечает отказом, хуже её отсутствия.
    показать('кнопки-хозяина', вид.яХозяин === true);
    написать('ожидание-соперника', словаПроСборСтола(вид));
    настроитьКнопкуНачать(вид);
  }

  /**
   * Что человеку делать в прихожей. Слова разные у четырёх случаев, и это
   * не украшательство: за парным столом главное действие — выбрать
   * напарника, и о нём должны узнать все, а не только хозяин. Раньше про
   * пересадку было написано в подсказке хозяина, и трое из четверых
   * не знали о ней вовсе.
   */
  function словаПроСборСтола(вид) {
    const парный = вид.парами === true;
    if (вид.яХозяин) {
      const начало = 'Скажите друзьям код. Все собрались — нажмите «Начать игру». ';
      return начало + (парный
        ? 'Нажмите на игрока — он станет вашим напарником.'
        : 'Хотите пересадить игроков — нажмите на два места по очереди, они поменяются.');
    }
    return парный
      ? 'Ждём, когда хозяин начнёт игру. Нажмите на игрока — он станет вашим напарником.'
      : 'Ждём, когда хозяин начнёт игру.';
  }

  /** Каким получился стол — по словам сервера, а не по нашему выбору. */
  function словаПроСтолКомнаты(вид) {
    const части = ['Играют ' + числоИгроков(Number(вид.мест) || МЕСТ_НА_ДВОИХ)];
    части.push(вид.парами ? 'парами, 2 на 2' : 'каждый сам за себя');
    if (вид.переводной) части.push('переводной');
    return части.join(', ') + '.' + словаПроНапарника(вид);
  }

  /**
   * С кем вы играете в паре. Без этой строчки пересадка бессмысленна:
   * человек не видит, зачем менять места, — в парной игре напарник
   * определяется местом (через одного), а не тем, кто когда вошёл.
   */
  function словаПроНапарника(вид) {
    if (!вид.парами || !Array.isArray(вид.застолом)) return '';
    const я = вид.застолом.find(function (место) { return место.этоЯ; });
    if (!я || !я.напарник) return '';
    const напарник = вид.застолом.find(function (место) {
      return Number(место.номер) === Number(я.напарник);
    });
    if (!напарник) return ' Ваш напарник — место ' + я.напарник + ', оно пока пустое.';
    return ' Вы в паре с: ' + напарник.имя + '.';
  }

  /**
   * Весь список мест заново — каждое на своём номере.
   *
   * Раньше сначала рисовались занятые места, а свободные добавлялись
   * хвостом, с точкой вместо номера. После «Убрать бота» получалось
   * «1, 3, ·»: человек видел, что второго места нет, и искал, куда оно
   * делось. Теперь идём по номерам подряд, и пустое место стоит ровно
   * там, где оно пустует.
   *
   * Номер места сервер присылает сам (поле «номер»), и это настоящий
   * номер за столом, а не позиция в списке присутствующих, — потому
   * дырка в середине и возможна.
   */
  function нарисоватьМеста(вид) {
    const список = узел('список-мест');
    if (!список) return;
    список.innerHTML = '';

    /* Кому места отзываются на нажатие. Правило проверяет сервер — здесь
       оно лишь для того, чтобы у остальных места не обещали лишнего:

         — стол парами: нажимает КАЖДЫЙ, потому что «взять в напарники» —
           это про себя, и хозяин тут ни при чём;
         — стол без пар: только хозяин, как было, — там нажатие означает
           обмен местами, а это распоряжение столом;
         — обмен местами (кнопкой) — тоже только хозяин.

       Карты розданы — не нажимается ни у кого. */
    const собираемСтол = вид.этап === 'ожидание';
    const яХозяин = вид.яХозяин === true;
    const можноПересаживать = собираемСтол &&
      (вид.парами === true ? (яХозяин || !режимОбменаМестами) : яХозяин);
    if (!можноПересаживать) забытьВыборМеста();
    // Обмен местами — распоряжение хозяина; чужой режим гасим.
    if (режимОбменаМестами && !(собираемСтол && яХозяин)) режимОбменаМестами = false;

    const места = вид.застолом || [];
    const поНомерам = new Map();
    for (const место of места) {
      const номер = Number(место.номер);
      if (Number.isFinite(номер) && номер >= 1) поНомерам.set(номер, место);
    }

    /* Хоть у одного места номера нет — значит, отвечает старый сервер,
       который их не присылал. Расставлять места по номерам тогда не из чего,
       и мы рисуем список по-старому: сначала занятые, потом свободные без
       номера. Выдумывать номера в этом случае нельзя — это была бы прямая
       ложь о том, кто где сидит. */
    if (поНомерам.size !== места.length) {
      for (const место of места) список.appendChild(строкаМеста(место, можноПересаживать));
      const всего = Number(вид.мест) || места.length;
      for (let пустое = места.length; пустое < всего; пустое++) {
        список.appendChild(строкаСвободногоМеста());
      }
      дорисоватьКнопкуОбмена(список, вид);
      return;
    }

    /* Докуда рисуем. Обычно это число мест за столом, но занятое место
       с номером больше — сильнее: стол мог уменьшиться уже после того, как
       игрок сел (сервер предупреждает об этом в «докудаЗанятСтол»). Возьми
       мы только «мест» — такой игрок молча пропал бы у всех с экрана. */
    let докуда = Number(вид.мест) || 0;
    for (const номер of поНомерам.keys()) {
      if (номер > докуда) докуда = номер;
    }
    if (!докуда) докуда = места.length;

    // Выбранное место могло исчезнуть — стол разрешено уменьшать.
    if (выбранноеМесто > докуда) забытьВыборМеста();

    for (let номер = 1; номер <= докуда; номер++) {
      const место = поНомерам.get(номер);
      список.appendChild(место
        ? строкаМеста(место, можноПересаживать)
        : строкаСвободногоМеста(номер, можноПересаживать && пустыеНажимаются(вид)));
    }
    дорисоватьКнопкуОбмена(список, вид);
  }

  /* Пустое место нажимается только там, где нажатие означает обмен: сесть
     рядом с пустотой можно, а вот «взять пустое место в напарники» — это
     ничего не значит, и сервер на такое отвечает отказом. */
  function пустыеНажимаются(вид) {
    return !тапБерётВНапарники(вид);
  }

  /**
   * Кнопка «Поменять местами двоих» под списком мест.
   *
   * Она есть только у хозяина парного стола: там обычный тап занят выбором
   * напарника, и обмену нужен свой вход. За столом без пар обмен и так
   * делается тапом, вторая дорога к нему только запутала бы.
   *
   * Кнопку рисуем кодом, а не разметкой: список мест целиком собирается
   * здесь же и перерисовывается на каждую новость от сервера.
   */
  function дорисоватьКнопкуОбмена(список, вид) {
    const нужна = вид.яХозяин === true && вид.парами === true && вид.этап === 'ожидание';
    if (!нужна) return;
    const кнопка = document.createElement('button');
    кнопка.type = 'button';
    кнопка.className = 'кнопка кнопка--выбор место-за-столом__обмен' +
                       (режимОбменаМестами ? ' кнопка--активная' : '');
    кнопка.textContent = режимОбменаМестами
      ? 'Готово, вернуться к выбору напарника'
      : 'Поменять местами двоих';
    кнопка.addEventListener('click', переключитьОбменМестами);
    список.appendChild(кнопка);
  }

  /**
   * Сделать строку места нажимаемой. Пустое место тоже нажимается: обмен
   * с пустым — это переезд, и он нужен не меньше обмена двух игроков.
   */
  function сделатьМестоНажимаемым(строка, номер, можно) {
    if (!можно || !номер) return;
    строка.className += ' место-за-столом--нажимается';
    строка.addEventListener('click', function () { нажалиНаМесто(Number(номер)); });
  }

  /** Одна ячейка строки. Классы двойные: от таблицы рекордов — раскладка,
   *  свои — чтобы дизайнеру было за что взяться. */
  function ячейкаМеста(строка, классы, текст) {
    const ячейка = document.createElement('span');
    ячейка.className = классы;
    ячейка.textContent = текст;
    строка.appendChild(ячейка);
    return ячейка;
  }

  function строкаМеста(место, можноПересаживать) {
    const строка = document.createElement('div');
    строка.className = 'таблица__строка место-за-столом' +
                       (место.этоЯ ? ' место-за-столом--я' : '') +
                       классПары(место) +
                       (место.номер === выбранноеМесто ? ' место-за-столом--выбрано' : '');
    ячейкаМеста(строка, 'таблица__место место-за-столом__номер', место.номер);
    const имя = ячейкаМеста(строка, 'таблица__очки место-за-столом__имя',
                            место.имя + (место.этоЯ ? ' — вы' : ''));
    /* Пометка пары живёт ВНУТРИ ячейки имени, а не отдельной колонкой:
       колонок в строке ровно четыре, и пятая уехала бы на новую строку,
       сломав раскладку. Свой класс у неё есть — дизайнер сможет сделать
       из неё что угодно, хоть цветную полосу. */
    if (номерПары(место)) {
      const пометка = document.createElement('span');
      пометка.className = 'место-за-столом__пара';
      пометка.textContent = ' пара ' + номерПары(место);
      имя.appendChild(пометка);
    }
    ячейкаМеста(строка, 'таблица__дата место-за-столом__роль', рольЗаСтолом(место));
    ячейкаМеста(строка, 'таблица__сложность место-за-столом__связь', какДелаУИгрока(место));
    сделатьМестоНажимаемым(строка, место.номер, можноПересаживать);
    return строка;
  }

  /**
   * Какая это пара — первая или вторая. Считаем не «через одного», а по
   * напарнику, которого назвал сервер: своего правила рассадки в браузере
   * нет и быть не должно. Имя паре даём по младшему из двух мест — так
   * у обоих напарников выходит одно и то же число.
   */
  function номерПары(место) {
    const напарник = Number(место.напарник);
    if (!напарник) return 0;
    return Math.min(Number(место.номер), напарник);
  }

  function классПары(место) {
    const пара = номерПары(место);
    return пара ? ' место-за-столом--пара-' + пара : '';
  }

  /** Кто это за столом: хозяин стола, бот или обычный игрок. */
  function рольЗаСтолом(место) {
    if (место.этоБот) return 'бот';
    return место.хозяин ? 'хозяин' : '';
  }

  /** Как дела у игрока — словами, без значков: их каждый толкует по-своему. */
  function какДелаУИгрока(место) {
    if (место.ушёл) return 'вышел';
    if (место.этоБот) return '';
    /* «На связи» — только если сервер сам это сказал. Без поля молчим:
       обещать, что человек онлайн, не зная этого, — враньё. */
    if (место.наСвязи === true) return 'на связи';
    return место.наСвязи === false ? 'нет связи' : '';
  }

  /* Номер у свободного места настоящий: строка стоит на своём месте в списке,
     и точка вместо номера сбивала бы счёт — именно из-за неё казалось,
     что второе место куда-то пропало. */
  function строкаСвободногоМеста(номер, можноПересаживать) {
    const строка = document.createElement('div');
    строка.className = 'таблица__строка место-за-столом место-за-столом--пусто' +
                       (номер === выбранноеМесто ? ' место-за-столом--выбрано' : '');
    ячейкаМеста(строка, 'таблица__место место-за-столом__номер',
                номер ? String(номер) : '·');
    ячейкаМеста(строка, 'таблица__очки место-за-столом__имя', 'Свободное место');
    ячейкаМеста(строка, 'таблица__дата место-за-столом__роль', '');
    ячейкаМеста(строка, 'таблица__сложность место-за-столом__связь', 'ждём');
    сделатьМестоНажимаемым(строка, номер, можноПересаживать);
    return строка;
  }

  /**
   * «Начать игру» не нажимается, пока за столом один человек: играть не с кем,
   * и сервер всё равно откажет. Пусть лучше кнопка честно молчит, чем отвечает
   * отказом на каждое нажатие.
   */
  function настроитьКнопкуНачать(вид) {
    const кнопка = узел('кнопка-начать-игру');
    if (!кнопка || идётДействиеПрихожей) return;
    кнопка.disabled = !вид.можноНачать;
  }

  /**
   * Кнопка «Собрать стол заново» на экране итога — показать или спрятать.
   *
   * Показываем её ровно тогда, когда сервер и вправду примет такое действие:
   * стол собран компанией (только там есть прихожая и хозяин), партия
   * кончилась и хозяин — я. Гадать не приходится: оба признака сервер
   * присылает сам («яХозяин» и «завершена»). Комнате на двоих поля
   * «яХозяин» не приходит вовсе, и кнопки там не будет — правильно,
   * прихожей в ней нет.
   *
   * Зачем эта кнопка вообще. Игрок, вышедший посреди партии, оставляет
   * вместо себя бота, и убрать его после партии нельзя — стол потихоньку
   * зарастает ботами. Раньше лечилось только новой комнатой и новой
   * рассылкой кода; теперь стол пересобирается на месте, с тем же кодом.
   */
  function обновитьКнопкуПересбора(вид) {
    const можно = Boolean(вид) && вид.яХозяин === true && вид.завершена === true;
    показать('кнопка-пересобрать', можно);
    // Спрятали кнопку — убираем и ответ сервера под ней: он был про неё.
    if (!можно) сказать('сообщение-пересбора', '');
  }

  /**
   * Внизу экрана одна кнопка значит разное: хозяин распускает стол, а гость
   * просто уходит из чужой комнаты. Надпись меняем прямо здесь и через
   * «занятьКнопку» эту кнопку не проводим — та запомнила бы первую надпись
   * и однажды вернула бы чужую.
   */
  function настроитьКнопкуОтмены(вид) {
    const надпись = вид.яХозяин === false ? 'Выйти из комнаты' : 'Отменить игру';
    const кнопка = узел('кнопка-комната-отмена');
    if (кнопка) кнопка.textContent = надпись;
    // Стрелка «‹» экрана комнаты (#кнопка-комната-назад) делает то же
    // самое действие — читалке экрана она должна называть его тем же
    // словом, что и кнопка внизу, а не всегда «Выйти из комнаты»: для
    // хозяина это не выход, а роспуск стола.
    const стрелка = узел('кнопка-комната-назад');
    if (стрелка) стрелка.setAttribute('aria-label', надпись);
  }

  /**
   * Нажатие на кнопку хозяина: посадить бота, убрать бота, начать игру.
   * Отказ сервера показываем словами как есть — он объясняет причину лучше
   * любой нашей догадки («Игра парами бывает только вчетвером, а за столом
   * трое»), и человеку нужно именно это.
   */
  function действиеПрихожей(действие, идКнопки, надписьНаВремя, кудаОтвечать, ещёПоля) {
    /* Куда писать ответ сервера. Обычно это строка под кнопками прихожей,
       но одна кнопка того же рода живёт на экране итога («Собрать стол
       заново»), а там строки прихожей не видно вовсе — отказ уходил бы
       в никуда. Разбор ответа при этом общий: всё, что здесь выверено про
       обрыв связи и пропавшую комнату, работает для обеих кнопок. */
    const строкаОтвета = кудаОтвечать || 'сообщение-прихожей';

    if (идётДействиеПрихожей) return;   // ответ на первое нажатие ещё в пути
    if (!код || !пропуск) {
      сказать(строкаОтвета, 'Комната уже закрыта — создайте игру заново.');
      return;
    }

    идётДействиеПрихожей = true;
    // Кнопки может и не быть вовсе: пересадку заказывают нажатием на само
    // место в списке, и занимать там нечего.
    if (идКнопки) занятьКнопку(идКнопки, надписьНаВремя);
    сказать(строкаОтвета, '');

    const моё = поколение;
    запросОтМеня('/ход', Object.assign({ действие: действие }, ещёПоля || {}))
        .then(function (ответ) {
      идётДействиеПрихожей = false;
      if (идКнопки) освободитьКнопку(идКнопки);
      if (ответУстарел(моё)) return;   // человек уже вышел из этой комнаты

      if (ответ.связьСорвалась) {
        связьПотеряна();
        сказать(строкаОтвета,
          'Связь с сервером пропала — попробуйте нажать ещё раз.');
        return;
      }
      if (ответ.номер === 404) {
        потерялиКомнату(ответ);
        return;
      }
      if (!ответ.ок) {
        сказать(строкаОтвета,
          ответ.данные.ошибка || 'Сервер не принял это действие.');
        return;
      }
      if (!ответ.данные.принято) {
        сказать(строкаОтвета, ответ.данные.причина || 'Так сейчас нельзя.');
      }
      // Состояние применяем в любом случае: даже отказ приходит вместе
      // со свежим списком мест.
      if (ответ.данные.состояние) принятьСостояние(ответ.данные.состояние);
    });
  }

  /**
   * Дверь «действие» для нового экрана комнаты (js/дурак-комната.js) —
   * тот же запрос «/ход», что и у действиеПрихожей выше, и то же поведение
   * при обрыве связи и пропавшей комнате (это касается всех вкладок, а не
   * только старого вида). Разница одна: здесь нет узлов старой прихожей,
   * куда можно было бы написать ответ, — он весь уходит в Promise, который
   * никогда не отклоняется, а решает, что показать, сам экран.
   */
  function действиеДвери(действие, поля) {
    if (!код || !пропуск) {
      return Promise.resolve({ принято: false, причина: 'Комната уже закрыта — создайте игру заново.' });
    }
    const моё = поколение;
    return запросОтМеня('/ход', Object.assign({ действие: действие }, поля || {}))
      .then(function (ответ) {
        if (ответУстарел(моё)) {
          // Человек уже вышел из этой комнаты — ответ ей больше не нужен.
          return { принято: false, причина: 'Комната уже закрыта — создайте игру заново.' };
        }
        if (ответ.связьСорвалась) {
          связьПотеряна();
          return { принято: false, причина: 'Связь с сервером пропала — попробуйте нажать ещё раз.' };
        }
        if (ответ.номер === 404) {
          потерялиКомнату(ответ);
          return { принято: false, причина: 'Комната уже закрыта — создайте игру заново.' };
        }
        if (!ответ.ок) {
          return {
            принято: false,
            причина: (ответ.данные && ответ.данные.ошибка) || 'Сервер не принял это действие.'
          };
        }
        // Состояние применяем в любом случае: даже отказ приходит вместе
        // со свежим списком мест, и остальные части страницы (строка связи,
        // кнопка пересбора) должны узнать об этом сразу же, как и раньше.
        if (ответ.данные.состояние) принятьСостояние(ответ.данные.состояние);
        return {
          принято: ответ.данные.принято === true,
          причина: ответ.данные.причина || '',
          состояние: ответ.данные.состояние || null
        };
      });
  }

  /* Что стоит в плашке, пока код не пришёл. Точки помечаются отдельным
     классом: без пометки они выглядят как настоящее значение, и человек
     начинает диктовать другу четыре точки. */
  const ТОЧКИ_ВМЕСТО_КОДА = '····';

  /** Тот же признак «код настоящий», что красит плашку и кнопку
   *  приглашения — вынесен наружу, чтобы js/дурак-комната.js не держал
   *  свою копию регулярного выражения (см. штаб/очередь.md, ревьюер
   *  12 сентября: разойдутся — плашка кода начнёт спорить с кнопкой). */
  function кодНастоящий(значение) {
    return /^[A-Z0-9]{4,}$/.test(значение || '');
  }

  function показатьКодКомнаты(значение, вид) {
    const плашка = узел('код-комнаты');
    if (!плашка) return;
    const настоящий = кодНастоящий(значение);
    плашка.textContent = настоящий ? значение : ТОЧКИ_ВМЕСТО_КОДА;
    плашка.classList.toggle('код-игры--ждём', !настоящий);
    /* Кнопка приглашения живёт по тому же правилу, что и плашка: есть
       настоящий код — есть куда звать друга. Одно место на обе стороны,
       и кнопка не может остаться висеть с чужим кодом от прошлой игры.
       «вид» передаём дальше — по нему решаем, есть ли ещё свободное
       место (см. обновитьКнопкуПриглашения). Без него (код очищаем,
       комнаты ещё нет) считаем, что место есть — решает только код. */
    обновитьКнопкуПриглашения(настоящий ? значение : '', вид);
  }

  /* -------------------------------------------------------------------
     Длинный опрос
     ------------------------------------------------------------------- */

  /** Сколько ждать перед следующей попыткой: чем дольше не выходит, тем реже стучимся. */
  function пауза() {
    const множитель = Math.pow(2, Math.max(0, попытокПодряд - 1));
    return Math.min(МАКСИМАЛЬНАЯ_ПАУЗА, ПАУЗА_ПОСЛЕ_СБОЯ * множитель);
  }

  function связьПотеряна() {
    попытокПодряд++;
    связьЕсть = false;
    освежитьСтрокуСвязи();
  }

  function связьВернулась() {
    попытокПодряд = 0;
    связьЕсть = true;
    когдаОтвечалСервер = Date.now();
    освежитьСтрокуСвязи();
  }

  /* Одни и те же слова на всю игру: комнаты больше нет. Раньше про это
     говорили в двух местах и по-разному — «сервер её больше не помнит»
     после сна страницы и «Прошлая игра уже закрыта» после перезагрузки,
     хотя случай один и тот же. */
  const СЛОВА_КОМНАТЫ_НЕТ =
    'Игра закрылась: сервер её больше не помнит. Создайте новую или войдите по коду.';

  /**
   * Наше место за столом уже занято: пока нас не было, там начали новую
   * партию, и вернуться некуда.
   *
   * Отличить это от «комнаты нет вовсе» страница сама не может: сервер
   * отвечает на оба случая одинаковым отказом. Поэтому ждём от него
   * отдельный признак и без него ведём себя ровно как раньше.
   *
   * Признак зовётся «местоЗаняли», а не «комната жива», нарочно, и имя
   * здесь важнее удобства. Сервер выдаёт его только тому, чей пропуск
   * комната помнит: признак «такая комната есть», выданный любому
   * спрашивающему, превратил бы отказ в подсказку для подбора чужих
   * комнат. Не читаем его как «комната существует» и не спрашиваем
   * им ничего про чужие комнаты.
   */
  function насНеДождались(ответ) {
    return Boolean(ответ && ответ.данные && ответ.данные.местоЗаняли);
  }

  /* Код комнаты, из которой нас не дождались. Живёт до первого открытия
     экрана входа: там он сам встанет в поле, и человеку не придётся
     выспрашивать код у друга. */
  let кодДляПовторногоВхода = '';

  /**
   * Что сказать человеку, которого не дождались. Вины его тут нет —
   * телефон уснул или метро; поэтому говорим о столе, а не о нём.
   * Места за столом не обещаем: его может и не найтись.
   */
  function словаПроНовуюПартию(кодКомнаты) {
    const начало = 'Пока вас не было, за столом начали новую партию — ' +
                   'вернуться в неё нельзя. ';
    if (!кодКомнаты) {
      return начало + 'Спросите у друга код и войдите заново: если за столом ' +
             'найдётся место, вас пустят.';
    }
    return начало + 'Нажмите «Войти по коду» — код ' + кодКомнаты +
           ' уже вписан. Если за столом найдётся место, вас пустят.';
  }

  /**
   * Нас не дождались. Со стола уходим так же, как при пропавшей комнате:
   * ключи там больше не наши. Запись о комнате тоже убираем — иначе в меню
   * осталась бы кнопка «Вернуться к игре с другом», которая привела бы
   * к этому же отказу. Вместо неё человек получает код в поле входа.
   */
  function насБольшеНеЖдут() {
    const кодКомнаты = код;      // берём до того, как ключи стёрли
    комнатаПропала(словаПроНовуюПартию(кодКомнаты));
    кодДляПовторногоВхода = кодКомнаты || '';
  }

  /**
   * Сервер отказал в возврате. Отказ у него один на три разных случая,
   * поэтому смотрим на признаки: пропуск сменён — тот же человек сел
   * с другого устройства; комната жива — нас не дождались; признаков
   * нет — комнаты нет вовсе.
   */
  function потерялиКомнату(ответ) {
    if (ответ && ответ.данные && ответ.данные.пропускСменён === true) вошлиСДругогоУстройства();
    else if (насНеДождались(ответ)) насБольшеНеЖдут();
    else комнатаПропала();
  }

  /**
   * Комната пропала: сервер её уже не помнит (перезапустили, вышли оба,
   * прошло много времени). Играть дальше нечем — честно об этом говорим.
   */
  function комнатаПропала(причина, показатьСвоё) {
    остановитьОпрос();
    новоеПоколение();
    забытьКомнату();
    код = null;
    пропуск = null;
    последнееСостояние = null;
    соперникПропалС = 0;
    спрятатьНовуюКомнату();   // комнаты 05 больше нет — прячем, если была видна
    const былиВПартии = вПартии;
    вПартии = false;
    приветствиеДо = 0;
    показатьСвязь('');
    остановитьЧасовогоСвязи();
    остановитьЧасовогоВладения();

    const мост = игра();
    if (былиВПартии && мост && typeof мост.вМеню === 'function') мост.вМеню();
    // Свой экран у случая «вошли с другого устройства» — туда и ведём.
    if (typeof показатьСвоё === 'function') {
      показатьСвоё();
      return;
    }
    /* Куда вести — решает «путьВКомнату» (см. её выше), тем же правилом,
       что и «Выйти из комнаты» (отменитьКомнату): пришли по новому пути
       (лобби, шаги, ссылка-приглашение) — назад в лобби, а не на экран
       «Игра с другом», которого человек не открывал. У лобби своей строки
       под причину пропажи нет — молчать честнее, чем писать это в чужой
       экран. */
    if (путьВКомнату === 'путь' && typeof показатьЛоббиДурака === 'function') {
      показатьЛоббиДурака();
    } else {
      показатьЭкран('экран-друга');
      сказать('сообщение-друга', причина || СЛОВА_КОМНАТЫ_НЕТ);
    }
  }

  function остановитьОпрос() {
    опросИдёт = false;
    // Обрываем висящий запрос: без этого он вернётся в уже закрытую
    // комнату и оставит в консоли красную ошибку.
    if (ручкаОпроса && ручкаОпроса.прервать) ручкаОпроса.прервать();
    ручкаОпроса = null;
  }

  /**
   * Стук в дверь после обрыва. Спрашиваем коротко, «как дела сейчас»,
   * а не «что нового»: длинный опрос придержал бы ответ на полминуты,
   * и всё это время человек читал бы «связь потеряна», хотя она уже есть.
   */
  function достучаться() {
    const моё = поколение;
    запросОтМеня('/состояние', {}).then(function (ответ) {
      if (!опросИдёт || ответУстарел(моё)) return;
      if (ответ.номер === 404) {
        потерялиКомнату(ответ);
        return;
      }
      if (ответ.связьСорвалась || !ответ.ок) {
        связьПотеряна();
        setTimeout(крутитьОпрос, пауза());
        return;
      }
      связьВернулась();
      if (ответ.данные.состояние) принятьСостояние(ответ.данные.состояние);
      крутитьОпрос();
    });
  }

  /* -------------------------------------------------------------------
     Свёрнута ли страница — для ленты бота (server/лента.js)

     Сервер пишет человеку в Telegram о событиях стола, только если тот стола
     не видит. Свёрнутое мини-приложение на Android часто продолжает опрос,
     и без этого признака сервер считал бы его «у экрана». Скрытой считаем
     страницу, если свёрнута вкладка браузера (document.hidden) или свёрнут
     сам Telegram (его события deactivated/activated). js/telegram.js здесь
     не нужен: к Telegram обращаемся напрямую и осторожно — вне Telegram
     его просто нет.
     ------------------------------------------------------------------- */

  let окноTelegramСпит = false;
  let слушаемДокумент = false;
  let слушаемTelegram = false;

  function страницаСкрыта() {
    if (окноTelegramСпит) return true;
    try {
      return document.hidden === true || document.visibilityState === 'hidden';
    } catch (сбой) {
      return false;
    }
  }

  /**
   * Подписаться на смену признака. Зовём при каждом опросе: скрипт Telegram
   * грузится с отсрочкой и к запуску этого файла его может ещё не быть.
   * Подписка ставится по разу — флаги не дают навесить её дважды.
   */
  function следитьЗаСкрытостью() {
    if (!слушаемДокумент) {
      try {
        document.addEventListener('visibilitychange', скрытостьСменилась);
        слушаемДокумент = true;
      } catch (сбой) { /* нет страницы — нечего и слушать */ }
    }
    if (слушаемTelegram) return;
    try {
      const приложение = window.Telegram && window.Telegram.WebApp;
      if (!приложение || typeof приложение.onEvent !== 'function') return;
      // Старый Telegram этих событий не шлёт — тогда остаётся document.hidden.
      if (приложение.isActive === false) окноTelegramСпит = true;
      приложение.onEvent('deactivated', function () {
        окноTelegramСпит = true;
        скрытостьСменилась();
      });
      приложение.onEvent('activated', function () {
        окноTelegramСпит = false;
        скрытостьСменилась();
      });
      слушаемTelegram = true;
    } catch (сбой) { /* Telegram без событий — не беда */ }
  }

  /**
   * Признак сменился, а висящий опрос унёс на сервер старый — и сервер
   * верил бы ему до конца опроса (до 25 с): свернувшему не написал бы,
   * вернувшемуся мог бы написать зря. Поэтому один раз прерываем опрос
   * и переспрашиваем с новым признаком. Это не обрыв связи: крутитьОпрос
   * видит пометку «переспросить» и сразу спрашивает снова, без паузы
   * и без строки «связь потеряна».
   */
  function скрытостьСменилась() {
    const ручка = ручкаОпроса;
    if (!опросИдёт || !ручка || !ручка.прервать || ручка.переспросить) return;
    if (ручка.скрыта === страницаСкрыта()) return;
    ручка.переспросить = true;
    ручка.прервать();
  }

  /**
   * Тело «что нового». Кроме версии — два поля для ленты бота:
   *   ссылка — ссылка за этот стол для кнопки «Открыть стол» в письмах.
   *            Сервер берёт её только от хозяина и после проверки, остальным
   *            она безвредна. Шлём при каждом опросе: первую после запуска
   *            сервер может отбросить, пока не узнал имя бота;
   *   скрыта — страница свёрнута, человек стола не видит.
   */
  function телоОпроса() {
    return {
      версия: версия,
      ссылка: ссылкаНаМиниПриложение(адресСервера(), код),
      скрыта: страницаСкрыта()
    };
  }

  /** Спросить сервер о новостях и, что бы ни случилось, спросить снова. */
  function крутитьОпрос() {
    if (!опросИдёт || !код || !пропуск) return;
    if (!связьЕсть) {
      достучаться();
      return;
    }

    следитьЗаСкрытостью();
    const моё = поколение;
    const тело = телоОпроса();
    const моя = { прервать: null, скрыта: тело.скрыта, переспросить: false };
    ручкаОпроса = моя;
    запросОтМеня('/что-нового', тело, ОЖИДАНИЕ_ОПРОСА, ручкаОпроса)
      .then(function (ответ) {
      if (!опросИдёт || ответУстарел(моё)) return;

      // Прервали сами ради нового признака «скрыта» — это не обрыв связи.
      if (моя.переспросить && ответ.связьСорвалась) {
        крутитьОпрос();
        return;
      }

      if (ответ.связьСорвалась) {
        связьПотеряна();
        setTimeout(крутитьОпрос, пауза());
        return;
      }
      if (ответ.номер === 404) {
        потерялиКомнату(ответ);
        return;
      }
      if (!ответ.ок) {
        // Сервер жив, но чем-то недоволен. Связь есть, поэтому просто
        // подождём и спросим снова — обычно это временная беда.
        связьПотеряна();
        setTimeout(крутитьОпрос, пауза());
        return;
      }

      связьВернулась();
      /* Длинный опрос приносит эту новость не отказом, а обычным ответом.
         Признак «место заняли» читаем и здесь: поставь сервер его только
         в одну из двух дверей, тексты разошлись бы, и человек получал бы
         разные объяснения одной и той же беды. */
      if (ответ.данные.комнатыНет || насНеДождались(ответ)) {
        потерялиКомнату(ответ);
        return;
      }
      if (ответ.данные.изменилось && ответ.данные.состояние) {
        принятьСостояние(ответ.данные.состояние);
      }
      крутитьОпрос();
    });
  }

  function запуститьОпрос() {
    if (опросИдёт) return;
    опросИдёт = true;
    крутитьОпрос();
  }

  /* -------------------------------------------------------------------
     Создание игры, вход и возвращение
     ------------------------------------------------------------------- */

  /* Пробный стук в дверь: он нужен только чтобы отличить «там никого нет»
     от «там отвечает чужая программа». Долго ждать ради этого нельзя —
     человек и так уже прождал обычный запрос. */
  const ПРОБНОЕ_ОЖИДАНИЕ = 4000;

  /**
   * Кто сидит по адресу сервера. Обычный запрос игры браузер мог зарубить
   * сам: чужая программа не разрешает к себе обращаться со страницы игры,
   * и для нас это выглядит ровно как выключенный сервер. Поэтому стучимся
   * второй раз, но так, что ответ нам не нужен (режим no-cors): важно
   * только, ответил ли хоть кто-нибудь. Ответил — по адресу живёт чужая
   * программа, промолчал — там нет никого.
   */
  function ктоНаАдресе(адрес) {
    const управление = typeof AbortController !== 'undefined' ? new AbortController() : null;
    /* Пропуска через туннель здесь нет нарочно: в режиме no-cors браузер
       необычные заголовки к запросу не добавляет вовсе — молча выбрасывает.
       И он тут не нужен: ответ мы всё равно не читаем, важен сам факт,
       что по адресу кто-то есть. */
    const настройки = { method: 'GET', mode: 'no-cors', cache: 'no-store' };
    if (управление) настройки.signal = управление.signal;

    return new Promise(function (готово) {
      /* Срок ждём сами, а не только через прерывание запроса: старый браузер
         без AbortController прервать запрос не умеет, и без этой строки
         обещание висело бы вечно. Первый ответ побеждает, опоздавший
         пропадает сам — второй раз обещание не срабатывает. */
      const сторож = setTimeout(function () {
        if (управление) управление.abort();
        готово('никого');
      }, ПРОБНОЕ_ОЖИДАНИЕ);
      fetch((адрес || адресСервера()) + '/', настройки).then(
        function () { clearTimeout(сторож); готово('чужая'); },
        function () { clearTimeout(сторож); готово('никого'); }
      );
    });
  }

  /* -------------------------------------------------------------------
     «Играть с другом сейчас нельзя»

     Сюда сходятся все беды, после которых партии с другом не будет:
     сервера нет вовсе, по адресу отвечает чужая программа, адрес записан
     не так, страница защищённая, а сервер обычный. Для человека, который
     не знает слов «сервер», «адрес» и «порт», все они означают ровно одно
     и то же — сейчас не получится. Поэтому и слов у него теперь одни,
     а разница между случаями ушла во второй слой.

     Как это выглядит:
       первый слой  — три фразы: почему не выйдет, что игра цела и кнопка
                      «Играть с ботом»;
       второй слой  — по кнопке «Почему так и что делать»: что можно
                      сделать, точная причина и адрес сервера.

     Почему второй слой открыт всем. Хозяина сервера от гостя мы отличаем
     на глазок, и признак иногда врёт: владелец, открывший свою же игру
     с телефона через туннель, выглядит гостем. Поэтому в обоих текстах
     есть обе двери — и «напишите тому, кто позвал», и «если сервер
     запускаете вы». Ошибка признака стоит человеку одного лишнего
     нажатия, а не тупика.

     Чего здесь нет нарочно: слов «скоро заработает» и «попробуйте позже».
     Мы этого не знаем. И обвинений телефону или связи игрока — этого мы
     тоже не знаем.
     ------------------------------------------------------------------- */

  /* Блок беды один на всю игру и переезжает на тот экран, где случилась
     беда. Вот перед чем он там встаёт. */
  const ЯКОРЬ_БЕДЫ = {
    'экран-друга': 'кнопка-адрес-сервера',
    'экран-входа': 'кнопка-адрес-из-входа'
  };

  /* Части блока — в том порядке, в каком человек их читает. */
  const ЧАСТИ_БЕДЫ = ['нет-сервера-главное', 'кнопка-играть-с-ботом',
                      'кнопка-почему-нет-сервера', 'нет-сервера-подробности'];

  /* Первый слой. Одинаков для всех бед: разбираться в них — работа
     второго слоя, а здесь человеку нужно понять, что делать сейчас.
     Текст короче прежнего (замер штаба 21.09: плашка на телефоне
     обрезалась снизу на 47 точек) — смысл тот же, слов меньше. */
  const БЕДА_ГЛАВНОЕ =
    'Играть с другом нельзя: игра живёт на компьютере того, кто её ' +
    'запустил, а он не в сети. Это не поломка — игра против бота ' +
    'работает прямо сейчас.';

  /* Отдельные слова для случая «адреса нет вовсе». Прежний текст тут врал
     дважды: обвинял чужой выключенный компьютер и намекал, что ждать
     бесполезно. На самом деле сервер может работать прекрасно — игра
     просто не знает, где он: ссылка, по которой её открыли, адреса
     не несла. Так и говорим, и сразу показываем выход.
     Короче прежнего по той же причине, что и БЕДА_ГЛАВНОЕ. */
  const БЕДА_БЕЗ_АДРЕСА =
    'Игра не знает адрес вашего сервера — ссылка его не принесла. ' +
    'Если сервер работает, впишите адрес кнопкой ниже: игра его ' +
    'запомнит. Игра против бота работает и без сервера.';

  /** Первый слой беды — по причине. */
  function словаПервогоСлоя(причина) {
    return причина === 'нет-адреса' ? БЕДА_БЕЗ_АДРЕСА : БЕДА_ГЛАВНОЕ;
  }

  let причинаБеды = null;          // чем именно кончилась попытка
  let адресБеды = '';              // адрес, на котором всё сорвалось
  let экранБеды = null;            // на каком экране блок стоит прямо сейчас
  let подробностиРаскрыты = false; // открыт ли второй слой

  /** Ведёт ли адрес на домашний компьютер, а не в интернет. */
  function адресНаСвойКомпьютер(адрес) {
    const имяСервера = String(адрес || '').replace(/^https?:\/\//i, '').split('/')[0];
    return АДРЕС_СВОЕГО_КОМПЬЮТЕРА.test(имяСервера);
  }

  /**
   * Похоже, что перед экраном хозяин сервера, а не позванный гость.
   * Признак нарочно грубый: игра открыта на своём компьютере — или человек
   * вписал руками домашний адрес, то есть сервер стоит у него же.
   *
   * Почему просто «вписывал адрес» тут не годится, хотя напрашивается.
   * Вписать адрес игра сама советует гостю — во втором слое так и сказано.
   * Гость слушается, вставляет присланный ему адрес туннеля, и на следующей
   * беде получает текст хозяина с «node server/сервер.js» — ровно те слова,
   * от которых мы его и уводили. Вписанный адрес туннеля — это почерк
   * гостя, а не хозяина, и признаком хозяина он быть не должен.
   *
   * Точным этот признак всё равно не будет, поэтому ошибаться ему разрешено:
   * оба текста ведут в обе стороны.
   */
  function похожеНаХозяина() {
    const свой = сохранённыйАдрес() || вписанныйАдрес;
    if (свой && адресНаСвойКомпьютер(свой)) return true;
    try {
      if (window.location.protocol === 'file:') return true;   // открыт файл с диска
      return АДРЕС_СВОЕГО_КОМПЬЮТЕРА.test(window.location.host || '');
    } catch (сбой) {
      return false;
    }
  }

  /**
   * Точная причина — та самая техническая правда, которую видел новичок
   * и не понял ни слова. Теперь она живёт только во втором слое.
   * Адрес берём тот, на котором всё сорвалось, а не нынешний: пока идёт
   * пробный стук, игра успевает передумать, по какому адресу ей ходить.
   */
  function словаПроПричину(причина, адрес) {
    if (причина === 'нет-адреса') {
      return 'Адреса сервера у игры нет: ссылка, по которой открыли игру, ' +
             'его не принесла, и вписанного адреса тоже нет. Это не значит, ' +
             'что сервер выключен, — игре просто некуда стучаться.';
    }
    if (причина === 'чужая') {
      return 'По адресу ' + адрес + ' отвечает какая-то другая программа, ' +
             'а не сервер игры. Значит, адрес не тот, и запускать сервер бесполезно.';
    }
    if (причина === 'запрет-браузера') {
      return 'Сервер записан по обычному адресу (' + адрес + '), а сама игра открыта ' +
             'по защищённому. Соединять их браузер не даёт — это его правило, ' +
             'а не поломка игры. Серверу нужен адрес на https, его даёт туннель.';
    }
    if (причина === 'плохой-адрес') {
      return 'Адрес сервера записан неправильно: ' + адрес + '.';
    }
    if (причина === 'проверяем') {
      return 'Игра стучится по адресу ' + адрес + ' — выясняем, что там.';
    }
    return 'По адресу ' + адрес + ' никто не отвечает: сервер не запущен ' +
           'или его адрес сменился.';
  }

  /** Второй слой для того, кого позвали играть: он до чужого компьютера не достанет. */
  function подробностиДляГостя(причина, адрес) {
    if (причина === 'нет-адреса') {
      return [
        словаПроПричину(причина, адрес),
        'Что можно сделать. Попросить у того, кто позвал вас играть, свежую ссылку: ' +
        'в ней адрес сервера едет сам, и вписывать ничего не придётся.',
        'Если сервер запускаете вы сами — впишите его адрес кнопкой ниже, ' +
        'игра запомнит его и в следующий раз спросит сама.'
      ];
    }
    return [
      'Чтобы игра вдвоём работала, у того, кто её запускает, должны быть включены ' +
      'компьютер и две программы на нём: сервер игры и труба наружу, через которую ' +
      'до него дотягиваются друзья.',

      'Что можно сделать. Играть против бота — для этого никакой сервер не нужен. ' +
      'И написать тому, кто позвал вас в игру: пусть включит игру вдвоём у себя ' +
      'и пришлёт свежую ссылку.',

      'Если сервер запускаете вы сами — вот что видит игра. ' +
      словаПроПричину(причина, адрес) + ' Вписать другой адрес можно кнопкой ниже.'
    ];
  }

  /** Второй слой для того, кто сервер и запускает. */
  function подробностиДляХозяина(причина, адрес) {
    if (причина === 'нет-адреса') {
      return [
        словаПроПричину(причина, адрес),
        'Так бывает, когда игру открыли прямо в Telegram — из списка приложений ' +
        'или по кнопке, в которой адреса нет. Сервер при этом может работать: ' +
        'проверить можно, открыв его адрес в браузере — он ответит словом «живой».',
        'Впишите адрес сервера кнопкой ниже — игра его запомнит и больше спрашивать ' +
        'не станет. Если играете не с того же компьютера, нужен адрес туннеля ' +
        '(cloudflared); он меняется при каждом запуске. Подробно — в README, раздел 6.'
      ];
    }
    return [
      словаПроПричину(причина, адрес),

      'Что проверить: запущен ли сервер игры (node server/сервер.js) и — если играете ' +
      'не с того же компьютера — запущен ли туннель (cloudflared). У быстрого туннеля ' +
      'адрес меняется при каждом запуске, а старый перестаёт работать: это самая частая ' +
      'причина. Всё это расписано в README, раздел 6.',

      'Свежий адрес сервера вписывается кнопкой ниже. А если сервер запускаете не вы — ' +
      'напишите тому, кто позвал вас в игру.'
    ];
  }

  /**
   * Положить в плашку несколько абзацев. Собираем из кусочков текста
   * вручную: в адресе сервера может быть что угодно (он приходит из ссылки),
   * и склеивать его в готовую разметку нельзя.
   */
  function написатьАбзацы(id, абзацы) {
    const место = узел(id);
    if (!место) return;
    место.textContent = '';
    абзацы.forEach(function (абзац, номер) {
      if (номер > 0) {
        место.appendChild(document.createElement('br'));
        место.appendChild(document.createElement('br'));
      }
      место.appendChild(document.createTextNode(абзац));
    });
  }

  /** Перенести блок беды на тот экран, где человек её встретил. */
  function перенестиБеду(экран) {
    const якорь = узел(ЯКОРЬ_БЕДЫ[экран]);
    if (!якорь || !якорь.parentNode) return;
    for (const id of ЧАСТИ_БЕДЫ) {
      const часть = узел(id);
      if (часть) якорь.parentNode.insertBefore(часть, якорь);
    }
    экранБеды = экран;
  }

  /** Написать второй слой заново — по запомненным причине и адресу. */
  function написатьПодробности() {
    const абзацы = похожеНаХозяина() ? подробностиДляХозяина(причинаБеды, адресБеды)
                                     : подробностиДляГостя(причинаБеды, адресБеды);
    написатьАбзацы('нет-сервера-подробности', абзацы);
  }

  /** Свернуть второй слой, не трогая первый. */
  function свернутьПодробности() {
    подробностиРаскрыты = false;
    показать('нет-сервера-подробности', false);
    написать('кнопка-почему-нет-сервера', 'Почему так и что делать');
  }

  /** Нажали «Почему так и что делать». */
  function переключитьПодробности() {
    if (подробностиРаскрыты) {
      свернутьПодробности();
      return;
    }
    подробностиРаскрыты = true;
    написатьПодробности();
    показать('нет-сервера-подробности', true);
    написать('кнопка-почему-нет-сервера', 'Свернуть подробности');
    // Человек полез разбираться — теперь ему можно показать и поле адреса.
    показатьВходВНастройку();
  }

  /**
   * Показать блок беды. Причина и адрес запоминаются: они нужны второму
   * слою, а он может открыться и позже. Адрес можно назвать явно — тот,
   * на котором всё сорвалось; не назвали — берём нынешний.
   */
  function показатьБеду(причина, экран, адрес) {
    причинаБеды = причина;
    адресБеды = адрес || адресСервера();
    перенестиБеду(экран);
    // Прежние объяснения убираем: две плашки подряд про одно и то же
    // человек читать не станет.
    сказать('сообщение-друга', '');
    сказать('сообщение-входа', '');
    сказать('нет-сервера-главное', словаПервогоСлоя(причина));
    показать('кнопка-играть-с-ботом', true);
    показать('кнопка-почему-нет-сервера', true);
    // Второй слой сам не раскрываем, но если он уже открыт — обновляем:
    // причина могла уточниться, пока человек читал.
    if (подробностиРаскрыты) написатьПодробности();
  }

  /** Убрать блок беды целиком. */
  function скрытьБеду() {
    причинаБеды = null;
    адресБеды = '';
    свернутьПодробности();
    показать('нет-сервера-главное', false);
    показать('кнопка-играть-с-ботом', false);
    показать('кнопка-почему-нет-сервера', false);
  }

  /**
   * Сервер промолчал. Показываем беду сразу, чтобы нажатие получило ответ
   * без задержки, а через секунду-другую, когда вернётся пробный стук,
   * уточняем причину во втором слое.
   */
  function рассказатьПочемуМолчит(экран, моё) {
    /* Адрес запоминаем до того, как забудем итог спора: сорвалось именно
       на нём. Иначе игра назовёт человеку другой адрес — тот, что записан
       в ссылке, — и чинить он будет не то, что сломалось. */
    const сорвалосьНа = адресСервера();
    /* Выбранный адрес только что подвёл. Значит, прошлый итог спора устарел:
       забываем его, и следующее нажатие заново выяснит, кто из двух адресов
       живой. Так игра переезжает на вписанный адрес, даже если адрес из
       ссылки умер уже после того, как мы его выбрали. */
    забытьИтогСпора();
    показатьБеду('проверяем', экран, сорвалосьНа);
    ктоНаАдресе(сорвалосьНа).then(function (кто) {
      if (ответУстарел(моё)) return;   // человек уже занялся другой игрой
      /* Блока уже нет — человек ушёл в меню или начал новую игру.
         Воскрешать объяснение нельзя. */
      if (!причинаБеды) return;
      /* И переносить блок больше нельзя: пока стук летел (а это до четырёх
         секунд), человек мог нажать «Указать адрес сервера» и уехать вместе
         с блоком на другой экран. Прежний код утащил бы объяснение обратно
         на покинутый экран, и человек остался бы с пустым местом там, где
         только что читал. Поэтому уточняем причину там, где блок стоит. */
      показатьБеду(кто === 'чужая' ? 'чужая' : 'никого', экранБеды, сорвалосьНа);
    });
  }

  /**
   * Нажали «Играть с ботом». Уводим в меню и нажимаем за человека большую
   * кнопку «Играть»: он уже сказал, чего хочет, и заставлять его нажимать
   * второй раз незачем.
   */
  function уйтиИгратьСБотом() {
    // Начатая попытка вернуться в старую партию могла ещё висеть в пути —
    // её ответ не должен вытащить человека из партии с ботом.
    отменитьВозврат();
    скрытьБеду();
    показатьЭкран('экран-меню');
    const кнопка = узел('кнопка-играть');
    if (кнопка) кнопка.click();
  }

  /* -------------------------------------------------------------------
     Адрес сервера, вписанный руками

     Зачем это вообще есть. Адрес сервера обычно приезжает в самой ссылке
     на игру, и трогать его человеку незачем. Но если ссылка старая, а бот
     молчит, то без этого места игра вдвоём становится тупиком: все
     объяснения советуют взять свежую ссылку, а взять её негде. Поэтому
     здесь — единственный путь, который человек проходит сам.

     Почему спрятано. Обычному игроку про адреса знать не нужно, и лишняя
     кнопка на главном экране игры вдвоём только пугает. Вход появляется
     ровно тогда, когда беда уже случилась (или когда адрес однажды
     вписали — чтобы его можно было поправить или стереть).
     ------------------------------------------------------------------- */

  /* Части настройки, которые прячутся и показываются вместе. Сообщение
     о ходе дел живёт отдельно: оно появляется и исчезает по смыслу. */
  const ЧАСТИ_НАСТРОЙКИ = ['адрес-подпись', 'поле-адреса', 'кнопка-проверить-адрес',
                           'кнопка-сохранить-адрес'];

  let настройкаОткрыта = false;
  let входВНастройкуОткрыт = false;   // человек уже упёрся в беду — прятать нечего

  /** Показать кнопку «Указать адрес сервера»: дальше без неё не пройти. */
  function показатьВходВНастройку() {
    входВНастройкуОткрыт = true;
    обновитьВходВНастройку();
  }

  function обновитьВходВНастройку() {
    // Вписанный когда-то адрес — тоже повод показать вход: его надо уметь
    // поправить и стереть, не дожидаясь новой беды.
    const надо = входВНастройкуОткрыт || Boolean(сохранённыйАдрес() || вписанныйАдрес);
    показать('кнопка-адрес-сервера', надо);
    показать('кнопка-адрес-из-входа', надо);
  }

  /**
   * Слова о том, по какому адресу игра стучится и почему именно по нему.
   * Ни одного «вообще-то»: если адресов два, прямо сказано, какой из них
   * в ходу, какой отложен и по какой причине.
   */
  function словаПроАдрес(приставка) {
    const кто = кандидаты();
    const адрес = адресСервера();
    const откуда = откудаАдрес();
    let текст = (приставка ? приставка + ' ' : '') +
                'Сейчас игра стучится по адресу ' + адрес + '. ';

    if (откуда === 'ссылка') {
      текст += 'Этот адрес взят из самой ссылки на игру.';
      if (кто.вписан && кто.вписан !== адрес) {
        // Победа адреса из ссылки бывает двух сортов: он живой — или живых
        // нет вовсе. Путать их нельзя, иначе человек будет искать беду не там.
        if (итогГодится() && !итогСпора.ссылкаЖива && !итогСпора.вписанныйЖив) {
          текст += ' Вписанный вами адрес (' + кто.вписан + ') сейчас тоже молчит, ' +
                   'поэтому играть пока не по чему: проверьте адреса и запустите сервер.';
        } else {
          текст += ' Вписанный вами адрес (' + кто.вписан + ') отложен: адрес из ссылки ' +
                   'отвечает, а он главнее — иначе по свежей ссылке нельзя было бы ' +
                   'перейти на новый сервер. Ваш адрес вступит в дело, как только ' +
                   'адрес из ссылки перестанет отвечать.';
        }
      }
    } else if (откуда === 'вписан') {
      текст += 'Этот адрес вы вписали сами.';
      if (кто.ссылка && кто.ссылка !== адрес) {
        текст += ' В самой ссылке на игру записан другой адрес (' + кто.ссылка + '), ' +
                 'но он не отвечает — поэтому игра ходит по вашему.';
      }
    } else {
      текст += 'Это встроенный запасной адрес — он годится только тогда, когда ' +
               'сервер запущен на этом же компьютере.';
    }
    return текст;
  }

  /** Рассказать, по какому адресу игра стучится сейчас и откуда он взялся. */
  function рассказатьПроАдрес(приставка) {
    // Пока неизвестно, какой из двух адресов живой, сказать правду нечем:
    // сначала стучимся, потом рассказываем.
    if (естьСпор() && !итогГодится()) {
      сказать('сообщение-адреса', (приставка ? приставка + ' ' : '') +
        'В ссылке на игру записан один адрес сервера, а вами вписан другой. ' +
        'Проверяем, какой из них отвечает…');
      решитьСпорАдресов().then(function () {
        сказать('сообщение-адреса', словаПроАдрес(приставка));
      });
      return;
    }
    сказать('сообщение-адреса', словаПроАдрес(приставка));
  }

  function открытьНастройкуАдреса() {
    настройкаОткрыта = true;
    входВНастройкуОткрыт = true;
    /* Второй слой сворачиваем: человек уже пошёл по техническому пути,
       и его совет «вписать адрес кнопкой ниже» выполнен. Сам блок беды
       остаётся на месте — без него экран выглядел бы так, будто ничего
       и не случилось. */
    свернутьПодробности();
    ЧАСТИ_НАСТРОЙКИ.forEach(function (id) { показать(id, true); });
    показать('кнопка-стереть-адрес', Boolean(сохранённыйАдрес() || вписанныйАдрес));
    const поле = узел('поле-адреса');
    // Подставляем нынешний адрес: чаще всего его надо не сочинить заново,
    // а поправить одну букву.
    if (поле && !поле.value) поле.value = сохранённыйАдрес() || вписанныйАдрес || адресСервера();
    рассказатьПроАдрес();
    обновитьВходВНастройку();
  }

  function закрытьНастройкуАдреса() {
    настройкаОткрыта = false;
    ЧАСТИ_НАСТРОЙКИ.forEach(function (id) { показать(id, false); });
    показать('кнопка-стереть-адрес', false);
    сказать('сообщение-адреса', '');
  }

  /** Нажатие на «Указать адрес сервера»: открыть настройку или свернуть её. */
  function переключитьНастройкуАдреса() {
    if (настройкаОткрыта) закрытьНастройкуАдреса();
    else открытьНастройкуАдреса();
  }

  /** То же самое, но с экрана входа по коду: сначала вернуть человека туда,
   *  где живёт поле адреса. */
  function открытьНастройкуСЭкранаВхода() {
    сказать('сообщение-друга', '');
    // Беда случилась на экране входа, а поле адреса живёт здесь. Забираем
    // объяснение с собой: иначе человек попадает на пустой экран с полем
    // и уже не помнит, из-за чего он тут оказался.
    if (причинаБеды) перенестиБеду('экран-друга');
    показатьЭкран('экран-друга');
    if (!настройкаОткрыта) открытьНастройкуАдреса();
  }

  /* Сколько ждём ответа на проверку. Дольше обычного запроса не нужно:
     человек стоит и смотрит на кнопку. */
  const ПРОВЕРКА_АДРЕСА_ЖДЁТ = 6000;

  /* А столько ждём в споре двух адресов. Здесь человек ничего не нажимал
     и ждать не подряжался, поэтому срок короче: живой сервер отвечает
     на «здоровье» мгновенно, а от мёртвого мы всё равно ничего не дождёмся. */
  const СПОР_АДРЕСОВ_ЖДЁТ = 4000;

  /**
   * Стук в дверь сервера: жив ли он по этому адресу. Отвечаем одним словом:
   *   'сервер-игры' — там наш сервер, играть можно;
   *   'не-игра'     — кто-то ответил, но это не сервер игры;
   *   'отказ'       — сервер отвечает, но эту страницу игры не пускает;
   *   'молчит'      — до двери не достучались.
   */
  function стукВДверь(адрес, сколькоЖдать) {
    const управление = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const сторож = setTimeout(function () {
      if (управление) управление.abort();
    }, сколькоЖдать || ПРОВЕРКА_АДРЕСА_ЖДЁТ);
    /* Пропуск через туннель нужен и здесь. Без него туннель отвечает
       своей страницей-предупреждением, игра считает живой сервер мёртвым
       и уводит человека чинить то, что и так работает. */
    const настройки = {
      method: 'GET', cache: 'no-store',
      headers: Object.assign({}, ПРОПУСК_ЧЕРЕЗ_ТУННЕЛЬ)
    };
    if (управление) настройки.signal = управление.signal;

    return fetch(адрес + '/здоровье', настройки).then(function (ответ) {
      clearTimeout(сторож);
      if (!ответ.ok) return { итог: 'отказ', номер: ответ.status };
      return ответ.json().then(
        function (данные) {
          if (!данные || !данные.живой) return { итог: 'не-игра' };
          /* Сервер заодно говорит, сколько комнат он сейчас помнит. Само
             по себе число нам не нужно, но ноль — это твёрдое знание:
             ни одной комнаты нет, значит нет и нашей. Пригодится тому,
             кто возвращается в сохранённую игру (см. «попробоватьВернуться»). */
          const комнат = Number(данные.комнат);
          return { итог: 'сервер-игры', комнат: Number.isFinite(комнат) ? комнат : null };
        },
        function () { return { итог: 'не-игра' }; }
      );
    }, function () {
      clearTimeout(сторож);
      return { итог: 'молчит' };
    });
  }

  /**
   * Отвечает ли по адресу именно наш сервер игры. Нужно для спора двух
   * адресов, поэтому ответ короткий — да или нет. Всё, кроме нашего живого
   * сервера, считаем «нет»: по чужой программе и по отказу играть нельзя
   * ровно так же, как по пустому месту.
   */
  function отвечаетЛиАдрес(адрес) {
    // Незащищённый адрес с защищённой страницы браузер не пропустит —
    // стучаться туда бессмысленно, только время терять.
    if (!адрес || браузерЗапретит(адрес)) return Promise.resolve(false);
    return стукВДверь(адрес, СПОР_АДРЕСОВ_ЖДЁТ).then(function (ответ) {
      return ответ.итог === 'сервер-игры';
    });
  }

  /**
   * То же самое, но для кнопки «Проверить»: человеку важно отличить чужую
   * программу от пустого места, поэтому в тишину стучимся второй раз —
   * ответ чужой программы браузер прячет от нас так же, как её отсутствие.
   */
  function постучатьсяВСервер(адрес) {
    return стукВДверь(адрес).then(function (ответ) {
      if (ответ.итог !== 'молчит') return ответ;
      return ктоНаАдресе(адрес).then(function (кто) {
        return { итог: кто === 'чужая' ? 'чужая' : 'молчит' };
      });
    });
  }

  let идётПроверкаАдреса = false;

  /**
   * Проверить адрес, который сейчас в поле, и честно сказать, что там.
   * Нужна до того, как человек начнёт создавать игру: иначе он узнает
   * о беде уже с кодом на руках и другом на проводе.
   */
  function проверитьАдресСервера(чьяКнопка) {
    if (идётПроверкаАдреса) return;
    const поле = узел('поле-адреса');
    const разбор = привестиАдрес(поле ? поле.value : '');
    if (!разбор.адрес) {
      ответитьНаКнопке(чьяКнопка, 'Адрес не понят');
      сказать('сообщение-адреса', разбор.беда);
      return;
    }
    if (поле) поле.value = разбор.адрес;   // показываем, что именно проверяем
    if (браузерЗапретит(разбор.адрес)) {
      ответитьНаКнопке(чьяКнопка, 'Так не выйдет');
      сказать('сообщение-адреса',
        'Такой адрес отсюда не сработает: он начинается с http://, а игра, открытая ' +
        'по этой ссылке, может стучаться только по адресам на https://. ' +
        'Впишите адрес туннеля — он выглядит так: https://имя-сервера.trycloudflare.com.');
      return;
    }

    идётПроверкаАдреса = true;
    занятьКнопку(чьяКнопка, 'Проверяем…');
    постучатьсяВСервер(разбор.адрес).then(function (ответ) {
      идётПроверкаАдреса = false;
      освободитьКнопку(чьяКнопка);
      const итог = чтоТамПоАдресу(ответ, разбор.адрес);
      сказать('сообщение-адреса', итог);
      /* Адресов два — тогда «отвечает ли этот» ещё не весь ответ: человеку
         надо знать, по какому из двух пойдёт игра. Дописываем это второй
         фразой, когда спор будет решён. */
      if (естьСпор()) {
        решитьСпорАдресов().then(function () {
          сказать('сообщение-адреса', итог + ' ' + словаПроАдрес());
        });
      }
    });
  }

  /** Слова для итога проверки — так, чтобы было понятно, что делать дальше. */
  function чтоТамПоАдресу(ответ, адрес) {
    if (ответ.итог === 'сервер-игры') {
      const свой = (сохранённыйАдрес() || вписанныйАдрес) === адрес;
      return 'Сервер игры отвечает — по этому адресу можно играть. ' +
             (свой ? 'Нажмите «Назад» и создавайте игру.'
                   : 'Нажмите «Сохранить адрес», чтобы игра его запомнила.');
    }
    if (ответ.итог === 'отказ') {
      return 'По адресу ' + адрес + ' сервер отвечает, но эту страницу игры не пускает ' +
             '(ответ ' + ответ.номер + '). Скорее всего, сервер настроен на другой сайт — ' +
             'спросите адрес у того, кто его запускал.';
    }
    if (ответ.итог === 'не-игра') {
      return 'По адресу ' + адрес + ' кто-то отвечает, но это не сервер игры. ' +
             'Проверьте адрес — возможно, он устарел.';
    }
    if (ответ.итог === 'чужая') {
      return 'По адресу ' + адрес + ' отвечает другая программа, а не сервер игры. ' +
             'Значит, адрес не тот.';
    }
    return 'По адресу ' + адрес + ' никто не отвечает. Если сервер запущен на своём ' +
           'компьютере — включите его. Если это туннель — его адрес мог смениться, ' +
           'возьмите свежий у того, кто запускал сервер.';
  }

  /** Запомнить вписанный адрес и тут же проверить, отвечает ли он. */
  function сохранитьАдресСервера() {
    const поле = узел('поле-адреса');
    const разбор = привестиАдрес(поле ? поле.value : '');
    if (!разбор.адрес) {
      ответитьНаКнопке('кнопка-сохранить-адрес', 'Адрес не понят');
      сказать('сообщение-адреса', разбор.беда);
      return;
    }
    if (поле) поле.value = разбор.адрес;   // показываем, что именно запомнили
    const легло = запомнитьАдрес(разбор.адрес);
    забытьИтогСпора();   // адрес поменялся — прошлый победитель уже не в счёт
    показать('кнопка-стереть-адрес', true);
    обновитьВходВНастройку();
    ответитьНаКнопке('кнопка-сохранить-адрес', легло ? 'Адрес сохранён' : 'Адрес принят');

    const начало = легло
      ? 'Адрес сохранён: ' + разбор.адрес + '. Браузер его помнит — вписывать заново не нужно.'
      : 'Адрес принят: ' + разбор.адрес + '. Запомнить его не вышло — браузер не дал ' +
        'доступ к своей памяти, поэтому после перезагрузки страницы впишите адрес снова.';

    /* В ссылке записан другой адрес — значит, спор, и решает его не наше
       желание, а то, кто из двух отвечает. Раньше на этом месте человеку
       говорили «играть всё равно будем по адресу из ссылки», и на мёртвой
       ссылке это был тупик: вписывать адрес было бессмысленно. */
    if (естьСпор()) {
      сказать('сообщение-адреса', начало +
        ' В ссылке на игру записан другой адрес — проверяем, какой из двух отвечает…');
      решитьСпорАдресов().then(function () {
        сказать('сообщение-адреса', словаПроАдрес(начало));
      });
      return;
    }
    сказать('сообщение-адреса', начало + ' Проверяем, отвечает ли он…');
    проверитьАдресСервера('кнопка-проверить-адрес');
  }

  /** Стереть вписанный адрес и вернуться к тому, что в ссылке. */
  function стеретьАдресСервера() {
    забытьАдрес();
    забытьИтогСпора();   // спорить больше не о чем: адрес остался один
    const поле = узел('поле-адреса');
    if (поле) поле.value = адресСервера();
    показать('кнопка-стереть-адрес', false);
    обновитьВходВНастройку();
    рассказатьПроАдрес('Вписанный адрес стёрт.');
  }

  /* -------------------------------------------------------------------
     Кто садится за стол: имя игрока и каким будет стол
     ------------------------------------------------------------------- */

  /**
   * Как звать игрока за столом. Имя берём у Telegram — оно там уже есть,
   * и спрашивать человека незачем. Имени нет (игра открыта в обычном
   * браузере) — ничего не выдумываем: сервер сам назовёт «Игрок 2» по номеру
   * места.
   *
   * Почему имя добывается здесь, а не в js/telegram.js: тот файл отдаёт
   * наружу ровно три функции про рекорды, имени среди них нет. Поэтому
   * спрашиваем Telegram сами и очень осторожно — любая беда молча
   * превращается в «имени нет», и игра идёт дальше.
   */
  function имяИгрока() {
    try {
      const приложение = window.Telegram && window.Telegram.WebApp;
      const кто = приложение && приложение.initDataUnsafe && приложение.initDataUnsafe.user;
      if (!кто) return '';
      return String(кто.first_name || кто.username || '').trim();
    } catch (сбой) {
      return '';
    }
  }

  /**
   * Подпись Telegram — строка, которой Telegram удостоверяет, кто мы такие.
   * Сервер по ней узнаёт номер игрока и только по ней: имя из тела запроса
   * для этого не годится, назваться чужим именем может кто угодно.
   *
   * Нужна она ровно для одного — чтобы после партии в списке знакомых
   * появились имена тех, с кем сидели за столом. Подписи нет (игру открыли
   * в обычном браузере) — уходит пустая строка, и всё работает как раньше,
   * только знакомств не заводится.
   */
  function подписьTelegram() {
    try {
      const приложение = window.Telegram && window.Telegram.WebApp;
      return (приложение && приложение.initData) || '';
    } catch (сбой) {
      return '';
    }
  }

  /* Каким будет стол. Пока человек ничего не трогал, здесь стоит обычная
     игра вдвоём — ровно та, что была в игре с другом всегда. */
  const МЕСТ_НА_ДВОИХ = 2;
  const САМЫЙ_БОЛЬШОЙ_СТОЛ = 6;
  const ИГРОКОВ_В_ПАРАХ = 4;      // парная игра бывает только вчетвером

  /* «компанией» — true у пути режима «друзья» (js/дурак-путь.js через
     js/game.js): даже стол «2, не переводной, не парами» должен уйти на
     сервер со списком мест, чтобы новый экран 05 (js/дурак-комната.js) было
     чем нарисовать. Кнопки старого экрана «Игра с другом» это поле не трогают —
     там всё решает «столОбычный», как и раньше. */
  const выборСтола = { мест: МЕСТ_НА_ДВОИХ, переводной: false, парами: false, компанией: false, открытый: false };

  /** Человек ничего не менял — значит, это прежняя игра вдвоём. */
  function столОбычный() {
    return выборСтола.мест === МЕСТ_НА_ДВОИХ &&
           !выборСтола.переводной && !выборСтола.парами;
  }

  /* Числа словами: «играют трое» читается легче, чем «играют 3». */
  const ЧИСЛО_СЛОВАМИ = { 2: 'двое', 3: 'трое', 4: 'четверо', 5: 'пятеро', 6: 'шестеро' };

  function числоИгроков(сколько) {
    return ЧИСЛО_СЛОВАМИ[сколько] || (сколько + ' игроков');
  }

  /**
   * Что уходит серверу в запросе «создать».
   *
   * Настройки стола шлём только тогда, когда человек их менял: комната
   * с настройками — это комната на компанию, с прихожей и кнопкой «Начать».
   * Ничего не трогал — уходит одно имя, и получается прежняя комната
   * на двоих, где карты раздаются сами, как только войдёт друг. Одно имя
   * настройкой не считается, поэтому старая игра вдвоём не меняется.
   *
   * Исключение — «компанией»: путь режима «друзья» просит список мест
   * всегда, даже когда стол сам по себе получился «обычным» (двое, не
   * переводной, не парами). Без этого поля сервер понял бы такой стол как
   * прежнюю комнату вдвоём без списка мест — а новый экран 05 её не рисует.
   */
  function телоСоздания() {
    const тело = {};
    /* Во что играем. Шлём всегда, и дурак тоже: старый сервер лишнее поле
       просто не заметит, а новый по нему поймёт, какие правила ставить
       на стол. Число мест НЕ шлём: сколько их у этой игры, сервер знает
       сам (у шашек их ровно два), а присланное число включило бы прихожую
       с кнопкой «Начать» — шашкам она не нужна, там ждать нечего. */
    тело.игра = ИГРА_ЭТОЙ_СТРАНИЦЫ;
    if (ИГРА_ЭТОЙ_СТРАНИЦЫ === 'монополия') {
      const n = Number(узел('монополия-мест-друга')?.value);
      тело.мест = [2,3,4,5,6].includes(n) ? n : 4;
      тело.парами = false;
    }
    if (ИГРА_ЭТОЙ_СТРАНИЦЫ === 'катан') {
      const мест = Number(узел('катан-мест-друга')?.value);
      тело.мест = [3, 4].includes(мест) ? мест : 4;
      тело.катанНастройки = window.КатанНастройкиСтола?.() || {};
    }
    if (ИГРА_ЭТОЙ_СТРАНИЦЫ === 'домино') {
      const цель = Number(узел('домино-цель-друга')?.value);
      const мест = Number(узел('домино-мест-друга')?.value);
      тело.цельДомино = [50, 100, 150].includes(цель) ? цель : 100;
      тело.мест = [2, 3, 4].includes(мест) ? мест : 2;
    }
    if (ИГРА_ЭТОЙ_СТРАНИЦЫ === 'деберц') {
      const цель = Number(узел('деберц-цель-друга')?.value);
      тело.цельДеберца = [301, 501, 1001].includes(цель) ? цель : 301;
      const режим = узел('деберц-режим-друга')?.value;
      if (['2', '3', '4', '2x2'].includes(режим)) {
        тело.мест = режим === '2x2' ? 4 : Number(режим);
        тело.парами = режим === '2x2';
      }
    }
    const имя = имяИгрока();
    if (имя) тело.имя = имя;
    /* Подпись — чтобы сервер знал, кто сел за стол, и потом смог показать
       нас в списке знакомых у тех, с кем мы сыграли. Настройкой стола она
       не считается: комната от неё прежней и остаётся. */
    const подпись = подписьTelegram();
    if (подпись) тело.initData = подпись;
    /* Открытый — стол виден всем в списке «Играть онлайн», а не только
       тому, у кого есть код. Признак не зависит от «столОбычный»/«компанией»
       и шлётся отдельно, даже если ниже сработает ранний выход. */
    if (выборСтола.открытый) тело.открытый = true;
    if (['деберц', 'домино', 'катан', 'монополия'].includes(ИГРА_ЭТОЙ_СТРАНИЦЫ)) return тело;
    if (столОбычный() && !выборСтола.компанией) return тело;
    тело.мест = выборСтола.мест;
    тело.переводной = выборСтола.переводной;
    тело.парами = выборСтола.парами;
    return тело;
  }

  /** Отметить нажатую кнопку в ряду выбора и погасить остальные. */
  function отметитьВыбор(идБлока, значение) {
    const блок = узел(идБлока);
    if (!блок) return;
    for (const кнопка of блок.querySelectorAll('.кнопка--выбор')) {
      кнопка.classList.toggle('кнопка--активная', кнопка.value === значение);
    }
  }

  /** Показать выбранное на кнопках и объяснить словами, что получится. */
  function показатьВыборСтола() {
    отметитьВыбор('выбор-мест', String(выборСтола.мест));
    отметитьВыбор('выбор-перевода', выборСтола.переводной ? 'переводной' : 'обычный');
    отметитьВыбор('выбор-пар', выборСтола.парами ? 'парами' : 'каждый');
    написать('пояснение-стола', словаПроВыборСтола());
  }

  /**
   * Что получится при нынешнем выборе — обычными словами, без терминов.
   *
   * Пояснение живёт в отведённом ему месте в четыре строки, поэтому каждая
   * фраза здесь короткая нарочно: длинный текст выталкивал вёрстку вниз.
   * По той же причине пропала фраза «парами играют только вчетвером» —
   * она показывалась ровно тогда, когда человек уже нажал «парами»
   * и число мест на его глазах стало четыре.
   */
  function словаПроВыборСтола() {
    if (столОбычный()) {
      return 'Обычная игра вдвоём: карты раздадутся сами, как только друг войдёт по коду.';
    }
    let текст = 'Играют ' + числоИгроков(выборСтола.мест) + '. ';
    текст += выборСтола.парами
      ? 'Парами: двое против двоих, напарник напротив. '
      : 'Каждый сам за себя. ';
    if (выборСтола.переводной) {
      текст += 'Переводной: положите такую же карту — и отбивается сосед. ';
    }
    return текст + 'Свободные места можно занять ботами. Игру начнёте вы — кнопкой.';
  }

  /**
   * Выбрать, сколько человек за столом. Игра парами бывает только вчетвером,
   * поэтому вместе с другим числом мест она выключается сама — и об этом
   * сказано сразу, а не отказом в последнюю минуту, когда все уже собрались.
   */
  function выбратьМеста(сколько) {
    const число = Number(сколько);
    if (!(число >= МЕСТ_НА_ДВОИХ && число <= САМЫЙ_БОЛЬШОЙ_СТОЛ)) return;
    выборСтола.мест = число;
    if (выборСтола.парами && число !== ИГРОКОВ_В_ПАРАХ) выборСтола.парами = false;
    показатьВыборСтола();
  }

  /**
   * Включить или выключить игру парами. Включили при другом числе мест —
   * сами ставим четыре: человек выбирал игру, а не число мест, и упираться
   * тут не во что.
   */
  function выбратьПары(парами) {
    выборСтола.парами = парами;
    if (парами) выборСтола.мест = ИГРОКОВ_В_ПАРАХ;
    показатьВыборСтола();
  }

  /** Повесить одно действие на все кнопки одного ряда выбора. */
  function накнопкиВыбора(идБлока, действие) {
    const блок = узел(идБлока);
    if (!блок) {
      // Ряды выбора правил — тоже стол дурака (см. УЗЛЫ_ТОЛЬКО_У_ДУРАКА).
      if (!молчатьПроУзел(идБлока)) {
        console.warn('Игра вдвоём: не нашёл выбор «' + идБлока + '». ' +
                     'Скорее всего, браузер показывает старую страницу — обновите её (Ctrl+F5).');
      }
      return;
    }
    for (const кнопка of блок.querySelectorAll('.кнопка--выбор')) {
      кнопка.addEventListener('click', function () { действие(кнопка.value); });
    }
  }

  function подключитьВыборСтола() {
    накнопкиВыбора('выбор-мест', выбратьМеста);
    накнопкиВыбора('выбор-перевода', function (значение) {
      выборСтола.переводной = (значение === 'переводной');
      показатьВыборСтола();
    });
    накнопкиВыбора('выбор-пар', function (значение) {
      выбратьПары(значение === 'парами');
    });
    показатьВыборСтола();
  }

  /* Пока ответ на «создать» или «войти» не пришёл, второй такой же запрос
     не отправляем: двойной тап на телефоне — обычное дело, а на сервере
     от него оставались две комнаты, и первая висела мусором. */
  let создаёмИгру = false;
  let входимВИгру = false;

  /* Нажали «Создать игру». Если адреса два и неизвестно, какой из них
     живой, сперва выясняем это: иначе игра создалась бы не на том сервере,
     а друг вошёл бы в пустоту. */
  function создатьИгру() {
    // Явный старый вход — с экрана «Игра с другом»: «Выйти из комнаты»
    // должен вернуть сюда же (см. «путьВКомнату» выше).
    путьВКомнату = 'друг';
    приВыбранномАдресе('кнопка-создать-игру', создатьИгруНаСервере);
  }

  /**
   * «итог» — необязательный: его передаёт только дверь «создатьКомнату»
   * (шаги дурака). Зовётся один раз — { ок: true }, когда комната создана,
   * или { ок: false, причина }, когда нет. Кнопка «Создать игру» его не
   * передаёт, и для неё всё идёт как раньше.
   */
  function создатьИгруНаСервере(итог) {
    const сообщить = typeof итог === 'function' ? итог : function () {};
    if (создаёмИгру) {                // ответ на первое нажатие ещё в пути
      сообщить({ ок: false, причина: 'Комнату уже создаём', тихо: true });
      return;
    }

    const беда = бедаАдреса(адресСервера());
    if (беда) {
      // Объяснение показываем именно здесь, по нажатию. Раньше оно висело
      // на экране заранее, и от нажатия не менялось ничего — человек видел
      // сломанную кнопку и не знал, чего ждать.
      ответитьНаКнопке('кнопка-создать-игру', 'Сейчас не получится');
      показатьБеду(беда, 'экран-друга');
      сообщить({ ок: false, причина: беда });
      return;
    }

    создаёмИгру = true;
    занятьКнопку('кнопка-создать-игру', 'Создаём игру…');
    сказать('сообщение-друга', '');
    скрытьБеду();
    // Старый код с прошлой игры показывать нельзя: его уже никто не ждёт.
    показатьКодКомнаты('');
    сказать('сообщение-копирования', '');
    // Список из прошлой комнаты тоже чужой: его соберём заново по ответу.
    показать('прихожая', false);
    сказать('сообщение-прихожей', '');

    const моё = новоеПоколение();
    запрос('/создать', телоСоздания()).then(function (ответ) {
      создаёмИгру = false;
      освободитьКнопку('кнопка-создать-игру');
      if (ответУстарел(моё)) {         // человек уже ушёл в другую игру
        сообщить({ ок: false, причина: 'Ответ опоздал', тихо: true });
        return;
      }
      if (ответ.связьСорвалась) {
        рассказатьПочемуМолчит('экран-друга', моё);
        сообщить({ ок: false, причина: 'Сервер не отвечает' });
        return;
      }
      if (!ответ.ок || !ответ.данные.код) {
        const причина = ответ.данные.ошибка || 'Сервер не смог создать игру.';
        сказать('сообщение-друга', причина);
        сообщить({ ок: false, причина: причина });
        return;
      }
      сказать('сообщение-друга', '');
      начатьЖизньВКомнате(ответ.данные.код, ответ.данные.пропуск, ответ.данные.состояние);
      сообщить({ ок: true });
    });
  }

  /* -------------------------------------------------------------------
     Комната со столом, выбранным на шагах дурака (js/дурак-путь.js)

     Шаги сами спрашивают, сколько мест, переводной ли и парами ли, и в
     конце зовут эту дверь. Дальше — та же дорога, что у «Создать игру»:
     адрес сервера, запрос «/создать», экран комнаты с кодом.

     Не вышло (сервер недоступен, адрес плохой, сервер отказал) — ведём
     на экран «Игра с другом»: объяснение беды, «Указать адрес сервера»
     и «Играть с ботом» живут там (решение штаба). Выбор стола на том
     экране уже стоит тот же, что на шагах, — можно просто нажать
     «Создать игру» ещё раз.
     ------------------------------------------------------------------- */

  /** Положить стол с шагов в выбор стола. Непонятное — не трогаем. */
  function поставитьСтолКомнаты(стол) {
    const набор = стол || {};
    const мест = Number(набор.мест);
    if (Number.isInteger(мест) && мест >= МЕСТ_НА_ДВОИХ && мест <= САМЫЙ_БОЛЬШОЙ_СТОЛ) {
      выборСтола.мест = мест;
    }
    выборСтола.переводной = набор.переводной === true;
    // Парами — только вчетвером, как и кнопками на экране друга.
    выборСтола.парами = набор.парами === true && выборСтола.мест === ИГРОКОВ_В_ПАРАХ;
    // См. пояснение у «выборСтола» выше: только этот путь ставит признак.
    выборСтола.компанией = набор.компанией === true;
    // Открытый — стол мастера «Создать игру» виден всем в списке «Играть
    // онлайн» (решение штаба). Ставит признак только js/дурак-путь.js.
    выборСтола.открытый = набор.открытый === true;
    показатьВыборСтола();
  }

  /** Не вышло — на экран друга, не стирая объяснения беды (как «открытьЭкранДруга» стёр бы). */
  function наЭкранДругаСБедой() {
    показатьЭкран('экран-друга');
    обновитьВходВНастройку();
  }

  /**
   * Создать комнату с этим столом. Отвечает обещанием, которое не срывается:
   * { ок: true } — комната есть, на экране комната с кодом;
   * { ок: false, причина } — нет, на экране «Игра с другом» с объяснением
   * («тихо: true» — повторное нажатие или опоздавший ответ: никуда не ведём).
   */
  function создатьКомнатуСоСтолом(стол) {
    // Единственная точка входа с шагов дурака (js/дурак-путь.js): значит,
    // «Выйти из комнаты» должен вести в лобби (см. «путьВКомнату» выше).
    путьВКомнату = 'путь';
    поставитьСтолКомнаты(стол);
    return new Promise(function (ответить) {
      приВыбранномАдресе(null, function () {
        создатьИгруНаСервере(function (итог) {
          if (!итог.ок && !итог.тихо) наЭкранДругаСБедой();
          ответить(итог);
        });
      });
    });
  }

  /** Привести набранный код к виду, который понимает сервер. */
  function очиститьКод(что) {
    return String(что || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 6);
  }

  /* ---------- Отказ во входе: понятная причина и выход из тупика ----------

     Сервер говорит, почему не пустил, машинным словом «почему»
     (server/комнаты.js). Раньше человек видел одну фразу на все случаи
     и оставался на экране входа без дела. Теперь — своя причина и два
     действия: сразу создать новый стол этой же игры или уйти в лобби. */

  const СЛОВА_ОТКАЗА_ВХОДА = {
    'закрыта': 'Стол закрыт — друг уже убрал его или время ожидания вышло.',
    'идёт': 'Партия уже началась — за этот стол сейчас не сесть.',
    'заполнена': 'Мест нет — за столом уже сидят все игроки.',
    'нет': 'Стола нет — возможно, сервер перезапускался. Попросите новую ссылку или создайте стол сами.'
  };

  /** Слова для причины отказа или '' — если причина незнакомая. */
  function словаОтказаВхода(почему) {
    if (typeof почему !== 'string') return '';
    return Object.prototype.hasOwnProperty.call(СЛОВА_ОТКАЗА_ВХОДА, почему)
      ? СЛОВА_ОТКАЗА_ВХОДА[почему] : '';
  }

  /* Кнопки под сообщением входа. Разметки для них в страницах нет, и
     страниц восемь — поэтому их ставит сюда сам этот файл, из общих
     классов кнопок. «когда» — при каком случае кнопка видна:
     отказ — сервер не пустил; устройство — вошли с другого устройства. */
  const КНОПКИ_ОТКАЗА = [
    { id: 'кнопка-играть-здесь', слова: 'Играть здесь', классы: 'кнопка кнопка--главная',
      когда: ['устройство'], действие: игратьЗдесь },
    /* Главная кнопка отказа — класс «кнопка» сам по себе уже акцентный
       (салатовый); «кнопка--главная» тут не нужен — иначе она сливается
       с «Играть здесь» (тот случай тут не бывает одновременно, но
       смотритель судит по каждому снимку отдельно). */
    { id: 'кнопка-новый-стол', слова: 'Создать новый стол', классы: 'кнопка',
      когда: ['отказ'], действие: создатьНовыйСтолПослеОтказа },
    /* Второстепенная — тем же классом, что везде в проекте отличает
       «уводящую» кнопку от главного действия. */
    { id: 'кнопка-отказ-в-лобби', слова: 'В лобби', классы: 'кнопка кнопка--мелкая',
      когда: ['отказ', 'устройство'], действие: вЛобби }
  ];

  /** Поставить кнопки под сообщением входа, если их ещё нет. Нет сообщения — false. */
  function завестиКнопкиОтказа() {
    const сообщение = узел('сообщение-входа');
    if (!сообщение || typeof сообщение.insertAdjacentElement !== 'function') return false;
    let после = сообщение;
    for (const описание of КНОПКИ_ОТКАЗА) {
      let кнопка = узел(описание.id);
      if (!кнопка) {
        кнопка = document.createElement('button');
        кнопка.id = описание.id;
        кнопка.type = 'button';
        кнопка.className = описание.классы + ' скрыт';
        кнопка.textContent = описание.слова;
        кнопка.addEventListener('click', описание.действие);
        после.insertAdjacentElement('afterend', кнопка);
      }
      после = кнопка;
    }
    return true;
  }

  /** Показать кнопки для случая «вид» ('отказ' или 'устройство'). */
  function показатьВыходИзОтказа(вид) {
    if (!завестиКнопкиОтказа()) return;
    for (const описание of КНОПКИ_ОТКАЗА) {
      показать(описание.id, описание.когда.indexOf(вид) !== -1);
    }
    /* С тем же кодом ещё раз не зайти — сервер откажет ровно так же.
       «Войти в игру» прячем, чтобы не звать пробовать заново вхолостую;
       вернётся, когда код поменяют или уйдут с экрана (см. ниже).
       Случай «устройство» — не отказ, а перехват своего же стола:
       код можно вводить снова, кнопку не трогаем. */
    if (вид === 'отказ') показать('кнопка-войти', false);
  }

  function спрятатьВыходИзОтказа() {
    for (const описание of КНОПКИ_ОТКАЗА) показать(описание.id, false);
    показать('кнопка-войти', true);
  }

  /** «Создать новый стол» — сразу, той же дверью, что шаги дурака: стол этой же игры. */
  function создатьНовыйСтолПослеОтказа() {
    спрятатьВыходИзОтказа();
    сказать('сообщение-входа', '');
    создатьКомнатуСоСтолом({});
  }

  /** «В лобби» — лобби этой игры; своё «назад» у игры сильнее. */
  function вЛобби() {
    спрятатьВыходИзОтказа();
    сказать('сообщение-входа', '');
    скрытьБеду();
    const мост = игра();
    if (мост && typeof мост.назадСоВхода === 'function') {
      мост.назадСоВхода();
    } else if (typeof показатьЛоббиДурака === 'function') {
      показатьЛоббиДурака();
    } else if (узел('экран-лобби')) {
      показатьЭкран('экран-лобби');
    } else {
      открытьЭкранДруга();
    }
  }

  /* ---------- Вошли с другого устройства ----------
     Тот же аккаунт Telegram сел за этот стол с другого телефона или
     компьютера — сервер отдал место ему, а наш пропуск погасил
     (server/комнаты.js, «одно место на аккаунт»). Здесь говорим это
     прямо и даём вернуть партию сюда: повторный вход по коду стола
     снова отдаёт место этому устройству. */
  let кодДругогоУстройства = '';

  function вошлиСДругогоУстройства() {
    кодДругогоУстройства = код || '';
    комнатаПропала('', function () {
      const поле = узел('поле-кода');
      if (поле) поле.value = кодДругогоУстройства;
      показатьЭкран('экран-входа');
      сказать('сообщение-входа',
        'Вы вошли с другого устройства — партия продолжается там. ' +
        'Можно забрать её сюда.');
      показатьВыходИзОтказа('устройство');
    });
  }

  /** «Играть здесь» — войти по коду того же стола ещё раз. */
  function игратьЗдесь() {
    const поле = узел('поле-кода');
    if (поле && кодДругогоУстройства) поле.value = кодДругогоУстройства;
    спрятатьВыходИзОтказа();
    войтиПоКоду();
  }

  /* То же и на входе по коду: сначала адрес, потом стук в сервер. */
  function войтиПоКоду() {
    приВыбранномАдресе('кнопка-войти', войтиПоКодуНаСервере);
  }

  function войтиПоКодуНаСервере() {
    /* Снимаем пометку «нас привела ссылка» первой строкой, при любом исходе:
       иначе она дожила бы до следующего входа руками и посчиталась там. */
    const поПриглашению = входПоПриглашению;
    входПоПриглашению = false;
    // Ссылка, по которой входим, — отметим её, когда сервер ответит.
    const ссылкаВхода = поПриглашению ? ссылкаЖдётОтвета : '';
    ссылкаЖдётОтвета = '';
    // Номер приглашения из хвоста ссылки — тоже только на этот вход.
    const номерИзСсылки = поПриглашению ? номерПриглашенияВхода : '';
    номерПриглашенияВхода = '';
    if (входимВИгру) return;          // ответ на первое нажатие ещё в пути

    const беда = бедаАдреса(адресСервера());
    if (беда) {
      ответитьНаКнопке('кнопка-войти', 'Сейчас не получится');
      показатьБеду(беда, 'экран-входа');
      return;
    }
    const поле = узел('поле-кода');
    const набранный = очиститьКод(поле ? поле.value : '');
    if (набранный.length < 4) {
      ответитьНаКнопке('кнопка-войти', 'Кода не хватает');
      сказать('сообщение-входа', 'Код состоит из четырёх знаков — наберите его целиком.');
      return;
    }

    входимВИгру = true;
    занятьКнопку('кнопка-войти', 'Входим в игру…');
    сказать('сообщение-входа', '');
    спрятатьВыходИзОтказа();
    скрытьБеду();

    const моё = новоеПоколение();
    // Имя нужно, чтобы за столом было видно, кто пришёл. Не назвались —
    // сервер сам даст имя по номеру места.
    const телоВхода = { код: набранный };
    const имя = имяИгрока();
    if (имя) телоВхода.имя = имя;
    // Подпись — чтобы сервер узнал вошедшего и записал знакомство
    // (см. подписьTelegram выше).
    const подпись = подписьTelegram();
    if (подпись) телоВхода.initData = подпись;
    /* Метка вкладки. Нужна на случай повторного входа: оборвалась связь,
       человек нажал «Войти» ещё раз — и раньше за столом появлялся его
       двойник, занимая лишнее место. С меткой сервер узнаёт ту же вкладку
       и возвращает ей прежний пропуск вместо нового места.

       Берём то самое имя вкладки, по которому игра и так узнаёт себя после
       перезагрузки (узнатьИмяВкладки): внутри одной вкладки оно постоянно,
       у соседней — другое. Своего второго имени тут заводить нельзя: два
       имени однажды разойдутся, и защита замолчит. */
    телоВхода.метка = имяВкладки;
    /* Пришли по ссылке-приглашению — говорим об этом серверу. Это только
       для счёта «сколько людей село за стол по приглашению»: бот такого
       человека не видит вовсе (ссылка ведёт прямо в игру, минуя его),
       а сервер видит. Никакой двери это слово не открывает. */
    if (поПриглашению) телоВхода.поПриглашению = true;
    /* Номер приглашения — по нему сервер сам отметит «вход» в учёте
       (server/приглашения.js). Верит он номеру, только если тот привязан
       к этому столу, поэтому подделка номера ничего не даёт. */
    if (номерИзСсылки) телоВхода.приглашение = номерИзСсылки;

    запрос('/войти', телоВхода).then(function (ответ) {
      входимВИгру = false;
      освободитьКнопку('кнопка-войти');
      if (ответУстарел(моё)) return;
      if (ответ.связьСорвалась) {
        /* Обрыв связи ссылку не отмечаем: перезагрузка в той же сессии
           должна попробовать войти ещё раз. */
        рассказатьПочемуМолчит('экран-входа', моё);
        return;
      }
      /* Сервер ответил — посадил или отказал (закрыта, заполнена, идёт):
         по этой ссылке в этой сессии больше не стучимся. Сбой самого
         сервера (5xx) не отмечаем — это не ответ про стол. */
      if (ссылкаВхода && ((ответ.ок && ответ.данные.пропуск) || ответ.номер < 500)) {
        отметитьВходПоСсылке(ссылкаВхода);
      }
      if (!ответ.ок || !ответ.данные.пропуск) {
        const словаОтказа = словаОтказаВхода(ответ.данные.почему);
        if (словаОтказа) {
          сказать('сообщение-входа', словаОтказа);
          показатьВыходИзОтказа('отказ');
          return;
        }
        сказать('сообщение-входа', ответ.данные.ошибка ||
          'Войти не получилось. Проверьте код — возможно, игру уже начали без вас.');
        return;
      }
      сказать('сообщение-входа', '');
      начатьЖизньВКомнате(ответ.данные.код || набранный, ответ.данные.пропуск,
                          ответ.данные.состояние);
    });
  }

  /** Мы в комнате: запоминаем ключи, показываем первое состояние и слушаем новости. */
  function начатьЖизньВКомнате(новыйКод, новыйПропуск, состояние) {
    остановитьОпрос();          // старый опрос мог ещё висеть на прошлой комнате
    новоеПоколение();           // всё, что летело раньше, теперь устарело
    код = новыйКод;
    пропуск = новыйПропуск;
    версия = 0;
    попытокПодряд = 0;
    связьЕсть = true;
    последнееСостояние = null;
    соперникПропалС = 0;
    когдаБылоСобытие = Date.now();
    когдаОтвечалСервер = Date.now();
    приветствиеДо = 0;
    запомнитьКомнату(код, пропуск);
    запуститьЧасовогоВладения();
    if (состояние) принятьСостояние(состояние);
    else показатьЭкран('экран-комнаты');
    запуститьОпрос();
  }

  /* Пока эта вкладка за столом, она регулярно отмечается в памяти
     браузера. По этой отметке вторая вкладка понимает, что место занято. */
  function запуститьЧасовогоВладения() {
    if (часовойВладения !== null) return;
    часовойВладения = setInterval(отметитьВладение, ОТМЕТКА_КАЖДЫЕ);
  }

  function остановитьЧасовогоВладения() {
    if (часовойВладения === null) return;
    clearInterval(часовойВладения);
    часовойВладения = null;
  }

  /**
   * Кончилась ли игра в этой комнате совсем. Партия доиграна — этого мало:
   * пока друг за столом, он может позвать на реванш, и вернуться туда стоит.
   * А вот доигранная партия, из которой друг уже ушёл (или пропал со связи), —
   * мёртвая комната: в ней нечего делать ни нам, ни ему.
   */
  function играВКомнатеКончилась(вид) {
    if (!вид) return false;
    if (!вид.завершена && вид.этап !== 'конец') return false;
    return Boolean(вид.соперникУшёл) || !вид.соперникНаСвязи;
  }

  /**
   * Вернуться в партию, начатую до перезагрузки страницы. Спрашиваем сервер,
   * жива ли комната: если нет — молча забываем ключи, чтобы не предлагать
   * человеку вернуться в никуда.
   *
   * тихо=true — ничего не показываем и не садим за стол, только узнаём,
   * жива ли комната: так плашка «Вернуться к игре» в лобби спрашивает
   * сервер заранее, не трогая то, что человек сейчас видит на экране.
   * наИтог(жива) зовётся ровно один раз — с true (можно возвращаться),
   * false (партии больше нет — ключи уже забыты) или null (сервер не
   * ответил, либо пока ждали ответ, начался новый заход и этот ответ
   * устарел; в обоих случаях ничего не решаем и ключи не трогаем).
   */
  function попробоватьВернуться(сСообщением, тихо, наИтог) {
    const сказатьЛи = Boolean(сСообщением) && !тихо;
    const сохранённое = вспомнитьКомнату();
    if (!сохранённое) { if (наИтог) наИтог(false); return; }
    if (бедаАдреса(адресСервера())) { if (наИтог) наИтог(null); return; }

    // Плашка возврата проверяется и во время активной партии. Эта комната
    // уже опрашивается: тихая проверка не должна начинать новое поколение
    // и тем самым останавливать ответ текущего длинного опроса.
    if (тихо && опросИдёт && код === сохранённое.код && пропуск === сохранённое.пропуск) {
      if (наИтог) наИтог(true);
      return;
    }

    // За этим столом уже сидит другая вкладка. Сесть туда же нельзя:
    // выход из второй вкладки выбросил бы из партии и первую.
    if (комнатуДержитДругаяВкладка()) {
      if (сказатьЛи) {
        сказать('сообщение-друга', 'Эта игра уже открыта в другой вкладке — играйте там. ' +
          'Здесь можно создать новую игру или войти к другому другу.');
      }
      // Это не «партия пропала» — комната жива, просто занята соседней
      // вкладкой. Решать за плашку тут нечего, ключи не трогаем.
      if (наИтог) наИтог(null);
      return;
    }

    if (сказатьЛи) сказать('сообщение-друга', 'Возвращаемся в вашу игру…');

    /* Ключи от комнаты нарочно не кладём в «код» и «пропуск», пока сервер
       не подтвердил, что партия жива, — спрашиваем о ней напрямую. Раньше
       мы занимали место сразу, и выход, нажатый в эти секунды ожидания,
       уходил на сервер по-настоящему: человек всего лишь передумал
       возвращаться, а партия рвалась у обоих. */
    /* Тихая проверка (раз в СРОК_СВЕЖЕСТИ_ЖИВОСТИ, 20 с) только читает
       ответ сервера и за стол не садится — новое поколение ей заводить
       нельзя. Раньше она звала новоеПоколение(), и висящий длинный опрос
       текущей партии считал свой ответ устаревшим и выбрасывал его: ходы
       соперника переставали приходить, партия «замерзала». Поэтому тихо
       берём текущее поколение: если за это время начнётся настоящий новый
       заход, ответ тихой проверки всё равно честно окажется устаревшим. */
    const моё = тихо ? поколение : новоеПоколение();

    /* Но сперва тихо стучимся в дверь сервера — и вот зачем.

       Спросить про исчезнувшую комнату можно только одним способом: послать
       запрос и получить отказ 404 («комнаты нет или пропуск чужой»). Для игры
       это обычный ответ, человеку по нему говорят правду, — а браузер всё
       равно пишет в консоль красную строку про неудачный запрос, и погасить
       её из кода нельзя никак. По правилам проекта в консоли должны быть
       видны только настоящие поломки, поэтому лишний отказ надо не глушить,
       а не создавать.

       Стук идёт в «/здоровье» — эта дверь отвечает согласием всегда, красной
       строки от неё не бывает. Сервер попутно говорит, сколько комнат он
       помнит, и ноль решает дело: комнат нет вовсе, значит нет и нашей,
       спрашивать не о чем. Так уходит самый частый случай — сервер
       перезапустили или все комнаты успели протухнуть.

       Что при этом НЕ проглатывается. Если дверь молчит или отвечает отказом
       (это и есть настоящая сетевая беда), мы ничего не решаем сами и идём
       прежним путём: запрос уйдёт, и человек получит честный рассказ про
       молчащий сервер. Тихо пропускаем ровно один случай — когда сервер
       живой и сам сказал, что комнат у него нет. */
    стукВДверь(адресСервера(), СПОР_АДРЕСОВ_ЖДЁТ).then(function (стук) {
      // Пока ответ шёл, начался другой заход (новое поколение) — этот
      // колбэк всё равно обязан позвать наИтог, иначе тихая проверка
      // навсегда останется «идёт» и плашка возврата пропадёт из вкладки.
      if (ответУстарел(моё)) { if (наИтог) наИтог(null); return; }
      if (стук.итог === 'сервер-игры' && стук.комнат === 0) {
        забытьКомнату();
        if (сказатьЛи) сказать('сообщение-друга', СЛОВА_КОМНАТЫ_НЕТ);
        if (наИтог) наИтог(false);
        return;
      }
      спроситьПроКомнату(сохранённое, моё, сказатьЛи, тихо, наИтог);
    });
  }

  /**
   * Спросить сервер про сохранённую комнату и разобрать ответ.
   * Вынесено из «попробоватьВернуться» отдельной дверью: перед этим
   * запросом появился тихий стук в «/здоровье», и держать оба шага
   * в одной лестнице вложенных ответов стало нечитаемо.
   *
   * тихо=true — только разобрать ответ и позвать наИтог(жива), не садясь
   * за стол: комната для этого вызова остаётся чужой, пока за неё явно
   * не взялись кнопкой «Вернуться».
   */
  function спроситьПроКомнату(сохранённое, моё, сказатьЛи, тихо, наИтог) {
    запрос('/состояние', { код: сохранённое.код, пропуск: сохранённое.пропуск })
        .then(function (ответ) {
      // Пока ответ шёл, человек мог войти в другую игру. Такой ответ
      // применять нельзя: он выкинет его обратно в старую комнату,
      // а друг останется за столом один и навсегда. Но наИтог всё равно
      // обязан прозвучать — иначе висящая кнопка или тихая проверка
      // так и останутся «в процессе» до перезагрузки страницы.
      if (ответУстарел(моё)) { if (наИтог) наИтог(null); return; }
      if (ответ.связьСорвалась) {
        if (сказатьЛи) рассказатьПочемуМолчит('экран-друга', моё);
        if (наИтог) наИтог(null);
        return;
      }
      if (!ответ.ок || !ответ.данные.состояние) {
        // Вернуться не вышло — ключи бесполезны. За столом мы так и не сели,
        // поэтому чистить нечего, кроме памяти браузера.
        забытьКомнату();
        /* Отказ тот же самый, а причины две. Комната жива — значит, нас
           не дождались и начали новую партию; тогда оставляем человеку код,
           чтобы он мог войти заново, не выспрашивая его у друга. */
        if (насНеДождались(ответ)) {
          кодДляПовторногоВхода = сохранённое.код || '';
          if (сказатьЛи) {
            сказать('сообщение-друга', словаПроНовуюПартию(сохранённое.код));
          }
          if (наИтог) наИтог(false);
          return;
        }
        if (сказатьЛи) сказать('сообщение-друга', СЛОВА_КОМНАТЫ_НЕТ);
        if (наИтог) наИтог(false);
        return;
      }
      /* Комната жива, но играть в ней уже нечего. Возвращаться туда нельзя:
         человек увидел бы экран доигранной партии с единственной кнопкой
         «В меню» и решил бы, что игра застряла. Вместо этого выбрасываем
         ключи и оставляем его там, откуда начинают новую игру. */
      if (играВКомнатеКончилась(ответ.данные.состояние)) {
        забытьКомнату();
        if (сказатьЛи) {
          сказать('сообщение-друга', 'Прошлая игра с другом уже доиграна, и за столом ' +
            'никого не осталось. Создайте новую игру или войдите по коду.');
        }
        if (наИтог) наИтог(false);
        return;
      }
      if (тихо) { if (наИтог) наИтог(true); return; }
      if (сказатьЛи) сказать('сообщение-друга', '');
      начатьЖизньВКомнате(сохранённое.код, сохранённое.пропуск, ответ.данные.состояние);
      if (наИтог) наИтог(true);
    });
  }

  /* -------------------------------------------------------------------
     Уход из партии
     ------------------------------------------------------------------- */

  /**
   * Выйти из партии: сказать серверу (чтобы друг сразу увидел уход),
   * погасить опрос и забыть ключи. Вызывать можно всегда — если сетевой
   * партии нет, ничего не произойдёт.
   */
  function покинутьПартию() {
    остановитьОпрос();
    остановитьЧасовогоСвязи();
    остановитьЧасовогоВладения();
    новоеПоколение();       // всё, что ещё летит, к этой партии уже не относится
    показатьСвязь('');
    вПартии = false;
    последнееСостояние = null;
    соперникПропалС = 0;
    приветствиеДо = 0;
    спрятатьНовуюКомнату();   // мы вышли из комнаты 05 — прячем её, если была видна
    /* Кнопка пересбора живёт на общем экране итога — том же, что и в игре
       с ботом. Уходя из комнаты, прячем её сами: состояний от сервера
       больше не придёт, и спрятать её будет уже некому. */
    обновитьКнопкуПересбора(null);
    if (!код || !пропуск) return;
    const уходящийКод = код;
    const уходящийПропуск = пропуск;
    код = null;
    пропуск = null;
    забытьКомнату();
    // Ответ нам уже не нужен: мы уходим в любом случае.
    запрос('/выйти', { код: уходящийКод, пропуск: уходящийПропуск });
  }

  /* -------------------------------------------------------------------
     Кнопки
     ------------------------------------------------------------------- */

  /* Сколько держим ответ сервера про живость сохранённой комнаты свежим.
     Раньше эту проверку не делали вовсе (см. память ниже), и кнопка звала
     в комнату, которую сервер уже забыл, — человек упирался в тупик.
     Спрашивать при каждом вызове обновитьКнопкуВозврата (а её зовут и при
     возврате в меню, и при входе/выходе из комнаты) — плодить лишние
     запросы; комната за несколько секунд не воскресает и не умирает,
     поэтому одного ответа хватает на СРОК_СВЕЖЕСТИ_ЖИВОСТИ. */
  const СРОК_СВЕЖЕСТИ_ЖИВОСТИ = 20 * 1000;
  /* живостьКомнаты.жива === null — ещё не спрашивали ни разу или ответ
     не пришёл (сеть молчала) — плашку в этом случае не показываем: врать
     «партия ждёт» опаснее, чем на секунду промолчать про неё. */
  let живостьКомнаты = { код: null, время: 0, жива: null };
  let проверкаЖивостиИдёт = false;

  /** Пора ли спросить сервер заново: комната сменилась или ответ протух. */
  function живостьНадоСпросить(сохранённое) {
    if (живостьКомнаты.код !== сохранённое.код) return true;
    return Date.now() - живостьКомнаты.время > СРОК_СВЕЖЕСТИ_ЖИВОСТИ;
  }

  /**
   * Показать в меню кнопку возврата, только если сервер подтвердил: партия
   * жива и нас там ждут. Сама проверка тихая (см. попробоватьВернуться) и
   * не чаще раза на СРОК_СВЕЖЕСТИ_ЖИВОСТИ — не поток запросов, а редкая
   * сверка. Пока ответа нет, кнопку не показываем: как только он придёт,
   * функция перерисует кнопку сама.
   */
  function обновитьКнопкуВозврата() {
    const сохранённое = вспомнитьКомнату();
    const своя = Boolean(сохранённое) && !комнатуДержитДругаяВкладка();

    if (!своя) {
      // Нет своей брошенной комнаты — прошлая проверка её и не касалась.
      живостьКомнаты = { код: null, время: 0, жива: null };
    } else if (живостьНадоСпросить(сохранённое) && !проверкаЖивостиИдёт) {
      проверкаЖивостиИдёт = true;
      попробоватьВернуться(false, true, function (жива) {
        проверкаЖивостиИдёт = false;
        живостьКомнаты = { код: сохранённое.код, время: Date.now(), жива: жива === true };
        обновитьКнопкуВозврата();   // ответ пришёл — перерисовать кнопку заново
      });
    }

    const естьЧтоПродолжить = своя && живостьКомнаты.жива === true &&
                               живостьКомнаты.код === сохранённое.код;

    /* Подпись входа на первом экране. Там теперь всего две кнопки — «с ботом»
       и «с другом», — и отдельной кнопке возврата места нет. Поэтому про
       недоигранную партию говорит сама кнопка входа: пока партия жива, она
       читается «Вернуться к игре с другом», а как только партия доиграна или
       брошена, слова возвращаются обычные. Обе стороны этой развилки нужны:
       без второй кнопка навсегда звала бы в игру, которой уже нет. */
    const вход = узел('кнопка-с-другом');
    if (вход) {
      /* Меняем ТОЛЬКО начало фразы. Последнее слово («другом») лежит в своём
         узле и подсвечено оформлением; перепиши мы кнопку целиком, выделение
         исчезло бы при первой же перерисовке и больше не вернулось.
         Запасная ветка — на случай старой разметки без этих узлов. */
      const начало = вход.querySelector ? вход.querySelector('.кнопка__начало') : null;
      if (начало) начало.textContent = естьЧтоПродолжить ? 'Вернуться к игре с' : 'Играть с';
      else вход.textContent = естьЧтоПродолжить ? 'Вернуться к игре с другом' : 'Играть с другом';
    }

    const кнопка = узел('кнопка-вернуться-в-игру');
    if (!кнопка) return;
    кнопка.classList.toggle('скрыт', !естьЧтоПродолжить);
  }

  /**
   * Нажатие на плашку «Вернуться к игре с другом». Эта кнопка уже обещала
   * живую партию (см. обновитьКнопкуВозврата) — значит, ведём прямо за
   * стол, без экрана-посредника «Игра с другом»: там всё равно нечего было
   * бы делать, окажись обещание неверным. Порядок ответа с сервера мог
   * измениться за секунды между показом плашки и нажатием — поэтому здесь
   * всё равно честно спрашиваем заново, а не верим прошлому ответу.
   */
  function нажатиеВозврата() {
    // Место занято другой вкладкой — это не тупик, а развилка с настоящими
    // действиями («Создать игру», «Войти по коду»): они живут на экране
    // «Игра с другом», туда и ведём, как раньше.
    if (комнатуДержитДругаяВкладка()) { открытьЭкранДруга(); return; }
    занятьКнопку('кнопка-вернуться-в-игру', 'Возвращаемся за стол…');
    попробоватьВернуться(false, false, function (жива) {
      if (жива === false) {
        // попробоватьВернуться уже забыла ключи — кнопка сама скоро спрячется.
        освободитьКнопку('кнопка-вернуться-в-игру', 'Партии больше нет');
        return;
      }
      if (жива === null) {
        // Сеть не ответила — ключи не тронуты, можно попробовать ещё раз.
        освободитьКнопку('кнопка-вернуться-в-игру', 'Сеть не отвечает');
        return;
      }
      освободитьКнопку('кнопка-вернуться-в-игру');   // вышло — экран уже сменился на стол
    });
  }

  function открытьЭкранДруга() {
    /* Признак «компанией» мог остаться от прошлого захода через шаги
       режима «друзья» (js/дурак-путь.js) — здесь человек снова на
       старом экране и ничего не выбирал заново, поэтому обычная кнопка
       «Создать игру» опять должна давать обычную игру вдвоём. */
    выборСтола.компанией = false;
    // Тот же сброс, что у «компанией» строкой выше: открытый стол с
    // прошлого захода через шаги дурака не должен утечь на обычную
    // «Игру с другом» — там всегда должна получаться приватная игра по коду.
    выборСтола.открытый = false;
    сказать('сообщение-друга', '');
    // Беда с прошлого захода уже неправдива: сервер мог за это время
    // подняться, и встречать человека старым отказом нечестно.
    скрытьБеду();
    показатьЭкран('экран-друга');
    обновитьВходВНастройку();
    /* Адрес проверяем и здесь, но объяснение заранее НЕ показываем. Раньше
       оно встречало человека прямо на входе, и тогда нажатие «Создать игру»
       ничего на экране не меняло: тот же текст перерисовывался сам в себя.
       Кнопка выглядела сломанной. Теперь беда всплывает по нажатию — вместе
       с ответом на самой кнопке. Здесь же остаётся только одно: не пытаться
       вернуться в прошлую партию, если сервер всё равно недостижим.

       Спор двух адресов запускаем прямо тут, в фоне и без всяких надписей:
       человек как раз читает экран и решает, создавать игру или входить по
       коду, — к его нажатию ответ обычно уже готов, и ждать не придётся. */
    приВыбранномАдресе(null, function () {
      if (бедаАдреса(адресСервера())) return;
      // Есть недоигранная партия — попробуем вернуться в неё сами.
      if (вспомнитьКомнату()) попробоватьВернуться(true);
    });
  }

  /* -------------------------------------------------------------------
     Копирование кода
     ------------------------------------------------------------------- */

  /**
   * Старый способ копирования — через невидимое поле. Нужен там, где нового
   * буфера обмена нет: он работает только на защищённых страницах, а внутри
   * Telegram встроенный браузер иногда не даёт и его.
   */
  function скопироватьЧерезПоле(текст) {
    try {
      const поле = document.createElement('textarea');
      поле.value = текст;
      поле.setAttribute('readonly', '');
      поле.style.position = 'fixed';
      поле.style.top = '-1000px';
      document.body.appendChild(поле);
      поле.select();
      // Без этой строки на iPhone выделение не срабатывает.
      if (поле.setSelectionRange) поле.setSelectionRange(0, текст.length);
      const вышло = document.execCommand && document.execCommand('copy');
      document.body.removeChild(поле);
      return Boolean(вышло);
    } catch (сбой) {
      return false;
    }
  }

  /** Положить текст в буфер обмена. Сначала новым способом, потом старым. */
  function положитьВБуфер(текст) {
    const буфер = window.navigator && window.navigator.clipboard;
    if (буфер && typeof буфер.writeText === 'function') {
      try {
        return буфер.writeText(текст).then(
          function () { return true; },
          function () { return скопироватьЧерезПоле(текст); }
        );
      } catch (сбой) {
        return Promise.resolve(скопироватьЧерезПоле(текст));
      }
    }
    return Promise.resolve(скопироватьЧерезПоле(текст));
  }

  function скопироватьКод() {
    if (!код) {
      сказать('сообщение-копирования', 'Код ещё не пришёл — подождите секунду.');
      return;
    }
    положитьВБуфер(код).then(function (вышло) {
      if (вышло) {
        ответитьНаКнопке('кнопка-копировать-код', 'Код скопирован');
        сказать('сообщение-копирования', 'Код в буфере — вставьте его другу в переписку.');
        return;
      }
      // Молчать нельзя: человек решит, что скопировалось, и отправит пустоту.
      ответитьНаКнопке('кнопка-копировать-код', 'Скопировать не вышло');
      сказать('сообщение-копирования',
        'Скопировать не получилось — телефон не дал доступ к буферу обмена. ' +
        'Продиктуйте другу код: ' + код);
    });
  }

  /* -------------------------------------------------------------------
     «Сыграть с другом»: приглашение вместо продиктованного кода

     Внутри Telegram кнопка открывает список чатов — человек выбирает
     друга, и тому уходит ссылка на этот самый стол. В обычном браузере
     списка чатов нет, поэтому там кнопка кладёт ссылку в буфер обмена:
     отправить её можно чем угодно, и путь всё равно короче диктовки.
     ------------------------------------------------------------------- */

  /* «Играем во что» для каждой игры по сети. Раньше текст был один —
     про дурака, и друг, позванный в нарды, читал «подкидного дурака».
     Слова те же, что «вИгру» в server/названия.js: сервер пишет их
     в подготовленное сообщение, мы — в запасной путь, и расходиться им
     нельзя (tests/маршрут-приглашения-8-игр.js сверяет обе таблицы). */
  const ВО_ЧТО_ИГРАЕМ = {
    'дурак': 'в подкидного дурака', 'шашки': 'в шашки', 'нарды': 'в нарды',
    'деберц': 'в деберц', 'морской-бой': 'в морской бой', 'домино': 'в домино',
    'катан': 'в Катан', 'монополия': 'в монополию'
  };
  const ТЕКСТ_ПРИГЛАШЕНИЯ = 'Играем ' + (ВО_ЧТО_ИГРАЕМ[ИГРА_ЭТОЙ_СТРАНИЦЫ] || ВО_ЧТО_ИГРАЕМ['дурак']) +
    '? Стол уже собран — заходите по ссылке.';

  /**
   * Открыть выбор чата средствами Telegram. Отвечает, получилось ли:
   * метода может не быть вовсе (старое приложение), и тогда зовём друга
   * по-другому, а не молчим.
   */
  function открытьВыборЧата(ссылка, слова) {
    try {
      const приложение = window.Telegram && window.Telegram.WebApp;
      if (!приложение || typeof приложение.openTelegramLink !== 'function') return false;
      // Второй довод необязателен: без него — прежние слова зова за стол.
      const текст = typeof слова === 'string' && слова ? слова : ТЕКСТ_ПРИГЛАШЕНИЯ;
      приложение.openTelegramLink('https://t.me/share/url?url=' + encodeURIComponent(ссылка) +
                                  '&text=' + encodeURIComponent(текст));
      return true;
    } catch (сбой) {
      return false;
    }
  }

  /**
   * Предупреждение про домашний адрес. Ссылка на свой компьютер работает
   * только на нём самом (ну и в домашней сети): другу с телефона идти
   * по ней некуда. Сказать это надо сразу — иначе он упрётся в молчащий
   * сервер и будет думать, что сломалась игра.
   */
  function бедаПриглашения(ссылка) {
    if (адресНаСвойКомпьютер(адресСервера()) || адресНаСвойКомпьютер(ссылка)) {
      return ' Но учтите: ссылка ведёт на ваш компьютер, и с чужого телефона ' +
             'она не откроется. Нужен адрес из интернета — запустите туннель.';
    }
    return '';
  }

  /* ---------- Выбор чата поверх игры ----------

     Раньше «Сыграть с другом» открывало список чатов обычной ссылкой, и на
     компьютере это уводило окно игры за окно Telegram: владелец сказал
     точнее всех — «улетает, и я его не могу найти». У Telegram есть
     способ лучше: бот заранее готовит сообщение, а игра показывает выбор
     чата ПОВЕРХ себя и никуда не уходит. Готовит сообщение наш сервер
     (только он знает токен бота), а игра лишь просит его об этом.

     Главное правило здесь — молчаливый откат. Не вышло подготовить,
     сервер не ответил, Telegram старый — человеку об этом знать незачем:
     он просто получит ссылку в буфер обмена обычными словами, как раньше.
     Рассказывать про внутренние неудачи — значит пугать человека тем,
     на что он всё равно не может повлиять. */

  /* Сколько ждём подготовку. Две с половиной секунды — предел терпения
     на нажатие кнопки; дальше уходим запасным путём. */
  const ЖДЁМ_ПОДГОТОВКУ = 2500;

  /** Умеет ли этот Telegram показывать выбор чата поверх игры. */
  function можноВыбратьЧатПоверх() {
    try {
      const приложение = window.Telegram && window.Telegram.WebApp;
      if (!приложение || typeof приложение.shareMessage !== 'function') return false;
      // Подпись нужна серверу: без неё он не поверит, что мы — это мы.
      if (!приложение.initData) return false;
      return typeof приложение.isVersionAtLeast === 'function' &&
             приложение.isVersionAtLeast('8.0');
    } catch (сбой) {
      return false;
    }
  }

  /* ---------- Учёт приглашения ----------

     Сервер выдаёт каждому зову за стол номер (server/приглашения.js) и
     ведёт по нему путь: окно открыто → отправлено или отменено → друг
     вошёл → сыграли. Вход и игру сервер видит сам, а что было в руках
     у зовущего — знает только игра, и она сообщает это дверью
     /приглашение-событие. «Отправлено» — только по подтверждению самого
     Telegram (колбэк shareMessage с true): по нажатию кнопки мы этого
     не знаем, и счёт отправленных стал бы враньём. */

  /** Сообщить серверу, что было с приглашением. Ответ не ждём: учёт игроку не мешает. */
  function отметитьПриглашение(номер, что) {
    if (!номер) return;
    try {
      const подпись = подписьTelegram();
      if (!подпись) return;
      запрос('/приглашение-событие', { initData: подпись, id: номер, что: что });
    } catch (сбой) {
      /* учёт не удался — играть это не мешает */
    }
  }

  /* ---------- Приглашение заранее ----------
     Буфер обмена в Safari (и Telegram на Mac) пускает только «прямо по
     нажатию»: стоит подождать ответа сервера — и копирование откажет.
     Поэтому приглашение просим заранее, как только на экране появился
     код стола, — один раз на код. К нажатию ответ обычно уже лежит,
     и всё делается сразу, без ожидания. Не успел — идём прежним путём,
     дожидаясь того же самого запроса, а не посылая второй. */
  let заготовка = null;   // { код, ссылка, ответ (null — ещё не пришёл), обещание }

  /** Заранее попросить приглашение для стола. Не в Telegram или ссылки нет — null. */
  function заготовитьПриглашение(кодКомнаты) {
    if (заготовка && заготовка.код === кодКомнаты) return заготовка;
    const ссылка = кодКомнаты ? ссылкаПриглашения(кодКомнаты) : '';
    const подпись = подписьTelegram();
    if (!ссылка || !этоСсылкаВTelegram(ссылка) || !подпись) return null;
    const моя = { код: кодКомнаты, ссылка: ссылка, ответ: null, обещание: null };
    моя.обещание = запрос('/приглашение', { initData: подпись, ссылка: ссылка }).then(function (ответ) {
      // Сервер не ответил — забываем, чтобы следующее нажатие спросило заново.
      if (!ответ.ок) {
        if (заготовка === моя) заготовка = null;
      } else {
        моя.ответ = ответ;
      }
      return ответ;
    });
    заготовка = моя;
    return моя;
  }

  /**
   * Что взять из ответа /приглашение: ссылку с номером, номер для учёта
   * и номер подготовленного сообщения ('' — Telegram его не принял).
   * Номер и ссылку сервер отдаёт и тогда, когда Telegram сообщение не принял.
   */
  function прочестьОтветПриглашения(ответ, ссылка) {
    const данные = (ответ && ответ.данные) || {};
    const итог = { ссылка: ссылка, номер: '', номерСообщения: '' };
    if (typeof данные.ссылка === 'string' && этоСсылкаВTelegram(данные.ссылка)) итог.ссылка = данные.ссылка;
    if (typeof данные.приглашение === 'string') итог.номер = данные.приглашение;
    if (ответ && ответ.ок && данные.ок === true && typeof данные.номерСообщения === 'string') {
      итог.номерСообщения = данные.номерСообщения;
    }
    return итог;
  }

  /** Ответ сервера уже есть — выбор чата или буфер прямо в нажатии. */
  function позватьПоГотовому(ответ, ссылка, поверх, поСтаринке) {
    const готово = прочестьОтветПриглашения(ответ, ссылка);
    // Выбора чата поверх игры нет (старый Telegram) — нужна была только ссылка с номером.
    if (!поверх || !готово.номерСообщения) {
      поСтаринке(готово.ссылка, готово.номер);
      return;
    }
    показатьВыборЧата(готово.номерСообщения, готово.номер, function () {
      поСтаринке(готово.ссылка, готово.номер);
    });
  }

  /**
   * Ответа ещё нет — ждём его и показываем выбор чата.
   * Что бы ни пошло не так — зовём «поСтаринке» и ни слова про неудачу.
   * «поСтаринке» получает ссылку и номер приглашения из ответа сервера:
   * в ссылке сервера уже зашит номер, и запасной путь обязан нести его же.
   * «ожидание» — уже летящий заранее запрос (нет — спрашиваем сами).
   */
  function позватьЧерезTelegram(ссылка, поверх, поСтаринке, ожидание) {
    занятьКнопку('кнопка-позвать-друга', 'Готовим…');
    let ужеУшли = false;
    const запасной = function () {
      if (ужеУшли) return;
      ужеУшли = true;
      освободитьКнопку('кнопка-позвать-друга');
      поСтаринке(ссылка, '');
    };
    // Сервер может и не ответить вовсе — ждать дольше нельзя.
    setTimeout(запасной, ЖДЁМ_ПОДГОТОВКУ);

    const ответПридёт = ожидание ||
      запрос('/приглашение', { initData: подписьTelegram(), ссылка: ссылка }, ЖДЁМ_ПОДГОТОВКУ);
    ответПридёт.then(function (ответ) {
      if (ужеУшли) return;
      ужеУшли = true;
      освободитьКнопку('кнопка-позвать-друга');
      позватьПоГотовому(ответ, ссылка, поверх, поСтаринке);
    });
  }

  /** Показать выбор чата поверх игры. Не вышло — тихо уходим запасным путём. */
  function показатьВыборЧата(номерСообщения, номерПриглашения, поСтаринке) {
    /* «Окно открыто» — до вызова: Telegram может позвать колбэк сразу,
       и в учёте «отправлено» встало бы раньше открытия окна. */
    отметитьПриглашение(номерПриглашения, 'окноОткрыто');
    try {
      window.Telegram.WebApp.shareMessage(номерСообщения, function (отправлено) {
        if (!отправлено) {
          // Человек закрыл выбор — ему молчим, а в учёт пишем.
          отметитьПриглашение(номерПриглашения, 'отменено');
          return;
        }
        отметитьПриглашение(номерПриглашения, 'отправлено');
        ответитьНаКнопке('кнопка-позвать-друга', 'Приглашение отправлено');
        сказать('сообщение-приглашения',
          'Друг получил ссылку — он нажмёт её и сразу сядет за ваш стол.');
      });
    } catch (сбой) {
      поСтаринке();
    }
  }

  function позватьДруга() {
    if (!код) {
      сказать('сообщение-приглашения', 'Код ещё не пришёл — подождите секунду.');
      return;
    }
    const ссылка = ссылкаПриглашения(код);
    if (!ссылка) {
      ответитьНаКнопке('кнопка-позвать-друга', 'Ссылку не собрать');
      сказать('сообщение-приглашения',
        'Игра открыта файлом с диска, и ссылки на неё не существует. ' +
        'Продиктуйте другу код: ' + код);
      return;
    }

    /* Лучший путь — выбор чата поверх игры. Он работает только для
       телеграмной ссылки: обычную ссылку на страницу бот не рассылает.
       В Telegram с подписью сервер нужен и без выбора поверх: ссылку
       с номером приглашения выдаёт только он. */
    if (этоСсылкаВTelegram(ссылка) && подписьTelegram()) {
      const готово = заготовитьПриглашение(код);
      if (готово && готово.ответ) {
        позватьПоГотовому(готово.ответ, ссылка, можноВыбратьЧатПоверх(), позватьПоСтаринке);
        return;
      }
      позватьЧерезTelegram(ссылка, можноВыбратьЧатПоверх(), позватьПоСтаринке,
        готово ? готово.обещание : null);
      return;
    }
    позватьПоСтаринке(ссылка, '');
  }

  /**
   * Прежний путь: на телефоне — список чатов ссылкой, иначе буфер обмена.
   * номерПриглашения — из ответа сервера ('' — учёта нет): по нему пишем,
   * открылось ли окно выбора чата или ссылка легла в буфер.
   */
  function позватьПоСтаринке(ссылка, номерПриглашения) {

    /* Список чатов открываем только с телефона. На компьютере он уводит
       игру с экрана, и вернуться человек не может — там нет ни жеста
       «назад», ни заметной кнопки. */
    if (гдеМыВTelegram() === 'телефон' && открытьВыборЧата(ссылка)) {
      отметитьПриглашение(номерПриглашения, 'окноОткрыто');
      ответитьНаКнопке('кнопка-позвать-друга', 'Выбираем чат…');
      сказать('сообщение-приглашения',
        'Выберите друга в списке — ему уйдёт ссылка на этот стол.' + бедаПриглашения(ссылка));
      return;
    }

    // Остальные случаи — копируем: компьютер, веб-версия и обычный браузер.
    положитьВБуфер(ссылка).then(function (вышло) {
      if (вышло) {
        отметитьПриглашение(номерПриглашения, 'скопировано');
        ответитьНаКнопке('кнопка-позвать-друга', 'Ссылка скопирована');
        /* Говорим ровно то, что человека ждёт: телеграмная ссылка откроет
           игру в мессенджере, браузерная — в браузере. Обещать не то место
           нельзя — друг решит, что ссылка сломана. */
        сказать('сообщение-приглашения',
          'Ссылка в буфере — отправьте её другу любым способом. ' +
          (этоСсылкаВTelegram(ссылка)
            ? 'Он нажмёт её и откроет игру прямо в Telegram, сразу за вашим столом.'
            : 'Он откроет её в браузере и сразу сядет за ваш стол.') +
          бедаПриглашения(ссылка));
        return;
      }
      // Буфер не дался — показываем ссылку целиком и готовой к копированию.
      ответитьНаКнопке('кнопка-позвать-друга', 'Скопировать не вышло');
      показатьСсылкуЦеликом(ссылка);
    });
  }

  /**
   * Последняя опора: показать ссылку прямо на экране и выделить её.
   *
   * Нужна там, где буфер обмена закрыт, — а это как раз встроенный
   * Telegram на компьютере. Двух вещей тут мало по отдельности: по всей
   * игре выделение текста выключено (иначе карты подсвечиваются при
   * долгом нажатии), поэтому сначала разрешаем выделять эту строку,
   * а потом выделяем её сами — человеку остаётся нажать Ctrl+C.
   */
  function показатьСсылкуЦеликом(ссылка) {
    сказать('сообщение-приглашения',
      'Скопировать не получилось — Telegram не дал доступ к буферу обмена. ' +
      'Вот ссылка, она уже выделена — скопируйте её (Ctrl+C) и отправьте другу: ' + ссылка);
    const место = узел('сообщение-приглашения');
    if (!место) return;
    try {
      место.style.userSelect = 'text';
      место.style.webkitUserSelect = 'text';
      const кусок = document.createRange();
      кусок.selectNodeContents(место);
      const выделение = window.getSelection();
      выделение.removeAllRanges();
      выделение.addRange(кусок);
    } catch (сбой) {
      /* выделить не вышло — ссылка всё равно на экране, её можно переписать */
    }
  }

  /**
   * Есть ли за столом свободное место — звать друга есть куда. Числа берём
   * прямо из того же ответа сервера, что получает и рисует экран комнаты
   * («застолом», «мест») — второго счёта не заводим, иначе однажды эти
   * два счёта разойдутся.
   * Комната-компания шлёт список «застолом» — по нему и считаем: занято
   * ровно столько мест, сколько в списке, свободно, если это меньше
   * «мест». Комната вдвоём такого списка не шлёт вовсе (её вид без поля
   * «застолом») — там своего счёта мест нет, решаем «место есть» и не
   * мешаем прежнему поведению этой комнаты.
   */
  function естьСвободноеМесто(вид) {
    if (!вид || !Array.isArray(вид.застолом)) return true;
    const всего = Number(вид.мест) || вид.застолом.length;
    return вид.застолом.length < всего;
  }

  /**
   * Показать кнопку приглашения или спрятать. Прячем, когда звать некуда:
   * кода ещё нет, свободных мест за столом не осталось (звать некого
   * посадить) или ссылку не из чего собрать (игру открыли файлом с диска).
   * Кнопка, которая всегда отвечает отказом, хуже её отсутствия.
   *
   * Это единственное место в игре, которое решает, видна ли кнопка
   * «Сыграть с другом» и доступна ли она: js/дурак-комната.js её не
   * трогает совсем, даже при своей перерисовке (см. её «нарисоватьКод»),
   * иначе повторный показ() перебивал бы disabled, пока занятьКнопку()
   * держит подпись «Готовим ссылку…».
   */
  function обновитьКнопкуПриглашения(кодКомнаты, вид) {
    const можно = Boolean(кодКомнаты) && естьСвободноеМесто(вид) &&
      Boolean(ссылкаПриглашения(кодКомнаты));
    показать('кнопка-позвать-друга', можно);
    if (!можно) {
      сказать('сообщение-приглашения', '');
      return;
    }
    // Кнопка видна — приглашение просим сейчас, чтобы нажатие не ждало сервер.
    заготовитьПриглашение(кодКомнаты);
    предупредитьПроСворачивание();
  }

  /**
   * На телефоне выбор чата сворачивает игру, и сказать об этом надо
   * ЗАРАНЕЕ: человек, у которого окно исчезло без предупреждения, решает,
   * что игра закрылась совсем, и начинает всё заново, бросив стол.
   *
   * Пишем только в пустую строку — иначе эта подсказка затирала бы ответ
   * на нажатие: список мест приходит с сервера каждые несколько секунд,
   * и кнопка обновляется вместе с ним.
   */
  function предупредитьПроСворачивание() {
    if (гдеМыВTelegram() !== 'телефон') return;
    const место = узел('сообщение-приглашения');
    if (!место || место.textContent) return;
    сказать('сообщение-приглашения',
      'Пока вы выбираете чат, игра свернётся — это нормально. ' +
      'Вернуться за стол можно кнопкой «Вернуться к игре с другом» в главном меню.');
  }

  /**
   * «Назад» на экране «Вход по коду». Куда — решает игра, если умеет
   * (у дурака вход открывается из лобби строкой «Есть код? Войти», и
   * назад логично туда же). Не умеет — как всегда, на экран друга: так
   * у шашек ничего не меняется.
   */
  function назадСоВхода() {
    спрятатьВыходИзОтказа();
    const мост = игра();
    if (мост && typeof мост.назадСоВхода === 'function') {
      скрытьБеду();
      сказать('сообщение-входа', '');
      мост.назадСоВхода();
      return;
    }
    открытьЭкранДруга();
  }

  function открытьЭкранВхода() {
    /* «Есть код?» в лобби дурака нажимает эту же кнопку программно, стоя
       на лобби (js/game.js, мост «войтиПоКоду»), — тогда и «Выйти из
       комнаты» после входа должен вернуть в лобби. Пришли сюда вручную,
       с экрана «Игра с другом» («Войти по коду»), — видимый экран будет
       он, и выходить нужно обратно на него, как раньше. Строка тут же,
       а не в отдельной функции: определять источник нужно ДО того, как
       эта же функция сама переключит видимый экран на «экран-входа». */
    const видимый = document.querySelector('.экран.экран--виден');
    путьВКомнату = (видимый && видимый.id === 'экран-лобби') ? 'путь' : 'друг';
    сказать('сообщение-входа', '');
    спрятатьВыходИзОтказа();
    скрытьБеду();
    const поле = узел('поле-кода');
    /* Обычно поле пустое. Но если нас только что не дождались за столом,
       мы сами позвали человека войти заново — и код той самой комнаты
       должен быть уже набран, иначе набирать ему нечего. Подставляем
       один раз: дальше поле ведёт себя как всегда. */
    if (поле) {
      поле.value = кодДляПовторногоВхода;
      кодДляПовторногоВхода = '';
    }
    показатьЭкран('экран-входа');
    if (поле) поле.focus();
  }

  /* Приглашение одноразовое: сработало при открытии страницы — и хватит.
     Иначе человек, вышедший из чужого стола в меню, тут же затягивался бы
     обратно, и уйти оттуда было бы нельзя вовсе. */
  let приглашениеСъедено = false;
  /* Поднимается на один вход: «этот вход — по ссылке, а не по коду руками».
     Читает и гасит его войтиПоКодуНаСервере. */
  let входПоПриглашению = false;
  /* start_param, по которому сейчас входим за стол: отмечается как
     отработанный только после ответа сервера. */
  let ссылкаЖдётОтвета = '';
  /* Номер приглашения из этой ссылки ('' — ссылка старая, без номера). */
  let номерПриглашенияВхода = '';

  /**
   * Нас позвали ссылкой — садимся за стол сами, без набора кода.
   *
   * Зовём это дважды: сразу при запуске и ещё раз, когда страница
   * догрузится. Второй раз нужен на случай, когда код приехал не в адресе
   * страницы, а от скрипта Telegram, — тот подключается позже нас.
   * Повторного входа не будет: приглашение съедается один раз.
   */
  /* Сколько ждём скрипт Telegram, прежде чем войти без имени. Три секунды —
     это уже не загрузка страницы, а что-то неладное, и держать гостя дольше
     нечестно. */
  const ЖДЁМ_TELEGRAM = 3000;

  /**
   * Войти по приглашению — но не раньше, чем появится скрипт Telegram.
   *
   * Ждать приходится вот почему. Наши файлы подключены в конце страницы
   * и выполняются прямо во время её разбора, а telegram-web-app.js стоит
   * с пометкой defer — то есть появляется ПОЗЖЕ нас. Кто поторопится, тот
   * войдёт за стол без имени: спросить его будет не у кого, и друг увидит
   * за столом не «Пётр», а «Игрок 2». Ровно это и случалось: проверка
   * ловила запрос «войти» вообще без имени.
   *
   * Поэтому входим по готовности страницы, а на случай, если та почему-то
   * не догрузится, стоит страховка по времени: лучше сесть за стол
   * безымянным, чем не сесть вовсе. Второй раз вход не случится —
   * приглашение съедается один раз.
   */
  function начатьВходПоПриглашению() {
    if (window.Telegram || document.readyState === 'complete') {
      войтиПоПриглашению();
      return;
    }
    window.addEventListener('load', войтиПоПриглашению);
    setTimeout(войтиПоПриглашению, ЖДЁМ_TELEGRAM);
  }

  function войтиПоПриглашению() {
    if (приглашениеСъедено) return;
    const позвали = приглашениеИзСсылки();
    if (!позвали || !позвали.код) return;
    приглашениеСъедено = true;
    /* Стол другой игры: в комнату шашек дурак не садится. Куда отправить
       человека, решает index.html по «какуюИгруПроситСсылка». */
    if (позвали.игра && позвали.игра !== ИГРА_ЭТОЙ_СТРАНИЦЫ) return;

    // Пришли по ссылке, а не с экрана «Игра с другом» и не с шагов —
    // «Выйти из комнаты» (и «Комната пропала») должны вести в лобби (см.
    // «путьВКомнату» выше), а не на экран, которого этот человек никогда
    // не открывал. Ставим сразу для обеих веток ниже — и для обычного
    // входа, и для «уже сидим, просто перезагрузили страницу».
    путьВКомнату = 'путь';

    /* За этим столом мы уже сидим — просто перезагрузили страницу по той же
       ссылке. Входить заново нельзя: вернуться в свою партию можно только
       по пропуску, и этим займётся обычный возврат с экрана «Игра с другом». */
    const сохранённое = вспомнитьКомнату();
    if (сохранённое && сохранённое.код === позвали.код) {
      открытьЭкранДруга();
      return;
    }

    /* По этой ссылке Telegram в этой сессии уже сажал нас за стол. Он
       держит start_param до закрытия приложения, и человек, вышедший из-за
       стола и вернувшийся в лобби игры с главной, иначе снова садился бы
       за старый стол. Ссылку с кодом в адресе (?code=) не трогаем: её
       открывают нарочно. */
    const параметр = стартовыйПараметр();
    if (параметр && входПоСсылкеУжеБыл(параметр)) return;
    // Отметку ставит ответ сервера (войтиПоКодуНаСервере), не эта строка.
    ссылкаЖдётОтвета = параметр;
    номерПриглашенияВхода = позвали.приглашение || '';

    /* Дальше — то же самое, что делает человек руками: код в поле и «Войти».
       Экран входа открываем без перевода курсора в поле нарочно: набирать
       там нечего, а выехавшая клавиатура закрыла бы пол-экрана вместе
       с ответом сервера. */
    сказать('сообщение-входа', '');
    скрытьБеду();
    const поле = узел('поле-кода');
    if (поле) поле.value = позвали.код;
    показатьЭкран('экран-входа');
    входПоПриглашению = true;
    войтиПоКоду();
  }

  function отменитьКомнату() {
    покинутьПартию();
    сказать('сообщение-друга', '');
    скрытьБеду();
    сказать('сообщение-копирования', '');
    показатьКодКомнаты('');   // чужой старый код в плашке никому не нужен
    // И список тех, кто сидел за покинутым столом, тоже убираем.
    показать('прихожая', false);
    сказать('сообщение-прихожей', '');
    /* Новый путь дурака (лобби → три шага режима «друзья») привёл
       сюда не через «Игра с другом» — значит и «Выйти из комнаты» должен
       вести в лобби, а не на экран, которого человек не открывал. Прежний
       вход с «Игра с другом» ведёт туда же, откуда пришёл, как и раньше.
       Функции «показатьЛоббиДурака» может не быть вовсе — этот файл общий
       для дурака и шашек, а лобби дурака знает только js/game.js дурака. */
    if (путьВКомнату === 'путь' && typeof показатьЛоббиДурака === 'function') {
      показатьЛоббиДурака();
    } else {
      показатьЭкран('экран-друга');
    }
  }

  /**
   * Бросить начатую попытку вернуться в партию. Серверу мы при этом ничего
   * не говорим и ключи возврата не стираем: партия жива, друг за столом,
   * вернуться можно в любой момент. Единственное, что делаем, — помечаем
   * улетевший вопрос о комнате устаревшим, иначе его ответ через секунду
   * затащил бы человека за стол прямо из меню.
   */
  function отменитьВозврат() {
    новоеПоколение();
  }

  /**
   * «Назад» на экране «Игра с другом». Здесь два разных «выхода», и путать
   * их нельзя. За столом кнопка «В меню» — это настоящий уход из партии,
   * и она честно предупреждает, что друг останется один. А на этом экране
   * человек за стол ещё не сел: сюда попадают из меню, и как только возврат
   * удался, экран сам сменяется на стол или на плашку с кодом. Значит,
   * «Назад» здесь означает «передумал возвращаться прямо сейчас» —
   * партию не рвём, ключи оставляем, кнопка возврата в меню остаётся.
   */
  function вернутьсяВМеню() {
    // Если мы всё-таки за столом (так сюда не попасть, но пусть будет
    // надёжно) — это честный выход, и друга надо предупредить.
    if (вПартии || (код && пропуск)) покинутьПартию();
    else отменитьВозврат();
    // Иначе «Возвращаемся в вашу игру…» так и висит на скрытом экране.
    сказать('сообщение-друга', '');
    скрытьБеду();
    обновитьКнопкуВозврата();
    показатьЭкран('экран-меню');
  }

  /* Узлы, которые бывают только у дурака. Это стол компании: боты, кнопка
     «Начать», пересборка и ряды выбора правил. У шашек за столом ровно двое,
     партия начинается сама, и ничего этого на странице нет и не будет.

     Зачем список. Предупреждение о пропавшем узле ловит настоящую беду —
     браузер показывает старую страницу. Но если ругаться на узлы, которых
     у этой игры не бывает, в консоли шашек всегда висят шесть жёлтых строк,
     и настоящее предупреждение в этом шуме уже никто не заметит. Молчим
     о них ровно тогда, когда страница играет не в дурака. */
  const УЗЛЫ_ТОЛЬКО_У_ДУРАКА = [
    'кнопка-посадить-бота', 'кнопка-убрать-бота', 'кнопка-начать-игру',
    'кнопка-пересобрать', 'выбор-мест', 'выбор-перевода', 'выбор-пар'
  ];

  /** Надо ли говорить вслух, что этого узла на странице нет. */
  function молчатьПроУзел(id) {
    return ИГРА_ЭТОЙ_СТРАНИЦЫ !== 'дурак' && УЗЛЫ_ТОЛЬКО_У_ДУРАКА.indexOf(id) !== -1;
  }

  function накнопку(id, действие) {
    const кнопка = узел(id);
    if (!кнопка) {
      if (!молчатьПроУзел(id)) {
        console.warn('Игра вдвоём: не нашёл кнопку «' + id + '». ' +
                     'Скорее всего, браузер показывает старую страницу — обновите её (Ctrl+F5).');
      }
      return;
    }
    кнопка.addEventListener('click', действие);
  }

  /* Узлы, по которым видно: разметка игры с другом на этой странице есть.
     Хватает любого одного — список нарочно из разных углов экрана, чтобы
     он не оказался пустым из-за одной переделки. */
  const ПРИЗНАКИ_РАЗМЕТКИ = [
    'экран-друга', 'кнопка-с-другом', 'кнопка-создать-игру',
    'кнопка-войти-по-коду', 'поле-кода', 'код-комнаты'
  ];

  /**
   * Есть ли на странице разметка игры с другом.
   *
   * Зачем это спрашивать. Предупреждение «не нашёл кнопку» ловит настоящую
   * беду — браузер показал старую страницу, — и отменять его нельзя. Но игр
   * стало две, и страница, которая сетевую часть не показывает вовсе,
   * сыпала бы этими предупреждениями десятками, и в этом шуме настоящее
   * предупреждение никто бы не заметил. Поэтому середина: нет НИ ОДНОГО
   * узла — одна спокойная строка и тишина; есть часть, а часть пропала —
   * ругаемся на каждый пропавший, как раньше.
   */
  function разметкаИгрыСДругомЕсть() {
    return ПРИЗНАКИ_РАЗМЕТКИ.some(function (id) { return Boolean(узел(id)); });
  }

  function подключить() {
    if (!разметкаИгрыСДругомЕсть()) {
      console.log('Игра вдвоём: на этой странице нет разметки игры с другом — ' +
                  'сетевая часть выключена.');
      return;
    }
    накнопку('кнопка-с-другом', открытьЭкранДруга);
    накнопку('кнопка-вернуться-в-игру', нажатиеВозврата);
    накнопку('кнопка-создать-игру', создатьИгру);
    накнопку('кнопка-войти-по-коду', открытьЭкранВхода);
    накнопку('кнопка-друг-назад', вернутьсяВМеню);
    накнопку('кнопка-копировать-код', скопироватьКод);
    накнопку('кнопка-позвать-друга', позватьДруга);
    накнопку('кнопка-комната-отмена', отменитьКомнату);
    накнопку('кнопка-войти', войтиПоКоду);
    накнопку('кнопка-вход-назад', назадСоВхода);
    накнопку('кнопка-посадить-бота', function () {
      действиеПрихожей('бот', 'кнопка-посадить-бота', 'Сажаем бота…');
    });
    накнопку('кнопка-убрать-бота', function () {
      действиеПрихожей('убрать-бота', 'кнопка-убрать-бота', 'Убираем бота…');
    });
    накнопку('кнопка-начать-игру', function () {
      действиеПрихожей('начать', 'кнопка-начать-игру', 'Раздаём карты…');
    });
    /* Возврат в прихожую делает сервер: он убирает ушедших и обнуляет партию,
       а комната остаётся с тем же кодом. Странице после этого ничего делать
       не надо — придёт состояние с этапом «ожидание», и прихожая покажется
       сама, тем же путём, что и в начале игры. */
    накнопку('кнопка-пересобрать', function () {
      действиеПрихожей('пересобрать', 'кнопка-пересобрать', 'Собираем стол…',
                       'сообщение-пересбора');
    });
    накнопку('кнопка-играть-с-ботом', уйтиИгратьСБотом);
    накнопку('кнопка-почему-нет-сервера', переключитьПодробности);
    накнопку('кнопка-адрес-сервера', переключитьНастройкуАдреса);
    накнопку('кнопка-адрес-из-входа', открытьНастройкуСЭкранаВхода);
    накнопку('кнопка-проверить-адрес', function () {
      проверитьАдресСервера('кнопка-проверить-адрес');
    });
    накнопку('кнопка-сохранить-адрес', сохранитьАдресСервера);
    накнопку('кнопка-стереть-адрес', стеретьАдресСервера);

    // Телефон сам сообщает, что связь пропала или вернулась. Это самый
    // быстрый сигнал: ждать, пока оборвётся висящий запрос, не нужно.
    window.addEventListener('offline', function () {
      if (!вПартии) return;
      связьЕсть = false;
      освежитьСтрокуСвязи();
    });
    window.addEventListener('online', function () {
      if (!вПартии || !код || !пропуск) return;
      // Сеть вернулась — не ждём паузы, спрашиваем состояние сразу.
      const моё = поколение;
      запросОтМеня('/состояние', {}).then(function (ответ) {
        // Пока ответ шёл, человек мог выйти и начать новую игру. Тогда это
        // рассказ о брошенной комнате, и показывать его нельзя.
        if (ответУстарел(моё)) return;
        if (!ответ.ок || !ответ.данные.состояние) return;
        связьВернулась();
        принятьСостояние(ответ.данные.состояние);
      });
    });

    const поле = узел('поле-кода');
    if (поле) {
      // Телефон норовит писать строчными и «исправлять» код в слово.
      поле.addEventListener('input', function () {
        const исправленный = очиститьКод(поле.value);
        if (поле.value !== исправленный) поле.value = исправленный;
        // Код меняют руками — прежний отказ мог относиться к старому коду,
        // с новым стоит дать попробовать ещё раз.
        показать('кнопка-войти', true);
      });
      поле.addEventListener('keydown', function (событие) {
        if (событие.key === 'Enter') войтиПоКоду();
      });
    }

    const полеАдреса = узел('поле-адреса');
    if (полеАдреса) {
      полеАдреса.addEventListener('keydown', function (событие) {
        if (событие.key === 'Enter') сохранитьАдресСервера();
      });
    }

    /* В разметке кнопка возврата спрятана. Показать её при первой загрузке
       некому, кроме этой строки: дальше её включает и выключает работа с
       памятью браузера, а перезагрузка страницы — как раз тот случай,
       ради которого кнопку и делали. */
    /* Адрес сервера из ссылки запоминаем сразу при запуске: во второй раз
       игру откроют уже без ссылки, и найти сервер будет негде. */
    запомнитьАдресИзСсылки();
    /* И тихо выясняем, жив ли адрес, лежащий в памяти. Экран этого
       НЕ ждёт: стук уходит в фоне, а страница уже нарисована — так же,
       как это сделано у витрины и рейтинга.

       Зачем это при старте. Спор адресов раньше начинался только при
       нажатии кнопок на экране «Игра с другом». Человек, который зашёл
       на витрину и сразу ушёл в шашки, до этих кнопок не доходил вовсе —
       и на страницу шашек уезжал вчерашний мёртвый адрес из памяти,
       потому что ссылки там уже нет. Игра с другом становилась
       невозможной, а у дурака всё работало.

       Правило внутри самого спора: память освежается, только если
       её адрес умер, а пришедший ссылкой жив (см. освежитьПамятьАдреса). */
    if (естьСпор()) решитьСпорАдресов();
    обновитьКнопкуВозврата();
    // По той же причине показываем вход в настройку адреса, если адрес
    // однажды вписали: после перезагрузки его должно быть где поправить.
    обновитьВходВНастройку();
    /* И по той же — прячем кнопку приглашения: звать друга некуда, пока
       нет кода комнаты. Разметка прячет её и сама, но полагаться на это
       нельзя: класс из разметки легко потерять при первой же переделке
       экрана, а кнопка «Сыграть с другом» без стола ведёт в никуда. */
    обновитьКнопкуПриглашения('');
    // Выбор стола тоже надо показать сразу: без этого человек видит ряды
    // кнопок, ни одна из которых не отмечена, и не понимает, что выбрано.
    подключитьВыборСтола();

    // И последнее: не позвали ли нас ссылкой.
    начатьВходПоПриглашению();
  }

  /* -------------------------------------------------------------------
     Знакомые: с кем уже играли и кто из них сейчас за столом

     Откуда берётся список. Списка друзей Telegram приложению не даёт,
     и это правильно. Поэтому знакомства заводит сам сервер в миг раздачи
     карт: сели за один стол — значит, знакомы. Здесь мы только спрашиваем
     готовый список и приводим его к виду, удобному игре.

     Почему список ещё и запоминается в браузере. Сервер игры домашний,
     он бывает выключен. Показать в такую минуту пустой экран — значит
     соврать: человек прочитает «друзей нет». Поэтому показываем прежний
     список и прямо говорим, что он старый, а «сейчас за столом» в нём
     погашено — этого мы сейчас не знаем.
     ------------------------------------------------------------------- */

  /** Что лежит в памяти браузера: { когда, имена }. Ничего нет — нули. */
  function вспомнитьЗнакомых() {
    try {
      const текст = window.localStorage.getItem(КЛЮЧ_ЗНАКОМЫХ);
      const своё = текст ? JSON.parse(текст) : null;
      if (!своё || !Array.isArray(своё.имена)) return { когда: 0, имена: [] };
      /* Записи бывают двух видов, и оба надо понимать. Раньше в память
         клали одни имена строками; теперь — пару «имя и во что играли».
         Старые записи так и лежат у людей в телефонах, и терять их из-за
         нового поля нельзя: список знакомых опустел бы на ровном месте. */
      const имена = своё.имена
        .map(function (запись) {
          if (typeof запись === 'string') return { имя: запись, игра: '' };
          if (запись && typeof запись === 'object' && typeof запись.имя === 'string') {
            return { имя: запись.имя, игра: игроюСловами(запись.игра) };
          }
          return null;
        })
        .filter(function (запись) { return запись && запись.имя; })
        .slice(0, ЗНАКОМЫХ_В_ПАМЯТИ);
      return { когда: Number(своё.когда) || 0, имена: имена };
    } catch (сбой) {
      // Память запрещена или в ней мусор — считаем, что списка нет.
      return { когда: 0, имена: [] };
    }
  }

  /** Запомнить свежий список. Не легло в память — не беда, молчим. */
  function запомнитьЗнакомых(список) {
    try {
      const имена = список.map(function (друг) {
                            return { имя: друг.имя, игра: друг.игра || '' };
                          })
                          .filter(function (запись) { return Boolean(запись.имя); })
                          .slice(0, ЗНАКОМЫХ_В_ПАМЯТИ);
      window.localStorage.setItem(КЛЮЧ_ЗНАКОМЫХ,
        JSON.stringify({ когда: Date.now(), имена: имена }));
    } catch (сбой) {
      /* Инкогнито или переполненная память: список просто не переживёт
         перезагрузку страницы. Ради этого ничего ломать не станем. */
    }
  }

  /**
   * Ответ «свежего списка не будет»: отдаём то, что помним, и объясняем
   * причину. «Сейчас играет» у всех гасим нарочно — мы этого не знаем,
   * а показать чужое присутствие наугад хуже, чем не показать вовсе.
   */
  function знакомыеИзПамяти(причина, узналиВас) {
    const своё = вспомнитьЗнакомых();
    return {
      знакомые: своё.имена.map(function (запись) {
        /* «Сейчас играет» гасим, а вот во что играли — помним: это
           не сегодняшняя новость, она не устаревает. Ключа для зова
           здесь нет и быть не может: его выдаёт сервер, а он сейчас
           молчит — значит и письмо отправлять некому. */
        return { имя: запись.имя, ключ: '', сейчасИграет: false, игра: запись.игра || '' };
      }),
      свежий: false,
      когда: своё.когда,
      узналиВас: Boolean(узналиВас),
      причина: причина
    };
  }

  /* Во что играли, когда познакомились. Список закрытый нарочно: сюда
     приходит слово с сервера, а всё, что пришло с сервера, показывать
     как есть нельзя. Незнакомое слово превращается в пустоту — строка
     просто останется без подсказки. */
  const НАЗВАНИЯ_ИГР = {
    'дурак': 'дурак',
    'шашки': 'шашки',
    'шахматы': 'шахматы',
    'нарды': 'нарды'
  };

  /** Название игры для показа. Незнакомое или пустое — пустая строка. */
  function игроюСловами(что) {
    const ключ = typeof что === 'string' ? что.trim().toLowerCase() : '';
    return НАЗВАНИЯ_ИГР[ключ] || '';
  }

  /** Привести ответ сервера к своему виду: чужому на слово не верим. */
  function разобратьЗнакомых(данные) {
    const пришло = Array.isArray(данные.знакомые) ? данные.знакомые : [];
    const список = [];
    for (const друг of пришло) {
      if (!друг || typeof друг !== 'object') continue;
      список.push({
        имя: String(друг.имя || '').slice(0, 32),
        /* Ключ — то, чем игра назовёт этого знакомого, когда его позовут
           (см. позватьЗнакомого). Номера Telegram сюда не приходят вовсе,
           и ключ их не заменяет: он живёт, пока жив список, и годится
           только этому серверу. В память браузера он не ложится нарочно —
           вчерашним ключом звать нельзя. */
        ключ: String(друг.ключ || '').slice(0, 64),
        сейчасИграет: друг.сейчасИграет === true,
        /* Во что играли в последний раз. У старых знакомств поле пустое:
           сервер завёл его позже, чем эти люди сели за стол. Пустота —
           не поломка, просто подсказки не будет. */
        игра: игроюСловами(друг.игра)
      });
      if (список.length >= ЗНАКОМЫХ_В_ПАМЯТИ) break;
    }
    return список;
  }

  /**
   * Спросить у сервера список знакомых.
   * Обещание никогда не срывается: при любой беде вернётся прежний список
   * из памяти и причина словами, которую можно показать человеку.
   */
  function списокЗнакомых() {
    const подпись = подписьTelegram();
    // Без подписи сервер нас не узнает — тревожить его незачем.
    if (!подпись) {
      return Promise.resolve(знакомыеИзПамяти(
        'Игра открыта не в Telegram, поэтому узнать, с кем вы играли, не получится.', false));
    }

    return решитьСпорАдресов().then(function () {
      if (бедаАдреса(адресСервера())) {
        /* Два разных случая — два разных объяснения. «Адрес не подходит»
           про пустой адрес было неправдой: адрес не «не подошёл», его
           просто нет, и человек ничего не сделал не так. */
        return знакомыеИзПамяти(адресаНет()
          ? 'Игра не знает адреса сервера. Впишите его на экране «Играть с другом» — ' +
            'и список знакомых вернётся.'
          : 'Сервер игры сейчас не отвечает — спросить не у кого.', false);
      }
      return запрос('/знакомые', { initData: подпись }).then(function (ответ) {
        const данные = (ответ && ответ.данные) || {};

        // Старый сервер про такую дверь не знает и честно отвечает «нет адреса».
        if (ответ.номер === 404) {
          return знакомыеИзПамяти(
            'Сервер игры ещё не умеет показывать знакомых — его надо обновить.', false);
        }
        if (!ответ.ок) {
          return знакомыеИзПамяти(
            'Сервер игры не ответил. Кто из знакомых сейчас за столом — неизвестно.', false);
        }
        if (данные.узналиВас !== true) {
          return знакомыеИзПамяти(
            'Сервер не смог проверить, кто вы, — список показан старый.', false);
        }

        const список = разобратьЗнакомых(данные);
        запомнитьЗнакомых(список);
        return { знакомые: список, свежий: true, когда: Date.now(),
                 узналиВас: true, причина: '' };
      });
    });
  }

  /* -------------------------------------------------------------------
     Позвать знакомого одним нажатием

     Что происходит по нажатию. Если человек ещё не за столом — стол
     создаётся тут же, той же дорогой, что и по кнопке «Создать игру»
     (и человек оказывается в комнате). Дальше собирается обычная
     ссылка-приглашение за этот стол, и сервер просит бота отправить
     знакомому письмо с кнопкой «Войти».

     Кого зовут, игра не знает и знать не должна: номера Telegram сюда
     не приходят вовсе. Есть только «ключ» из свежего списка знакомых —
     слово, которое понимает один наш сервер.

     Обещание не срывается никогда: при любой беде приходит «ок: false»
     и готовая фраза для человека. Слова итога собираются ЗДЕСЬ, одни
     на всех, — их показывает и комната (сообщение под кнопкой), и список
     знакомых на экране «Играть с другом»; разойдись они, человек читал бы
     в двух местах разное об одном и том же.
     ------------------------------------------------------------------- */

  /* Сколько ждём ответ на зов. Сервер успевает сходить в Telegram дважды:
     getMe за именем бота (до пяти секунд, и то лишь однажды — дальше имя
     лежит в памяти сервера) и sendMessage с письмом (тоже до пяти секунд).
     Раньше здесь стояло 8000 — впритык, а при первом зове после
     перезапуска сервера могло не хватить и десяти. Двенадцать секунд —
     запас на оба похода разом, а не только на один. */
  const ЖДЁМ_ЗОВ = 12000;

  /** Отказ одним видом: слова готовы к показу, старый путь предлагаем. */
  function зовНеВышел(причина) {
    return { ок: false, кого: '', словами: причина, причина: причина, можноПоСтаринке: true };
  }

  /**
   * Стол, за который зовём. Уже сидим за своим — берём его; нет — создаём
   * ровно так же, как по кнопке «Создать игру», и оказываемся в комнате.
   */
  function приготовитьСтолДляЗова() {
    if (код) return Promise.resolve({ ок: true });
    return new Promise(function (готово) {
      /* Зовут с экрана «Играть с другом», значит «Выйти из комнаты»
         должен вернуть туда же — как и у кнопки «Создать игру». */
      путьВКомнату = 'друг';
      приВыбранномАдресе(null, function () {
        создатьИгруНаСервере(function (итог) {
          готово(итог.ок
            ? { ок: true }
            : { ок: false, причина: итог.причина || 'Стол создать не вышло.' });
        });
      });
    });
  }

  /** Разобрать ответ сервера на зов. Чужим словам верим только как тексту. */
  function разобратьЗов(ответ, имяИзСписка) {
    const данные = (ответ && ответ.данные) || {};
    if (ответ.номер === 404) {
      return зовНеВышел('Сервер игры ещё не умеет звать письмом — его надо обновить.');
    }
    if (!ответ.ок) {
      return зовНеВышел('Сервер игры не ответил. Попробуйте ещё раз или отправьте ссылку сами.');
    }
    if (данные.ок === true) {
      const кого = String(данные.кого || имяИзСписка || '').slice(0, 32);
      /* Имя стоит после двоеточия нарочно: склонять имена из Telegram мы
         не умеем и не научимся («Позвали Боря» — так писать нельзя, а
         «Борю», «Дмитрия», «Айгуль» одним правилом не получить). */
      return {
        ок: true,
        кого: кого,
        словами: 'Позвали' + (кого ? ': ' + кого : '') +
                 '. Ждём — письмо с кнопкой «Войти» уже отправлено.',
        причина: '',
        можноПоСтаринке: false
      };
    }
    const причина = typeof данные.причина === 'string' && данные.причина
      ? данные.причина
      : 'Позвать письмом не вышло.';
    return {
      ок: false,
      кого: '',
      словами: причина,
      причина: причина,
      можноПоСтаринке: данные.можноПоСтаринке === true
    };
  }

  /**
   * Позвать знакомого письмом. Довод — ключ из свежего списка знакомых;
   * вторым можно передать имя, чтобы оно попало в слова итога, если сервер
   * своего не вернул. Отвечает обещанием { ок, кого, словами, причина,
   * можноПоСтаринке }, которое не срывается.
   */
  function позватьЗнакомого(ключ, имяИзСписка) {
    if (typeof ключ !== 'string' || !ключ) {
      return Promise.resolve(зовНеВышел(
        'Список знакомых устарел — откройте экран заново и позовите ещё раз.'));
    }
    const подпись = подписьTelegram();
    // Без подписи сервер не узнает, кто зовёт, — тревожить его незачем.
    if (!подпись) {
      return Promise.resolve(зовНеВышел(
        'Письмо знакомому отправляет бот, поэтому звать так можно только из Telegram.'));
    }

    return решитьСпорАдресов().then(function () {
      if (бедаАдреса(адресСервера())) {
        return зовНеВышел(адресаНет()
          ? 'Игра не знает адреса сервера. Впишите его на экране «Играть с другом».'
          : 'Сервер игры сейчас не отвечает — позвать некому.');
      }
      return приготовитьСтолДляЗова().then(function (стол) {
        if (!стол.ок) return зовНеВышел(стол.причина);

        const ссылка = ссылкаПриглашения(код);
        /* Бот рассылает только телеграмные ссылки — обычную ссылку
           на страницу сервер не примет и будет прав. */
        if (!ссылка || !этоСсылкаВTelegram(ссылка)) {
          return зовНеВышел('Ссылку за стол собрать не вышло. Продиктуйте другу код: ' + код);
        }
        return запрос('/позвать',
          // Код своего стола — отдельным полем: сервер сверяет его со столом
          // в самой ссылке и с тем, что зовущий и правда сейчас за столом.
          { initData: подпись, ключ: ключ, ссылка: ссылка, код: код }, ЖДЁМ_ЗОВ)
          .then(function (ответ) {
            return разобратьЗов(ответ, имяИзСписка);
          });
      });
    }).then(function (итог) {
      /* Говорим итог в комнате: если стол создался только что, человек
         уже здесь и ждёт ответа именно тут. На экране списка знакомых те же
         слова покажет тот, кто рисует список (js/game.js). */
      сказать('сообщение-приглашения', итог.словами);
      return итог;
    });
  }

  /* «Похвастаться победой» здесь больше не живёт: дорога к чату вынесена
     в js/похвастаться.js, потому что нужна и шашкам, а тащить туда весь
     этот файл ради одной кнопки нельзя. Тот файл дополняет тот же объект
     window.Сеть — дверь по-прежнему зовётся Сеть.похвастаться. */

  /* -------------------------------------------------------------------
     Раздача дня: сдать свой итог и узнать, как сыграли остальные

     Одна и та же раздача у всех, кто нажал сегодня, — а сравнить её
     есть с кем только на сервере. Сюда игра приносит результат партии
     (победа/поражение/ничья и число ходов), а получает строку для
     плашки итога: сколько сыграли, сколько выиграли, какое у меня место.
     ------------------------------------------------------------------- */

  /** Пустая сводка с причиной — на все беды один вид ответа. */
  function раздачаДняНеВышла(день, причина) {
    return { ок: false, узналиВас: false, день: день, сыграли: 0, выиграли: 0,
             среднийХодПобедителей: null, моёМесто: null, причина: причина };
  }

  /** Ответ сервера — в свой вид, поле за полем: чужим числам на слово не верим. */
  function разобратьРаздачуДня(данные, день) {
    const число = function (что) { return Number.isInteger(что) && что >= 0 ? что : 0; };
    const местоИлиНичего = function (что) { return Number.isInteger(что) && что > 0 ? что : null; };
    return {
      ок: данные.ок === true,
      узналиВас: данные.узналиВас === true,
      день: typeof данные.день === 'string' ? данные.день : день,
      сыграли: число(данные.сыграли),
      выиграли: число(данные.выиграли),
      среднийХодПобедителей: местоИлиНичего(данные.среднийХодПобедителей),
      моёМесто: местоИлиНичего(данные.моёМесто),
      причина: typeof данные.причина === 'string' ? данные.причина : ''
    };
  }

  /**
   * Сдать итог раздачи дня или спросить сводку.
   *   раздачаДня({ день, исход, ходов }) — записать и получить сводку;
   *   раздачаДня({ день })               — только сводка.
   * Обещание никогда не срывается: при любой беде приходит пустая сводка
   * и причина словами.
   */
  function раздачаДня(что) {
    const просьба = что && typeof что === 'object' ? что : {};
    // Игра у себя зовёт этот день «дата» — принимаем оба слова, чтобы не спорить.
    const день = typeof просьба.день === 'string' ? просьба.день
               : (typeof просьба.дата === 'string' ? просьба.дата : '');
    const сдаём = просьба.исход !== undefined;
    const подпись = подписьTelegram();

    if (сдаём && !подпись) {
      return Promise.resolve(раздачаДняНеВышла(день,
        'Результат раздачи дня записывается только в Telegram.'));
    }

    return решитьСпорАдресов().then(function () {
      if (бедаАдреса(адресСервера())) {
        return раздачаДняНеВышла(день, адресаНет()
          ? 'Игра не знает адреса сервера — впишите его на экране «Играть с другом».'
          : 'Сервер игры сейчас не отвечает — сравнить не с кем.');
      }
      const тело = { день: день };
      if (подпись) тело.initData = подпись;
      if (сдаём) {
        тело.исход = просьба.исход;
        тело.ходов = просьба.ходов;
      }
      return запрос('/раздача-дня', тело).then(function (ответ) {
        if (ответ.номер === 404) {
          return раздачаДняНеВышла(день, 'Сервер игры ещё не умеет раздачу дня — его надо обновить.');
        }
        if (!ответ.ок || !ответ.данные || typeof ответ.данные !== 'object') {
          return раздачаДняНеВышла(день, 'Сервер игры не ответил — сравнить пока не с кем.');
        }
        return разобратьРаздачуДня(ответ.данные, день);
      });
    });
  }

  /* -------------------------------------------------------------------
     Билет на партию с ботом: очки рейтинга за игру, которую сервер не видит

     Партия с ботом идёт целиком в браузере — сервер её не видит. Поэтому
     ДО партии берём билет (кто играет, во что, против какого бота), а
     ПОСЛЕ — сдаём билет вместе с исходом и получаем прибавку к рейтингу.
     Честно про то, что это даёт и чего не даёт, — в server/билеты.js.
     Обе двери, как и раздача дня, никогда не срываются: любая беда —
     тихий отказ словами, партию это не задерживает и не останавливает.
     ------------------------------------------------------------------- */

  /** Пустой отказ на билет — один вид на все беды. */
  function билетНеВышел(причина) {
    return { ок: false, билет: '', партияНеКорочеСекунд: 0, причина: причина };
  }

  /** Пустой отказ на сдачу билета — тот же приём, что у «билетНеВышел». */
  function итогСБотомНеВышел(причина) {
    return { ок: false, очков: 0, причина: причина };
  }

  /**
   * Взять билет на партию с ботом: { игра, уровень } → Promise
   *   { ок, билет, партияНеКорочеСекунд, причина }.
   * Обещание никогда не срывается. Нет Telegram, нет адреса сервера или
   * сервер не ответил — тихий отказ: партия и без билета идёт как обычно,
   * просто без очков в рейтинге.
   */
  function билетНаБота(что) {
    const просьба = что && typeof что === 'object' ? что : {};
    const подпись = подписьTelegram();
    if (!подпись) {
      return Promise.resolve(билетНеВышел('Очки за партии с ботом начисляются только в Telegram'));
    }
    return решитьСпорАдресов().then(function () {
      if (бедаАдреса(адресСервера())) {
        return билетНеВышел(адресаНет()
          ? 'Игра не знает адреса сервера' : 'Сервер игры сейчас не отвечает');
      }
      return запрос('/билет', { initData: подпись, игра: просьба.игра, уровень: просьба.уровень })
        .then(function (ответ) {
          if (ответ.номер === 404) {
            return билетНеВышел('Сервер игры ещё не умеет билеты на партию с ботом — его надо обновить.');
          }
          if (!ответ.ок || !ответ.данные || typeof ответ.данные !== 'object') {
            return билетНеВышел('Сервер игры не ответил');
          }
          const данные = ответ.данные;
          return {
            ок: данные.ок === true,
            билет: typeof данные.билет === 'string' ? данные.билет : '',
            партияНеКорочеСекунд: Number.isInteger(данные.партияНеКорочеСекунд) ? данные.партияНеКорочеСекунд : 0,
            причина: typeof данные.причина === 'string' ? данные.причина : ''
          };
        });
    });
  }

  /**
   * Сдать билет и исход партии с ботом: { билет, исход } → Promise
   *   { ок, очков, причина }.
   * Обещание никогда не срывается — как у «билетНаБота».
   */
  function итогПартииСБотом(что) {
    const просьба = что && typeof что === 'object' ? что : {};
    const подпись = подписьTelegram();
    if (!подпись) {
      return Promise.resolve(итогСБотомНеВышел('Очки за партии с ботом начисляются только в Telegram'));
    }
    return решитьСпорАдресов().then(function () {
      if (бедаАдреса(адресСервера())) {
        return итогСБотомНеВышел(адресаНет()
          ? 'Игра не знает адреса сервера' : 'Сервер игры сейчас не отвечает');
      }
      return запрос('/итог-с-ботом', { initData: подпись, билет: просьба.билет, исход: просьба.исход })
        .then(function (ответ) {
          if (ответ.номер === 404) {
            return итогСБотомНеВышел('Сервер игры ещё не умеет билеты на партию с ботом — его надо обновить.');
          }
          if (!ответ.ок || !ответ.данные || typeof ответ.данные !== 'object') {
            return итогСБотомНеВышел('Сервер игры не ответил');
          }
          const данные = ответ.данные;
          return {
            ок: данные.ок === true,
            очков: Number.isInteger(данные.очков) ? данные.очков : 0,
            причина: typeof данные.причина === 'string' ? данные.причина : ''
          };
        });
    });
  }

  /* -------------------------------------------------------------------
     Найти игру: список открытых столов и посадка за один из них

     «Открытый стол» — тот, который хозяин пометил общим при создании
     (сервер, дверь /создать, поле «открытый»). Список короткий: сколько
     мест, кто уже сидит, сколько стол ждёт. Кода комнаты в нём нет —
     сервер меняет его на одноразовый ключ (см. server/сервер.js), и садимся
     мы по этому ключу, а не по коду (дверь /сесть). Экран, который всё это
     показывает, живёт отдельным файлом — js/открытые-столы.js.
     ------------------------------------------------------------------- */

  /**
   * Список открытых столов этой игры. Обещание никогда не срывается:
   *   { ок, узналиВас, столы, причина }
   * «столы» — то, что прислал сервер, поле в поле:
   *   { ключ, мест, занято, свободно, игроки: [имена], ботов, ждётСекунд }.
   * Без подписи Telegram сервер никого не узнаёт — списка не будет,
   * и об этом честно говорит «причина».
   */
  function открытыеСтолы() {
    const подпись = подписьTelegram();
    if (!подпись) {
      return Promise.resolve({ ок: false, узналиВас: false, столы: [],
        причина: 'Найти игру можно только в Telegram — откройте игру через бота.' });
    }
    return решитьСпорАдресов().then(function () {
      if (бедаАдреса(адресСервера())) {
        return { ок: false, узналиВас: false, столы: [],
          причина: адресаНет() ? 'Игра не знает адреса сервера.' : 'Сервер игры сейчас не отвечает.' };
      }
      return запрос('/открытые-столы', { initData: подпись, игра: ИГРА_ЭТОЙ_СТРАНИЦЫ }).then(function (ответ) {
        const данные = (ответ && ответ.данные) || {};
        if (ответ.связьСорвалась) {
          return { ок: false, узналиВас: true, столы: [],
            причина: 'Сервер игры не отвечает — список не обновился.' };
        }
        return {
          ок: данные.ок === true,
          узналиВас: данные.узналиВас === true,
          столы: Array.isArray(данные.столы) ? данные.столы : [],
          причина: typeof данные.причина === 'string' ? данные.причина : ''
        };
      });
    });
  }

  /* -------------------------------------------------------------------
     «В друзья» на экране результата — общий помощник для всех игр

     Сервер отдаёт соседей по столу дверью /друзья-за-столом (ключи нужны
     один раз, поэтому их нет в виде стола). По соседу, у которого есть
     ключ и который ещё не друг и не позван, ставим кнопку «В друзья»;
     нажатие шлёт /друзья-позвать с этим ключом. Друг или уже позван —
     вместо кнопки подпись. Любой отказ сервера — просто ничего не ставим:
     дружба — приятная мелочь, и экран результата из-за неё ломаться
     не должен.
     ------------------------------------------------------------------- */

  const ПОДПИСЬ_СТАТУСА_ДРУГА = { 'друг': 'В друзьях', 'позван': 'Позван' };

  /** Подпись «Имя: слова» — при нескольких соседях видно, кто есть кто. */
  function сИменем(имя, слова) {
    return имя ? имя + ': ' + слова : слова;
  }

  /** Подпись вместо кнопки: друг или уже позван. */
  function подписьДруга(имя, статус) {
    const подпись = document.createElement('p');
    подпись.className = 'сеть-сообщение';
    подпись.textContent = сИменем(имя, ПОДПИСЬ_СТАТУСА_ДРУГА[статус]);
    return подпись;
  }

  /** Кнопка «В друзья» по ключу соседа. */
  function кнопкаДруга(имя, ключ) {
    const кнопка = document.createElement('button');
    кнопка.type = 'button';
    кнопка.className = 'кнопка';
    кнопка.textContent = сИменем(имя, 'В друзья');
    let идёт = false;
    кнопка.addEventListener('click', function () {
      if (идёт) return;
      идёт = true;
      кнопка.disabled = true;
      запрос('/друзья-позвать', { initData: подписьTelegram(), ключ: ключ }).then(function (ответ) {
        идёт = false;
        const данные = (ответ && ответ.данные) || {};
        if (ответ.ок && данные.ок === true) {
          // Сервер мог сразу оформить дружбу — если и сосед звал нас.
          кнопка.textContent = сИменем(имя, данные.статус === 'друг' ? 'В друзьях' : 'Позван');
          return;
        }
        кнопка.disabled = false;
        кнопка.textContent = сИменем(имя, 'Не вышло — ещё раз');
      });
    });
    return кнопка;
  }

  /**
   * Поставить в «куда» (пустой узел на экране результата) по строке на
   * соседа: кнопку «В друзья» или подпись «В друзьях»/«Позван». Прежнее
   * содержимое «куда» заменяется. Обещание не срывается и отвечает,
   * сколько строк поставлено (0 — нечего показывать или сервер отказал).
   */
  function кнопкаВДрузья(куда) {
    if (!куда) return Promise.resolve(0);
    /* Прежние строки (от прошлой партии) убираем при любом отказе:
       кнопка с чужим ключом не должна пережить стол, к которому относилась. */
    const очистить = function () { куда.textContent = ''; return 0; };
    const подпись = подписьTelegram();
    if (!код || !пропуск || !подпись) return Promise.resolve(очистить());
    const моё = поколение;
    return запросОтМеня('/друзья-за-столом', { initData: подпись }).then(function (ответ) {
      // Устаревший ответ не трогает гнездо: его мог уже заполнить новый стол.
      if (ответУстарел(моё)) return 0;
      if (!ответ.ок || ответ.номер !== 200) return очистить();
      const места = ответ.данные && Array.isArray(ответ.данные.места) ? ответ.данные.места : [];
      очистить();
      let поставлено = 0;
      for (const сосед of места) {
        if (!сосед || typeof сосед !== 'object') continue;
        const имя = typeof сосед.имя === 'string' ? сосед.имя : '';
        const ключ = typeof сосед.ключ === 'string' ? сосед.ключ : '';
        let строка = null;
        if (сосед.статус === 'друг' || сосед.статус === 'позван') строка = подписьДруга(имя, сосед.статус);
        else if (ключ) строка = кнопкаДруга(имя, ключ);
        if (!строка) continue;       // бот или гость без ключа — звать некого
        куда.appendChild(строка);
        поставлено++;
      }
      return поставлено;
    }, очистить);
  }

  /** Отказ «сесть» или «создать открытый стол» одним видом — слова готовы к показу. */
  function открытыйСтолНеВышел(причина) {
    return { ок: false, причина: причина };
  }

  /**
   * Сесть за стол из списка «Открытые столы» — ключ берём из ответа
   * «открытыеСтолы». Ведёт в комнату ТЕМ ЖЕ путём, что вход по коду
   * (см. «начатьЖизньВКомнате» выше): второй дороги в комнату не заводим.
   * Обещание никогда не срывается: { ок: true } — уже за столом,
   * { ок: false, причина } — нет, причина готова к показу человеку.
   */
  function сестьЗаСтол(ключ) {
    const подпись = подписьTelegram();
    if (!подпись) {
      return Promise.resolve(открытыйСтолНеВышел('Сесть за стол можно только из Telegram.'));
    }
    if (входимВИгру || создаёмИгру) {
      return Promise.resolve(открытыйСтолНеВышел('Уже входим в игру — подождите.'));
    }
    return решитьСпорАдресов().then(function () {
      if (бедаАдреса(адресСервера())) {
        return открытыйСтолНеВышел(адресаНет() ? 'Игра не знает адреса сервера.' : 'Сервер игры сейчас не отвечает.');
      }

      входимВИгру = true;
      const моё = новоеПоколение();
      const тело = { initData: подпись, ключ: ключ, метка: имяВкладки };
      const имя = имяИгрока();
      if (имя) тело.имя = имя;

      return запрос('/сесть', тело).then(function (ответ) {
        входимВИгру = false;
        if (ответУстарел(моё)) return открытыйСтолНеВышел('Ответ опоздал — попробуйте ещё раз.');
        if (ответ.связьСорвалась) {
          return открытыйСтолНеВышел('Сервер игры не отвечает — сесть не вышло.');
        }
        const данные = ответ.данные || {};
        if (!ответ.ок || !данные.пропуск) {
          // Причина словами — та же, что при входе по коду (СЛОВА_ОТКАЗА_ВХОДА).
          const отказ = открытыйСтолНеВышел(словаОтказаВхода(данные.почему) ||
            (typeof данные.ошибка === 'string' && данные.ошибка
              ? данные.ошибка : 'Сесть за стол не вышло — попробуйте другой.'));
          if (словаОтказаВхода(данные.почему)) отказ.почему = данные.почему;
          return отказ;
        }
        /* Пришли не через «Игра с другом» — «Выйти из комнаты» должен вести
           в лобби, а не на чужой экран (см. «путьВКомнату» выше). */
        путьВКомнату = 'путь';
        начатьЖизньВКомнате(данные.код, данные.пропуск, данные.состояние);
        return { ок: true };
      });
    });
  }

  /**
   * Создать открытый стол этой игры — тем же приёмом, что «Создать игру»
   * (см. «создатьИгруНаСервере» выше): то же тело запроса, только с признаком
   * «открытый», и та же дорога в комнату — «начатьЖизньВКомнате». Второго
   * пути создания комнаты не заводим.
   * Обещание никогда не срывается: { ок: true } — уже в комнате,
   * { ок: false, причина }.
   */
  function создатьОткрытыйСтол() {
    const подпись = подписьTelegram();
    if (!подпись) {
      return Promise.resolve(открытыйСтолНеВышел('Создать открытый стол можно только в Telegram.'));
    }
    if (создаёмИгру || входимВИгру) {
      return Promise.resolve(открытыйСтолНеВышел('Уже создаём стол — подождите.'));
    }
    return решитьСпорАдресов().then(function () {
      if (бедаАдреса(адресСервера())) {
        return открытыйСтолНеВышел(адресаНет() ? 'Игра не знает адреса сервера.' : 'Сервер игры сейчас не отвечает.');
      }

      создаёмИгру = true;
      const моё = новоеПоколение();
      const тело = телоСоздания();   // то же, что у «Создать игру» — плюс признак ниже
      тело.открытый = true;

      return запрос('/создать', тело).then(function (ответ) {
        создаёмИгру = false;
        if (ответУстарел(моё)) return открытыйСтолНеВышел('Ответ опоздал — попробуйте ещё раз.');
        if (ответ.связьСорвалась) {
          return открытыйСтолНеВышел('Сервер игры не отвечает — стол не создан.');
        }
        if (!ответ.ок || !ответ.данные.код) {
          return открытыйСтолНеВышел(ответ.данные.ошибка || 'Сервер не смог создать стол.');
        }
        путьВКомнату = 'путь';
        начатьЖизньВКомнате(ответ.данные.код, ответ.данные.пропуск, ответ.данные.состояние);
        return { ок: true };
      });
    });
  }

  /* -------------------------------------------------------------------
     Играть онлайн: сервер сам подбирает соперника

     В отличие от «Найти игру» выше (человек сам смотрит список и жмёт
     «Сесть»), здесь сервер сводит пару сам: встали в очередь с такими же
     правилами (server/подбор.js) — и как только нашёлся второй, обоих
     сажают за стол без единого действия руками. Не нашёлся никто за
     отведённое сервером время — соперником тихо становится бот: сервер
     отвечает ровно тем же видом «свели», разницы отсюда не видно и
     не должно быть видно (решение штаба, план-онлайн-подбор.md,
     «Открытый вопрос к Э4»).

     Устроено двумя дверями, как и всё сетевое здесь:
       /подбор — встать в очередь, отвечает сразу «свели» или «ждите»;
       /подбор-новости — длинный опрос, тот же приём, что «что нового»
         у стола: запрос висит на сервере, пока пара не сведена или не
         вышло время, тогда отвечает «ничего», и мы спрашиваем снова.
     Экран ожидания (js/подбор-экран.js) крутит опрос сам, вызывая
     «подождатьСоперника» по кругу — здесь только одна попытка, без
     внутреннего цикла, чтобы кнопка «Отменить» могла прервать ожидание
     между попытками, а не посреди уже улетевшего запроса.
     ------------------------------------------------------------------- */

  /* Своя, отдельная от комнатного «поколение» метка: подбор идёт ДО входа
     в комнату, комнатным счётчиком его мешать незачем. Растёт при каждом
     «встать» и «отменить» — старый ответ длинного опроса, помеченный
     прежним числом, отбрасывается молча. */
  let поколениеПодбора = 0;
  let ключОжиданияПодбора = null;   // чем опрашивать сервер, пока ждём
  let ручкаОпросаПодбора = null;    // чем прервать висящий /подбор-новости

  /* Сеть моргнула во время долгого опроса — не беда самого подбора,
     соперника это не отменяет. Просто ждём немного и пробуем тем же
     ключом снова, не заваливая сервер частыми повторами. */
  const ПАУЗА_ПОСЛЕ_СБОЯ_ПОДБОРА = 2000;

  function итогПодбораНеВышел(причина) {
    return { статус: 'ошибка', причина: причина };
  }

  /**
   * Встать в очередь на соперника в игру этой страницы, 1×1 (сперва только
   * дурак — план-онлайн-подбор.md, «Объём подбора»; шашки и нарды
   * добавлены планом штаб/план-подбор-шашки-нарды.md — сервер сам решает
   * игру по полю «игра» в теле запроса). Обещание не срывается:
   *   { статус: 'свели' } — соперник нашёлся сразу, в комнату уже вошли
   *     (через начатьЖизньВКомнате — второй дороги в комнату не заводим);
   *   { статус: 'ждём' } — встали в очередь, дальше зовите
   *     Сеть.подождатьСоперника() по кругу, пока не придёт «свели»;
   *   { статус: 'ошибка', причина } — не вышло, причина готова к показу.
   */
  function встатьВОчередь(настройки) {
    // Новое ожидание по просьбе игрока — право на один тихий повтор снова есть.
    повторПодбораБыл = false;
    return встатьВОчередьНаСервере(настройки);
  }

  /* Ответ «не_найдено» посреди ожидания бывает не только «время вышло»:
     сервер мог уже посадить нас за открытый стол, а ответ потерялся по
     дороге. Сервер 60 секунд помнит, кого посадил, и повторный /подбор
     отдаёт то же место — поэтому один раз молча спрашиваем снова.
     Ровно один: без флага «не_найдено» → /подбор → «не_найдено» крутилось
     бы по кругу. */
  let повторПодбораБыл = false;
  let настройкиПодбора = null;

  /**
   * Ответ сервера про подбор пришёл, когда игрок уже отменил ожидание или
   * встал в очередь заново («моё» поколение подбора устарело) — но сервер
   * мог успеть сделать что-то настоящее ДО того, как узнал про отмену:
   * занять место в очереди или даже посадить нас за стол с чужим соперником.
   * Молча забыть такой ответ — оставить «призрака»: место в очереди никто
   * не освободит (и рано или поздно оно неожиданно кого-то сведёт), а стол,
   * за который уже посадили, никто не покинет — соперник сядет напротив
   * пустого места. Оба запроса — тихие, без ожидания ответа: закрыть
   * призрака важнее, чем знать, получилось ли (как и уход в покинутьПартию).
   * Ветка «ждёт» отвечает только устаревшему /подбор — сам /подбор-новости
   * такого статуса наружу не отдаёт (сервер там либо сажает за стол сразу,
   * либо говорит «не_найдено»/«ничего не изменилось»), но проверку
   * оставляем как защиту на случай, если это когда-нибудь изменится.
   */
  function убратьПризракПодбора(данные) {
    if (!данные) return;
    if (данные.статус === 'ждёт' && данные.ключОжидания) {
      запрос('/подбор-отмена', { ключОжидания: данные.ключОжидания });
      return;
    }
    if (данные.статус === 'свели' && данные.код && данные.пропуск) {
      /* Опоздавший ответ мог посадить нас туда же, куда мы уже попали
         другим путём: сервер 60 секунд помнит посадку по паре «человек +
         игра» (см. «повторПодбораБыл» выше), и следующий /подбор отдаёт
         тот же код и пропуск. Тогда это не призрак, а живая комната, в
         которой мы уже сидим, — тихий /выйти выбросил бы нас из
         собственной партии. */
      if (данные.код === код && данные.пропуск === пропуск) return;
      /* Ответы на независимые запросы приходят в любом порядке: опоздавший
         ответ мог обогнать ответ нового /подбор, который вот-вот вернёт тот
         же стол (сервер помнит посадку). Код ещё не выставлен, сверка выше
         не совпала — но выйти сейчас значит выгнать себя из стола, который
         нам сейчас отдадут. Решение откладываем до ответа нового /подбор. */
      if (висящийПодбор) {
        висящийПодбор.отложенныеВыходы.push({ статус: 'свели', код: данные.код, пропуск: данные.пропуск });
        return;
      }
      // Тем же путём, что обычный выход (см. покинутьПартию), но тихо:
      // на экране эта комната никогда не появлялась — сказать другу, что
      // мы вышли, там некому, а сервер должен знать, что место свободно.
      запрос('/выйти', { код: данные.код, пропуск: данные.пропуск });
    }
  }

  /* Самый свежий /подбор, ответа на который ещё нет (null — такого нет).
     Пока он летит, тихие /выйти по опоздавшим ответам копятся в его
     «отложенныеВыходы» и решаются, когда он ответит (см. выше). */
  let висящийПодбор = null;

  /**
   * Новый /подбор ответил (или так и не ушёл) — решаем отложенные выходы.
   * Каждый проходит через убратьПризракПодбора заново: вернул сервер тот
   * же стол — код уже выставлен, выходить не нужно; другой стол, отказ,
   * обрыв или отмена — /выйти по старому коду; успел улететь ещё более
   * новый /подбор — выход откладывается уже до него, а не теряется.
   * Один и тот же стол мог отложиться дважды — /выйти по нему шлём раз.
   */
  function решитьОтложенныеВыходы(список) {
    const уже = {};
    список.forEach(function (данные) {
      const метка = данные.код + '|' + данные.пропуск;
      if (уже[метка]) return;
      уже[метка] = true;
      убратьПризракПодбора(данные);
    });
  }

  function встатьВОчередьНаСервере(настройки) {
    настройкиПодбора = настройки || null;
    const подпись = подписьTelegram();
    if (!подпись) {
      return Promise.resolve(итогПодбораНеВышел(
        'Играть онлайн можно только в Telegram — откройте игру через бота.'));
    }
    if (входимВИгру || создаёмИгру) {
      return Promise.resolve(итогПодбораНеВышел('Уже входим в игру — подождите.'));
    }
    /* Висящим считаем с этой минуты, а не с ухода fetch: опоздавший ответ
       может прийти, пока мы ещё выясняем адрес сервера. */
    const мойПодбор = { отложенныеВыходы: [] };
    висящийПодбор = мойПодбор;
    function отпуститьПодбор() {
      if (висящийПодбор === мойПодбор) висящийПодбор = null;
    }
    function закончитьПодбор() {
      отпуститьПодбор();
      решитьОтложенныеВыходы(мойПодбор.отложенныеВыходы.splice(0));
    }
    return решитьСпорАдресов().then(function () {
      if (бедаАдреса(адресСервера())) {
        return итогПодбораНеВышел(адресаНет()
          ? 'Игра не знает адреса сервера.' : 'Сервер игры сейчас не отвечает.');
      }

      const моё = ++поколениеПодбора;
      ключОжиданияПодбора = null;
      const переводной = Boolean(настройки && настройки.переводной);
      const тело = { initData: подпись, переводной: переводной, метка: имяВкладки };
      тело.игра = ИГРА_ЭТОЙ_СТРАНИЦЫ;
      const имя = имяИгрока();
      if (имя) тело.имя = имя;

      return запрос('/подбор', тело).then(function (ответ) {
        отпуститьПодбор();
        if (моё !== поколениеПодбора) {
          // Свой призрак — в общий список с отложенными: одним разбором
          // в закончитьПодбор, чтобы /выйти по одному столу не ушёл дважды.
          if (ответ.данные) мойПодбор.отложенныеВыходы.unshift(ответ.данные);
          return итогПодбораНеВышел('Подбор отменён.');
        }
        if (ответ.связьСорвалась) {
          return итогПодбораНеВышел('Сервер игры не отвечает — подбор не начался.');
        }
        const данные = ответ.данные || {};
        if (данные.ок === false) {
          return итогПодбораНеВышел(данные.причина || 'Играть онлайн сейчас не вышло.');
        }
        if (данные.статус === 'свели' && данные.код && данные.пропуск) {
          путьВКомнату = 'путь';
          начатьЖизньВКомнате(данные.код, данные.пропуск, данные.состояние);
          return { статус: 'свели' };
        }
        if (данные.статус === 'ждёт' && данные.ключОжидания) {
          ключОжиданияПодбора = данные.ключОжидания;
          return { статус: 'ждём' };
        }
        return итогПодбораНеВышел('Сервер не ответил про подбор.');
      });
    }).then(function (итог) {
      // Уже после разбора ответа: если он посадил за стол, код выставлен,
      // и отложенный выход в этот же стол не уйдёт.
      закончитьПодбор();
      return итог;
    }, function (сбой) {
      закончитьПодбор();
      throw сбой;
    });
  }

  /**
   * Один шаг ожидания — длинный опрос /подбор-новости. Зовать по кругу,
   * пока не придёт «свели» или «ошибка»; «ждём» значит «спросите ещё раз
   * прямо сейчас», пауза (если нужна) уже выдержана внутри. Обещание
   * не срывается.
   */
  function подождатьСоперника() {
    if (!ключОжиданияПодбора) {
      return Promise.resolve(итогПодбораНеВышел('Подбор не запущен.'));
    }
    const моё = поколениеПодбора;
    const свойКлюч = ключОжиданияПодбора;
    const ручка = { прервать: null };
    ручкаОпросаПодбора = ручка;

    return запрос('/подбор-новости', { ключОжидания: свойКлюч }, ОЖИДАНИЕ_ОПРОСА, ручка)
      .then(function (ответ) {
        if (моё !== поколениеПодбора) {
          убратьПризракПодбора(ответ.данные);
          return { статус: 'отменено' };
        }
        if (ответ.связьСорвалась) {
          return new Promise(function (готово) {
            setTimeout(function () { готово({ статус: 'ждём' }); }, ПАУЗА_ПОСЛЕ_СБОЯ_ПОДБОРА);
          });
        }
        const данные = ответ.данные || {};
        if (данные.изменилось === false) {
          return { статус: 'ждём' };   // вышло время опроса — обычное дело, спрашиваем снова
        }
        if (данные.ок === false) {
          ключОжиданияПодбора = null;
          return итогПодбораНеВышел(данные.причина || 'Играть онлайн сейчас не вышло.');
        }
        if (данные.статус === 'не_найдено') {
          ключОжиданияПодбора = null;
          if (!повторПодбораБыл) {
            повторПодбораБыл = true;
            return встатьВОчередьНаСервере(настройкиПодбора);
          }
          return итогПодбораНеВышел('Ожидание закончилось — попробуйте ещё раз.');
        }
        if (данные.статус === 'свели' && данные.код && данные.пропуск) {
          ключОжиданияПодбора = null;
          путьВКомнату = 'путь';
          начатьЖизньВКомнате(данные.код, данные.пропуск, данные.состояние);
          return { статус: 'свели' };
        }
        return { статус: 'ждём' };
      });
  }

  /**
   * Отменить ожидание — кнопка «Отменить» на экране подбора. Прерывает
   * висящий длинный опрос сразу (иначе «Отменить» ждало бы до 40 секунд)
   * и сообщает серверу, что место в очереди больше не нужно. Обещание
   * не срывается: { ок: true } всегда, кроме случая, когда отменять
   * уже нечего — тогда { ок: false }.
   */
  function отменитьПодбор() {
    поколениеПодбора++;   // всё, что ещё летит, теперь устарело
    if (ручкаОпросаПодбора && ручкаОпросаПодбора.прервать) ручкаОпросаПодбора.прервать();
    ручкаОпросаПодбора = null;
    const ключ = ключОжиданияПодбора;
    ключОжиданияПодбора = null;
    if (!ключ) return Promise.resolve({ ок: false });
    return запрос('/подбор-отмена', { ключОжидания: ключ }).then(function (ответ) {
      const данные = ответ.данные || {};
      return { ок: данные.ок === true };
    });
  }

  /* -------------------------------------------------------------------
     Наружу — только то, чем пользуется js/game.js
     ------------------------------------------------------------------- */

  /* Объект дополняем, а не заводим заново: js/похвастаться.js кладёт в тот
     же window.Сеть свою дверь, и подключаться он может как до этого файла,
     так и после. Перезапись стёрла бы её молча. */
  window.Сеть = Object.assign(window.Сеть || {}, {
    /**
     * Комната со столом с шагов дурака: { мест, переводной, парами }.
     * Обещание не срывается — см. «создатьКомнатуСоСтолом».
     */
    создатьКомнату: создатьКомнатуСоСтолом,

    /**
     * Список открытых столов этой игры — экран «Найти игру»
     * (js/открытые-столы.js). Обещание не срывается — см. «открытыеСтолы».
     */
    открытыеСтолы: открытыеСтолы,

    /**
     * Сесть за стол из этого списка — экран «Найти игру».
     * Обещание не срывается — см. «сестьЗаСтол».
     */
    сестьЗаСтол: сестьЗаСтол,

    /**
     * Открыть свой стол для всех — кнопка «Создать открытый стол» на пустом
     * экране «Найти игру». Обещание не срывается — см. «создатьОткрытыйСтол».
     */
    создатьОткрытыйСтол: создатьОткрытыйСтол,

    /**
     * Встать в очередь на соперника — экран «Ищем соперника»
     * (js/подбор-экран.js). Обещание не срывается — см. «встатьВОчередь».
     */
    встатьВОчередь: встатьВОчередь,

    /**
     * Один шаг ожидания соперника — звать по кругу, пока не «свели»
     * или «ошибка». Обещание не срывается — см. «подождатьСоперника».
     */
    подождатьСоперника: подождатьСоперника,

    /**
     * Отменить ожидание — кнопка «Отменить». Обещание не срывается —
     * см. «отменитьПодбор».
     */
    отменитьПодбор: отменитьПодбор,

    /**
     * Отправить намерение игрока. Обещание никогда не срывается:
     * при любой беде вернётся { ошибкаСвязи: true }, и игра не сломается.
     */
    отправитьХод: function (намерение) {
      if (!код || !пропуск) {
        return Promise.resolve({ принято: false, причина: 'Вы сейчас не в игре с другом' });
      }
      /* Связь уже оборвана, и мы это знаем — ход в никуда не отправляем.
         Иначе каждое нажатие висело бы десять секунд и заканчивалось ничем:
         пока туннель мёртв, запрос всё равно упрётся в ожидание. Лучше
         ответить сразу и словами. Ждать не придётся долго — опрос стучится
         в сервер сам и вернёт игру в строй, как только связь появится. */
      if (!связьЕсть) {
        return Promise.resolve({ принято: false,
          причина: 'Связь с игрой потеряна — ход не отправлен. ' +
                   'Как только связь вернётся, можно будет сходить снова.' });
      }
      const моё = поколение;
      return запросОтМеня('/ход', намерение || {}).then(function (ответ) {
        // Ответ мог опоздать: человек уже вышел и сел за новый стол.
        // Особенно опасен запоздавший «комнаты нет» — он выбросил бы
        // игрока из свежей партии, а друг остался бы за столом один.
        // Пустой ответ игра переживает: она проверяет его на «ничего».
        if (ответУстарел(моё)) return;
        if (ответ.связьСорвалась) {
          связьПотеряна();
          return { ошибкаСвязи: true };
        }
        if (ответ.номер === 404) {
          потерялиКомнату(ответ);
          return { ошибкаСвязи: true };
        }
        связьВернулась();
        if (ответ.данные.состояние) принятьСостояние(ответ.данные.состояние);
        return {
          принято: Boolean(ответ.данные.принято),
          причина: ответ.данные.причина || ответ.данные.ошибка || null
        };
      });
    },

    /**
     * Послать за стол знак внимания — смайлик или готовую фразу.
     * Наружу уходит только НОМЕР из списка правил: свободного текста
     * в этой переписке нет вовсе, поэтому и чистить нечего.
     *
     * Обещание никогда не срывается: при любой беде вернётся отказ
     * с причиной, которую можно показать человеку прямо на кнопке.
     */
    послатьЭмоцию: function (номер, цель) {
      if (!код || !пропуск) {
        return Promise.resolve({ принято: false, причина: 'Вы сейчас не в игре с другом' });
      }
      /* Старый сервер про эмоции не знает и ответит на них невнятным
         отказом про ход. Молчащая или странно отвечающая кнопка — худший
         исход, поэтому говорим прямо, что дело в сервере, а не в игроке. */
      if (!эмоцииРаботают) {
        return Promise.resolve({ принято: false,
          причина: 'Этот сервер ещё не умеет эмоции — обновите его и перезапустите' });
      }
      if (!связьЕсть) {
        return Promise.resolve({ принято: false,
          причина: 'Связь потеряна — смайлик не ушёл. Попробуйте ещё раз, когда связь вернётся' });
      }

      /* Цель — в кого бросить: имя игрока за столом или номер его кресла.
         Нужна только броскам; смайлику и фразе сервер её не ищет. Без цели
         поле не шлём вовсе — старый сервер лишнего не увидит. */
      const намерение = { действие: 'эмоция', номер: номер };
      if (цель !== undefined && цель !== null && цель !== '') намерение.цель = цель;
      const моё = поколение;
      return запросОтМеня('/ход', намерение).then(function (ответ) {
        if (ответУстарел(моё)) return;   // человек уже вышел из этой комнаты
        if (ответ.связьСорвалась) {
          связьПотеряна();
          return { принято: false, ошибкаСвязи: true,
                   причина: 'Связь потеряна — смайлик не ушёл' };
        }
        if (ответ.номер === 404) {
          потерялиКомнату(ответ);
          return { принято: false, ошибкаСвязи: true, причина: 'Игра уже закрылась' };
        }
        связьВернулась();
        // Своё же состояние применяем сразу: в нём наш смайлик уже виден.
        if (ответ.данные.состояние) принятьСостояние(ответ.данные.состояние);
        return {
          принято: Boolean(ответ.данные.принято),
          причина: ответ.данные.причина || ответ.данные.ошибка || null
        };
      });
    },

    /**
     * Что умеет сервер по части знаков: { знаки: true, броски: true/false }
     * или false, если не умеет ничего (старый сервер). Прежняя проверка
     * «if (Сеть.эмоцииРаботают())» работает как раньше; про броски —
     * «const умеет = Сеть.эмоцииРаботают(); if (умеет && умеет.броски)».
     */
    эмоцииРаботают: function () { return эмоцииРаботают; },

    /**
     * С кем этот человек уже играл и кто из них сейчас за столом.
     * Обещание никогда не срывается. Что приходит:
     *
     *   знакомые   [ { имя, сейчасИграет, игра } ] — кто играл позже, тот выше;
     *              «игра» — во что играли в последний раз, готовое слово
     *              для показа: «дурак», «шашки», «шахматы», «нарды».
     *              Пустая строка, если игра неизвестна: у знакомств,
     *              заведённых до появления этого поля, её нет, и это
     *              не поломка — подсказки просто не будет;
     *   свежий     true — список только что с сервера; false — из памяти
     *              браузера, и тогда «сейчасИграет» у всех погашено;
     *   когда      время этого списка (мс), 0 — списка нет вовсе;
     *   узналиВас  узнал ли сервер игрока по подписи Telegram;
     *   причина    почему список несвежий — готовая фраза для человека,
     *              пустая строка, когда всё в порядке.
     *
     * Имя может быть и пустым (человек вошёл в Telegram без имени) —
     * тогда показывать его надо своими словами, вроде «Без имени».
     */
    списокЗнакомых: списокЗнакомых,

    /**
     * Позвать знакомого письмом: позватьЗнакомого(ключ, имя).
     * «ключ» — поле из свежего списка знакомых (в списке из памяти его
     * нет, и звать по нему нельзя). Нет своего стола — он создастся сам,
     * и человек окажется в комнате. Обещание не срывается:
     *   ок              письмо ушло — true/false;
     *   кого            имя того, кого позвали;
     *   словами         готовая фраза для человека — и об удаче, и о беде;
     *   можноПоСтаринке стоит ли предложить прежний путь «Сыграть с другом».
     */
    позватьЗнакомого: позватьЗнакомого,

    /**
     * «В друзья» на экране результата: кнопкаВДрузья(узел). В узел встают
     * строки по соседям за столом — кнопка «В друзья» (зовёт
     * /друзья-позвать) или подпись «В друзьях» / «Позван». Содержимое
     * узла заменяется. Обещание не срывается: число поставленных строк,
     * 0 — показывать нечего (не в партии, не в Telegram, сервер отказал).
     */
    кнопкаВДрузья: кнопкаВДрузья,

    /**
     * Раздача дня. Обещание никогда не срывается. Что приходит:
     *   ок                    записали (или сводку отдали) — true/false;
     *   узналиВас             сервер узнал игрока по подписи Telegram;
     *   день                  за какой день сводка, «2026-09-07»;
     *   сыграли, выиграли     сколько человек сыграли эту раздачу и сколько победили;
     *   среднийХодПобедителей за сколько ходов в среднем выигрывали (null — никто);
     *   моёМесто              моё место среди сыгравших (null — нет подписи или не играл);
     *   причина               почему не записали — готовая фраза, '' если всё хорошо.
     * Строка для плашки: «Сегодня эту раздачу выиграли {выиграли} из {сыграли}».
     */
    раздачаДня: раздачаДня,

    /**
     * Билет на партию с ботом — очки рейтинга за игру, которую сервер
     * не видит (см. server/билеты.js). Обещание никогда не срывается:
     *   ок                    билет выдан — true/false;
     *   билет                 сам билет, пустая строка при отказе;
     *   партияНеКорочеСекунд  раньше этого сдавать бессмысленно — не засчитают;
     *   причина               почему отказали — готовая фраза или ''.
     */
    билетНаБота: билетНаБота,

    /**
     * Сдать билет и исход партии с ботом — { билет, исход }.
     * Обещание никогда не срывается:
     *   ок       билет принят и очки начислены — true/false;
     *   очков    сколько прибавилось к рейтингу (0, если не начислено);
     *   причина  почему отказали — готовая фраза или ''.
     */
    итогПартииСБотом: итогПартииСБотом,

    /**
     * Какую игру просит ссылка, по которой открыли страницу: 'шашки',
     * 'дурак' или ''. По ней index.html перебрасывает на страницу шашек
     * с тем же параметром запуска. Про комнату ничего не говорит.
     */
    какуюИгруПроситСсылка: какуюИгруПроситСсылка,

    /**
     * Главная перебрасывает по ссылке — запомнить её, чтобы по той же
     * ссылке (Telegram держит её всю сессию) не перебрасывать второй раз.
     */
    запомнитьПереброску: запомнитьПереброску,

    /**
     * Чистый разбор startapp: { игра, код, адрес, приглашение } или null.
     * И текст зова за стол этой страницы. Обе — для проверок на node
     * (tests/маршрут-приглашения-8-игр.js), в игре их никто не зовёт.
     */
    разобратьПриглашение: разобратьПриглашение,
    текстПриглашения: function () { return ТЕКСТ_ПРИГЛАШЕНИЯ; },

    покинутьПартию: покинутьПартию,

    /** Идёт ли сейчас сетевая партия — нужно для проверок. */
    вИгре: function () { return вПартии; },

    /**
     * Порог мягкой надписи (мс) и сама чистая функция текста по пропаже
     * соперника — нужны для проверок в node без браузера, см.
     * штаб/план-друг-пропал-со-связи.md, этап Э1.
     */
    МЯГКАЯ_ПРОПАЖА: МЯГКАЯ_ПРОПАЖА,
    текстПропажи: текстПропажи,

    /**
     * Настоящий ли код комнаты (а не «код ещё не пришёл») — то же
     * правило, что красит плашку кода и кнопку приглашения. Дверь нужна
     * js/дурак-комната.js, чтобы не держать свою копию регулярки.
     */
    кодНастоящий: кодНастоящий,

    /** Адрес сервера, с которым работаем. Пригодится при разборе жалоб. */
    адрес: адресСервера,

    /**
     * Чистая функция запасного адреса (когда нет ни ссылки, ни вписанного
     * руками) — отдельно от «адрес», чтобы проверки на node могли свериться
     * с правилом по месту (свой компьютер / собственный домен), не разбирая
     * весь спор живого адреса с мёртвым. См. tests/адрес-сервера-по-странице.js.
     */
    запаснойАдрес: запаснойАдрес
  });

  // Разметка к этому времени готова: файл подключён в конце страницы.
  подключить();

})();
